local config = {
  ui_story_5084_50840100_1_dialog_content = "ここは……墓所？",
  ui_story_5084_50840100_2_dialog_content = "「ワラーキ、おまえの運命は示された。だがその心中には迷いがあるようだな。」",
  ui_story_5084_50840100_3_dialog_content = "力には代償――つまり贄となり、不安におびえて過ごす日々――が付きもの。",
  ui_story_5084_50840100_4_dialog_content = "私は、強かったにもかかわらず苦しみ、ワラーキの血を最後の一滴まで流しつくしてようやく安息を得られた両親のようにはなりたくないの。",
  ui_story_5084_50840100_5_dialog_content = "「おまえはワラーキの信者ではない。私と同じ、真理の主だけを信奉する者だ。」",
  ui_story_5084_50840100_6_dialog_content = "「おまえはこの世界を旅することで成長しただろう。ならばおまえは真理の信者だ。」",
  ui_story_5084_50840100_7_dialog_content = "「真理の主の降臨を願うのに、犠牲を恐れるというのか？」",
  ui_story_5084_50840100_8_dialog_content = "私にどうしろというの？",
  ui_story_5084_50840100_9_dialog_content = "「私の力と体を取り戻してくれたら、対価としておまえの力を抜き取り、少し早い眠りに就かせてやろう。」",
  ui_story_5084_50840100_10_dialog_content = "「私はスリルを味わうのが好きなのだ。」",
  ui_story_5084_50840100_11_dialog_content = "「そこには、真理の味が垣間見える。」",
  ui_story_5084_50840100_12_dialog_content = "ビクトリア様、どうされましたか？",
  ui_story_5084_50840100_13_dialog_content = "教典と契約を結んだ時のことが…あの時、この指輪の未来のことは示してくれなかったわ。",
  ui_story_5084_50840100_14_dialog_content = "でも、こうやって私のもとに戻ってきたということは……\n何か、古い力が呼び起こされている気がする。",
  ui_story_5084_50840100_15_dialog_content = "握ってみた時の、懐かしささえ感じるこのとげとげしい痛み……",
  ui_story_5084_50840100_16_dialog_content = "その指輪はあなたと関係が？",
  ui_story_5084_50840100_17_dialog_content = "ワラーキのご先祖の遺物で、真理結社の指導者が代々受け継いできたものよ。",
  ui_story_5084_50840100_18_dialog_content = "持ち主のもとに戻ったのなら、喜ぶべき結末、ということですね。",
  ui_story_5084_50840100_19_dialog_content = "指輪自体がどうこうは関係ない。問題はこれが現れたタイミングよ。",
  ui_story_5084_50840100_20_dialog_content = "聖鳴祭が間近に迫った今になって、\n長い間行方知れずだった指輪が急に私のもとに帰ってきた。",
  ui_story_5084_50840100_21_dialog_content = "…！",
  ui_story_5084_50840100_22_dialog_content = "ビクトリア様！",
  ui_story_5084_50840100_23_dialog_content = "ウハハハッ……ワラーキ……",
  ui_story_5084_50840100_24_dialog_content = "クソッ！ぐっ、うう……！",
  ui_story_5084_50840100_25_dialog_content = "うわあああああ——！！！",
  ui_story_5084_50840100_26_dialog_content = "ビクトリア様！",
  ui_story_5084_50840100_27_dialog_content = "今のは……",
  ui_story_5084_50840100_28_dialog_content = "過去の出来事……いや、「未来」の予言のようでもあったわ……",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>パラパラ…</color>",
  ui_story_5084_50840100_30_dialog_content = "「招かれし変革者。」",
  ui_story_5084_50840100_31_dialog_content = "「墓所は待っている、訪問を。」",
  ui_story_5084_50840100_32_dialog_content = "「確かめる必要がある、真理をどれだけ理解しているか。」",
  ui_story_5084_50840100_33_dialog_content = "「盛典、古き月に出会う。」",
  ui_story_5084_50840100_34_dialog_content = "「時は来た。」",
  ui_story_5084_50840100_35_dialog_content = "…",
  ui_story_5084_50840100_36_dialog_content = "ビクトリア様、今回の啓示はやや曖昧ですね？",
  ui_story_5084_50840100_37_dialog_content = "過去の指輪の予言と合わせて考えると、意味が見えてくるわ。",
  ui_story_5084_50840100_38_dialog_content = "「時は来た。聖鳴祭では予期せぬめぐり逢いがあるだろう。」",
  ui_story_5084_50840100_39_dialog_content = "「真理への理解について確認したいなら、星空の墓所の守り人を訪ねねばならない。」",
  ui_story_5084_50840100_40_dialog_content = "「今回の行動には、空の末裔を伴うこと。」",
  ui_story_5084_50840100_41_dialog_content = "紅血の教典が倒置法を多用して予言するなんて初めてのことね。",
  ui_story_5084_50840100_42_dialog_content = "長らく行方知れずだったこの指輪の啓示は、\nバラバラだった「時」をつなげてくれるみたい。",
  ui_story_5084_50840100_43_dialog_content = "今の話で理解できました。",
  ui_story_5084_50840100_44_dialog_content = "あの瑞々しい血液なんだけど、あなたが連れて来てちょうだい。",
  ui_story_5084_50840100_45_dialog_content = "おおせのままに、ビクトリア様。",
  ui_story_5084_50840100_46_dialog_content = "道々説明は聞いたけど、やっぱり分からないな。\n真理結社の祝典にどうして僕が招待されたの？",
  ui_story_5084_50840100_47_dialog_content = "真理の主とビクトリア様の指示さ。",
  ui_story_5084_50840100_48_dialog_content = "もう…真理結社の人たちはいつもそうやって……",
  ui_story_5084_50840100_49_dialog_content = "影ノ街からずいぶん遠くまで来たけど、ここはどこ？",
  ui_story_5084_50840100_50_dialog_content = "うわっ！！",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>ドテッ――！</color>",
  ui_story_5084_50840100_52_dialog_content = "この真っ黒なやつ……どうやって動いてるの！？",
  ui_story_5084_50840100_53_dialog_content = "誰が起こしに来たのかと思ったら、ボーヤだったのね。",
  ui_story_5084_50840100_54_dialog_content = "……スカーレイ？",
  ui_story_5084_50840100_55_dialog_content = "足にからまったのは君の藤蔓だったの？",
  ui_story_5084_50840100_56_dialog_content = "他人を踏んづけたら謝るのが筋でしょう。なのになによその質問？",
  ui_story_5084_50840100_57_dialog_content = "ご、ごめん……でも、なんでここに？",
  ui_story_5084_50840100_58_dialog_content = "それはこっちのセリフよ。ここに用事でもあるのかしら？",
  ui_story_5084_50840100_59_dialog_content = "全部私のせいです。今日は朝から許されぬ過ちを犯すような気がしていました。",
  ui_story_5084_50840100_60_dialog_content = "スカーレイさんが許可してくださるなら、ここで懺悔したいのですが……",
  ui_story_5084_50840100_61_dialog_content = "ビクトリア様、全員そろいました。",
  ui_story_5084_50840100_62_dialog_content = "ビクトリア様……",
  ui_story_5084_50840100_63_dialog_content = "以前言っていたわよね？時はまだ来ていないから、\n星空の墓所に隠された秘密は私ですらうかがい知れないと。",
  ui_story_5084_50840100_64_dialog_content = "ところが今回、ここを訪れろという啓示を教典から受けたの。",
  ui_story_5084_50840100_65_dialog_content = "今回の遺物は何ですか？",
  ui_story_5084_50840100_66_dialog_content = "これよ。",
  ui_story_5084_50840100_67_dialog_content = "そのような啓示を受けたのなら、\n確かに星空の墓所に真相を探りに行く権利はありますね。",
  ui_story_5084_50840100_68_dialog_content = "星空の墓所ってどんなところ？",
  ui_story_5084_50840100_69_dialog_content = "一般的に言えば、死者が埋まっているところね。",
  ui_story_5084_50840100_70_dialog_content = "！！…ファウスト？……僕は間近に迫った真理結社の祝典のために呼ばれたんだよね！？",
  ui_story_5084_50840100_71_dialog_content = "「間近に迫ったもののため」という意味では合っているわ。",
  ui_story_5084_50840100_72_dialog_content = "落ちついて。そういえば、白夜城のあらゆる財をかき集めても足りないほど高価なものが、中にはあるらしいわ。",
  ui_story_5084_50840100_73_dialog_content = "墓所の秘密を探ろうとした者は数知れない。でも結局はそこで命を落とした。そう思うと、あなたは逆にラッキーなのよ。",
  ui_story_5084_50840100_74_dialog_content = "お宝のためなら何でもやると思ってる！？\nまあでも…お宝なら考えてみてもいいかも…",
  ui_story_5084_50840100_75_dialog_content = "星空の墓所について、伝えておくことが3つあるわ。",
  ui_story_5084_50840100_76_dialog_content = "1つ。「ファリア」は進入者を血のみで識別する。墓所に入れるのは血の誓いを交わした者だけよ。",
  ui_story_5084_50840100_77_dialog_content = "「ファリア」が開けたもう1つの扉は、契約者の導きに従うわ。",
  ui_story_5084_50840100_78_dialog_content = "これが「ファリア」よ。",
  ui_story_5084_50840100_79_dialog_content = "2つ。持ち物にも導くものが存在する。\n持ち物は時間に支配され、時間に従って自らの帰属する場所へと向かうわ。",
  ui_story_5084_50840100_80_dialog_content = "3つ。「運命はすでに刻まれた。もはや質問も憎悪も変転もできぬ。」",
  ui_story_5084_50840100_81_dialog_content = "ボーヤ。聞きたいことだらけ！って顔してるわよ。",
  ui_story_5084_50840100_82_option_content = "血の誓いって？",
  ui_story_5084_50840100_83_dialog_content = "血を取られたりするってこと？",
  ui_story_5084_50840100_84_dialog_content = "偉大なる主よ、この穢れた血でよろしければ、すべて差し上げます……",
  ui_story_5084_50840100_85_option_content = "運命に関して質問できないって、",
  ui_story_5084_50840100_86_dialog_content = "なんだか、時を「ワープ」する小説とかに出てきそうな話だね。",
  ui_story_5084_50840100_87_dialog_content = "不安でいっぱいなのかと思ったら、もう目がキラキラしているわ。",
  ui_story_5084_50840100_88_dialog_content = "ファリア、用意。",
  ui_story_5084_50840100_89_dialog_content = "待って！空の末裔の血でもいけるの？",
  ui_story_5084_50840100_90_dialog_content = "おりゃ――！",
  ui_story_5084_50840100_91_dialog_content = "<size=45>うわっ！！！</size>",
  ui_story_5084_50840100_92_dialog_content = "スカーレイさんがファリアが開くって言ってたでしょうが！",
  ui_story_5084_50840100_93_dialog_content = "ビクトリア様、あたしと「ベビーちゃん」も連れてってください！ちゃんと言うこと聞きますから。",
  ui_story_5084_50840100_94_dialog_content = "あなたが1人でここに来たこと、レノーアは知っているの？",
  ui_story_5084_50840100_95_dialog_content = "もちろんです。お姉ちゃんは「楽しんできて」って言ってました。",
  ui_story_5084_50840100_96_dialog_content = "ベビーちゃんの毛がいっぱいあるから、おっきい傷口でも縫合できますよ！",
  ui_story_5084_50840100_97_dialog_content = "PlayerName、そばにいるんだよ。あたしが面倒見てあげる。",
  ui_story_5084_50840100_98_dialog_content = "にゃ～。",
  ui_story_5084_50840100_99_dialog_content = "君とは離れてた方がいいと思う…",
  ui_story_5084_50840100_100_dialog_content = "みんな準備はできたわね。ファリア、始動！",
  ui_story_5084_50840100_101_dialog_content = "真理の主よ、私を疑問の終着点にお導きください。",
  ui_story_5084_50840100_102_dialog_content = "真理の主よ、どうかこの旅路をお守りください。",
  ui_story_5084_50840100_103_dialog_content = "真理の主よ、私の罪をお裁きください。",
  ui_story_5084_50840100_104_dialog_content = "真理の主よ、メイを楽しい場所にお導きください。",
  ui_story_5084_50840100_105_dialog_content = "服を引っ張らないで…！ちょっと！",
  ui_story_5084_50840100_106_dialog_content = "うう…！",
  ui_story_5084_50840100_107_dialog_content = "スカーレイ…スカーレイ…",
  ui_story_5084_50840100_108_dialog_content = "助けて…",
  ui_story_5084_50840100_109_dialog_content = "ボーヤ、目を閉じて苦しそうなフリをしてるのはなぜ？",
  ui_story_5084_50840100_110_dialog_content = "目を開けて。危険なものなんて何もないわ。",
  ui_story_5084_50840100_111_dialog_content = "そう？…さっき密集した藤蔓が当たったところがかゆくって、\n怖いんだよね…",
  ui_story_5084_50840100_112_dialog_content = "あなた、本当に真理を探求する気ある？……あ、まだ真理結社に入ってなかったっけ？",
  ui_story_5084_50840100_113_dialog_content = "……スカーレイってほんと大雑把だよね。",
  ui_story_5084_50840100_114_dialog_content = "で、みんな一瞬で消えちゃったの？",
  ui_story_5084_50840100_115_dialog_content = "あなたがまだここにいることの方が気になるわ。",
  ui_story_5084_50840100_116_dialog_content = "聞いたことがあると思うけど、真理に近づくには普段の思考は一旦ストップさせて、\n感覚だけであちこち探索する必要があるの。",
  ui_story_5084_50840100_117_dialog_content = "空の末裔なんだから、それは得意なはずよね？",
  ui_story_5084_50840100_118_dialog_content = "あなたはどこにいて、何者で、どこへ行くのか…",
  ui_story_5084_50840100_119_dialog_content = "奥が深いんだね…ファウストになかなか見られない祝典があるって言われたから来ただけなんだけど…",
  ui_story_5084_50840100_120_dialog_content = "なら祝典のことだけ考えてなさいよ。まだ怖いなら、\n藤蔓の中から燭台を引っ張り出すといいわ。",
  ui_story_5084_50840100_121_dialog_content = "燭台…",
  ui_story_5084_50840100_122_dialog_content = "ほ、ホントにあった…",
  ui_story_5084_50840100_123_dialog_content = "それがあなたを導いてくれる。でも調子に乗らないことね。\nロウソクが燃え尽きる前に戻ってくること。",
  ui_story_5084_50840100_124_dialog_content = "でも戻るって…どうやって？というかどこに戻るの？",
  ui_story_5084_50840100_125_dialog_content = "……スカーレイ？",
  ui_story_5084_50840100_126_dialog_content = "スカーレイ！",
  ui_story_5084_50840201_1_dialog_content = "（スカーレイから燭台をもらってよかった。暗すぎるんだよね…）",
  ui_story_5084_50840201_2_dialog_content = "（みんなどこにいるんだろう…）",
  ui_story_5084_50840201_3_dialog_content = "…ここは？",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>夜闇には赤い月が浮かんでいる。古時計が鳴り響き、そびえ立つ時計台が赤い月に向かってぐんぐん伸びていった</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>それは、信者たちに踏まれた一つ一つの石ころ、精緻な模様が施された扉の枠や壁まで照らした</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>そして真理の殿堂での懺悔に耳を傾け、血の一族の栄光と秘密について語らんとしている…</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>ぴょん、ぴょん――</color>",
  ui_story_5084_50840201_8_dialog_content = "床も壁も本物だ…不思議だなあ！",
  ui_story_5084_50840201_9_dialog_content = "真実の館とも違うけど、外にいる人には、\nここでなにが起きてるかまったく分からないんじゃないかな…",
  ui_story_5084_50840201_10_dialog_content = "あ、赤い月が出てきたぞ。3年に1度の聖鳴祭の巡行はもうすぐだ。",
  ui_story_5084_50840201_11_dialog_content = "何を祈るかはもう考えてある。\n巡行の間、全身全霊で唱えて真理の主に聞いていただくんだ。",
  ui_story_5084_50840201_12_dialog_content = "巡行で唱えるだけじゃ役に立たない。「啓示を受けし者」に選ばれないと。\n自分をいけにえにしてこそ、真理の主は祈りを聞き届けてくださる。",
  ui_story_5084_50840201_13_dialog_content = "ワラーキ村…ここで真理結社の祝典があるのかな？聖鳴祭とか…巡行とか…",
  ui_story_5084_50840201_14_dialog_content = "僕はどうやってここに？みんなはどこ行ったのかな…",
  ui_story_5084_50840201_15_dialog_content = "1つ目は、読書、学習、交流。真理結社には博識なお兄さんお姉さんが大勢いて、\n一生かけても学びきれないほどの知識を教えてくれるよ。",
  ui_story_5084_50840201_16_dialog_content = "2つ目は、食事、集会、真理の主の賛美。",
  ui_story_5084_50840201_17_dialog_content = "よく言われる「真理とはなにか」なんだけど、\nきっと毎日ご飯を食べたり、集会に参加したりしてたら自然とわかってくる。",
  ui_story_5084_50840201_18_dialog_content = "3つ目は、発掘、探検。\nセンスが良ければ、みんなをあっと言わせられる宝物を掘りだせるよ。",
  ui_story_5084_50840201_19_dialog_content = "あたしもそうだったんだけど、ただの探検好きにも真理結社は唯一無二の選択肢だね。",
  ui_story_5084_50840201_20_dialog_content = "真理結社に入ったら、「ベビーちゃん」の抜け毛まで減ったの。",
  ui_story_5084_50840201_21_dialog_content = "それに短期間でビクトリア様に認められて、しょっちゅう大事な仕事を1人で任されるようになったよ。",
  ui_story_5084_50840201_22_dialog_content = "どうよ？真理結社に入るのが楽しみになってきたでしょ？",
  ui_story_5084_50840201_23_dialog_content = "にゃ～。",
  ui_story_5084_50840201_24_dialog_content = "なんかすごい得意げ…",
  ui_story_5084_50840201_25_dialog_content = "ねえ、ちゃんとした服に着替えてから来てくれない？",
  ui_story_5084_50840201_26_dialog_content = "ビクトリア様はワラーキ家のお嬢様よ、\n本当にあなたみたいな小娘に仕事を任せるかしら…",
  ui_story_5084_50840201_27_dialog_content = "しかもあなた、ワラーキ村は初めてよね？",
  ui_story_5084_50840201_28_dialog_content = "なんなら真理結社の成り立ちや教義、墓所に眠る秘密について教えてあげましょうか…",
  ui_story_5084_50840201_29_dialog_content = "あれ？真理結社の先輩でした…？でも顔に見覚えがないような…",
  ui_story_5084_50840201_30_dialog_content = "メイ…！",
  ui_story_5084_50840201_31_dialog_content = "PlayerName？なによ、引っ張って。\nあの2人、もうちょっとで入りそうだったのに。",
  ui_story_5084_50840201_32_dialog_content = "彼女たちにその気がまったくなかっただろうというのはさておき…",
  ui_story_5084_50840201_33_dialog_content = "町中のみんなが巡行や聖鳴祭の話をしてるの聞こえたでしょ？僕たちはビクトリアの故郷、ワラーキ村に来たんだよ！",
  ui_story_5084_50840201_34_dialog_content = "ビクトリア様の故郷…前に聞いた気がする。で、それが？",
  ui_story_5084_50840201_35_dialog_content = "驚かないわけ？他の人がどこに行ったかも知りたくない？",
  ui_story_5084_50840201_36_dialog_content = "アハハッ、わかったわかった。祝典に参加するのに、新しい服を用意しないとだね！",
  ui_story_5084_50840201_37_dialog_content = "みんながどこのお店で買ったのか聞いて参考にしよう！",
  ui_story_5084_50840201_38_dialog_content = "あれ？急にテンション上がってきたね！ただ、ここだとお店って言うより、不気味な縫い物屋さんに出くわしそうな気がする…",
  ui_story_5084_50840201_39_dialog_content = "…メイ？どうしたの？",
  ui_story_5084_50840201_40_dialog_content = "この音！巡行が来た！迷子にならないようにさっさとあたしの手を握って。",
  ui_story_5084_50840201_41_dialog_content = "あの棺にはワラーキのご先祖様が入ってるんだって。真理の主に選ばれた人だよ！",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>赤い月が見守る中、華麗な衣装に身を包んだ集団が、歴史ある立派な棺をかついでゆっくりと行進していく</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>棺に横たわるのはワラーキの「ご先祖様」といわれる人物だ。神聖な典籍を胸に抱き、赤い月と共に真理の種をまく</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>信者たちは恭しくその後に続き、まばたきすら恐れるように棺を凝視している</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>彼らは村のあらゆる道を通り、真理の殿堂の壮大な正門の前にやって来た</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>ドスン——</color>",
  ui_story_5084_50840201_47_dialog_content = "巡行は終結し、真理が訪れた。",
  ui_story_5084_50840201_48_dialog_content = "信者は皆、主へと近づき、主に自らを委ねん。",
  ui_story_5084_50840201_49_dialog_content = "真理の主、感謝するわ！",
  ui_story_5084_50840201_50_dialog_content = "真理の主に一生を捧げる！",
  ui_story_5084_50840201_51_dialog_content = "さて…",
  ui_story_5084_50840201_52_dialog_content = "この中から信者1名が選ばれ、\n無限の啓示に満ちた虚空の棺に足を踏み入れ、真理の声を聴くことになる。",
  ui_story_5084_50840201_53_dialog_content = "非凡な洞察力は、ほの暗い地で歴史の謎を解き明かすことができるだろう。",
  ui_story_5084_50840201_54_dialog_content = "修行者である以上に、真理結社の集合知の体現者であるだろう。",
  ui_story_5084_50840201_55_dialog_content = "あらゆる経験が、我ら真理結社を未来へと導くだろう。",
  ui_story_5084_50840201_56_dialog_content = "虚無の河に沈んだ身の周囲では、時空の境界がぼんやりと消え去るだろう。",
  ui_story_5084_50840201_57_dialog_content = "真理の主が降臨なさる時のみ自我は洗い清められ変化し、\n最も純粋な本質だけが残るだろう。",
  ui_story_5084_50840201_58_dialog_content = "真理、傾聴、啓示、そして覚醒。",
  ui_story_5084_50840201_59_dialog_content = "その時、神聖なる存在と共鳴できる時が来る。",
  ui_story_5084_50840201_60_dialog_content = "ヴィルヘルム様、どうか私をご覧ください！",
  ui_story_5084_50840201_61_dialog_content = "もっと真理をお聞かせください…！",
  ui_story_5084_50840201_62_dialog_content = "あたしももっと聞きたい！",
  ui_story_5084_50840201_63_dialog_content = "…！しっ！",
  ui_story_5084_50840201_64_dialog_content = "苦労して潜り込んだんだから静かにして…",
  ui_story_5084_50840201_65_dialog_content = "でもあたしは真理結社の幹部になるんだから、もっと真理の話を聞かないと！\n今が絶好のチャンスでしょ。「ベビーちゃん」行くよ！",
  ui_story_5084_50840201_66_dialog_content = "「運命はすでに刻まれた。もはや質問も憎悪も変転もできぬ。」",
  ui_story_5084_50840201_67_dialog_content = "にゃ…？",
  ui_story_5084_50840201_68_dialog_content = "スカーレイにそう言われたでしょう？忘れたの、メイ？",
  ui_story_5084_50840201_69_dialog_content = "あ…ビクトリア様！？",
  ui_story_5084_50840201_70_dialog_content = "あれ？その恰好は？",
  ui_story_5084_50840201_71_dialog_content = "こっちが聞きたいわ。そんな恰好でどうやってここに入ったの？",
  ui_story_5084_50840201_72_dialog_content = "メイに引っ張られて、その後ずっと信者たちに揉まれながらなんとか入って来れた。",
  ui_story_5084_50840201_73_dialog_content = "ここがどこかもうわかっているわよね？",
  ui_story_5084_50840201_74_dialog_content = "信者たちの話を聞く限り、ここは君の故郷・ワラーキ村だよね。\nでもこの感じって、僕たちまさか…",
  ui_story_5084_50840201_75_dialog_content = "ここは過去なの。",
  ui_story_5084_50840201_76_dialog_content = "え？",
  ui_story_5084_50840201_77_dialog_content = "この時代は私もまだ真理結社のメンバーではなく、真理を知るために世界を渡り歩いていた。",
  ui_story_5084_50840201_78_dialog_content = "ここは1915年。この聖鳴祭の後、あの真理結社の指導者は失踪する。",
  ui_story_5084_50840201_79_dialog_content = "…どこに行ったの？",
  ui_story_5084_50840201_80_dialog_content = "真理の主はあの指輪を使って私をここへ導かれた。スカーレイの言っていた通り、\n物は時間に支配されるから、時間がそれらを本来の場所に連れ戻すというわけね。",
  ui_story_5084_50840201_81_dialog_content = "今この時、教典は祖先のもとへと戻り、指輪は指導者の指に帰った。",
  ui_story_5084_50840201_82_dialog_content = "ワラーキの血の呪いはどれほど時が経とうが消えないのよ。",
  ui_story_5084_50840201_83_dialog_content = "時の河を越えた謎を解決するために、君は啓示を受けなねばならない。",
  ui_story_5084_50840201_84_dialog_content = "君は真理に耳を傾け、世界をさらに読み解かねばならない。",
  ui_story_5084_50840201_85_dialog_content = "真理結社の指導者、ヴィルヘルム・ワラーキの名において、\n真理の主のお導きに従い、聖鳴祭の啓示を受けし者を発表する――",
  ui_story_5084_50840201_86_dialog_content = "ビクトリア・ワラーキ。",
  ui_story_5084_50840201_87_dialog_content = "なに…？",
  ui_story_5084_50840201_88_dialog_content = "ビクトリア・ワラーキ、彼女がなぜここに…",
  ui_story_5084_50840201_89_dialog_content = "ふふっ、おもしろいじゃない。",
  ui_story_5084_50840201_90_dialog_content = "…",
  ui_story_5084_50840201_91_dialog_content = "ビクトリアお嬢さま？お嬢さまがいらした！",
  ui_story_5084_50840201_92_dialog_content = "あの方こそワラーキ家の一人娘…",
  ui_story_5084_50840201_93_dialog_content = "でも聞くところによると、当主たちはあの方を受け入れていないとか…",
  ui_story_5084_50840201_94_dialog_content = "…",
  ui_story_5084_50840301_1_dialog_content = "<size=30>…ビクトリア様だ！</size>",
  ui_story_5084_50840301_2_dialog_content = "そんなに騒いだら、過去の人たちに気づかれちゃうよ！",
  ui_story_5084_50840301_3_dialog_content = "ここのルールを破ることになっちゃうんじゃない？",
  ui_story_5084_50840301_4_dialog_content = "心の導きに従うこと。まだ誰も導かれていない限り、啓示に誤りはない。",
  ui_story_5084_50840301_5_dialog_content = "真理の信者よ、次の赤い月を心待ちにせよ。\n真理の主は永久に我らを見つめ、我らの接近を切望しておられる。",
  ui_story_5084_50840301_6_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840301_7_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840301_8_dialog_content = "あの人たちと一緒にここを出る？",
  ui_story_5084_50840301_9_dialog_content = "心の導きに従い、静かに見守りましょう。",
  ui_story_5084_50840301_10_dialog_content = "どうする？",
  ui_story_5084_50840301_11_dialog_content = "私は真理結社のメンバーではないもの。天啓を聞く栄誉は、私には不相応よ。",
  ui_story_5084_50840301_12_dialog_content = "でも真理の殿堂に足を踏み入れる栄誉を与えられた時、君は異議を唱えなかった。",
  ui_story_5084_50840301_13_dialog_content = "真理を探し求め、組織を作る。君は真理結社に入るその日のために、準備をしているのだろう。",
  ui_story_5084_50840301_14_dialog_content = "あなたには一切関わりのないことよ。",
  ui_story_5084_50840301_15_dialog_content = "まだ答えをもらっていないな。真理とは一体なんだ？",
  ui_story_5084_50840301_16_dialog_content = "…",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>ゴロゴロ…ドーン！！</color>",
  ui_story_5084_50840301_18_dialog_content = "ただ…君は天啓と言ったね？ビクトリア・ワラーキ、\n早熟な君にぜひとも教えてもらいたい――真理とはなんだと思う？",
  ui_story_5084_50840301_19_dialog_content = "真理とは…知識。",
  ui_story_5084_50840301_20_dialog_content = "ふっ、ビクトリア・ワラーキ。我々は同じ血統につらなる者。\nだが頭脳、パワー、能力…それに姿形、どれをとっても私の方が優れている。",
  ui_story_5084_50840301_21_dialog_content = "にも関わらず、この指輪が自分のものだと思うのはなぜだ？",
  ui_story_5084_50840301_22_dialog_content = "私こそが真のワラーキ、真理結社の指導者なのだ！",
  ui_story_5084_50840301_23_dialog_content = "君は…まずは自らの力を証明してみよ――君がワラーキの名にふさわしいか否かを。\n恥ずかしい思いはさせてくれるなよ。",
  ui_story_5084_50840301_24_dialog_content = "…",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>ゴロゴロ…ドーン！！</color>",
  ui_story_5084_50840301_26_dialog_content = "本の中から意味の取れぬ文章を選び出し、共鳴の幻影から答えを探す…",
  ui_story_5084_50840301_27_dialog_content = "それが君なりの答えの探し方、だろう？",
  ui_story_5084_50840301_28_dialog_content = "さっきなにを見て、なにを思った？",
  ui_story_5084_50840301_29_dialog_content = "質問？恐れ？拒絶？君にはワラーキの力を選び取る資格はない。力がそれにふさわしい人物を選ぶのだ。",
  ui_story_5084_50840301_30_dialog_content = "…",
  ui_story_5084_50840301_31_dialog_content = "（彼はビクトリアの家に代々伝わる指輪をつけた…）",
  ui_story_5084_50840301_32_dialog_content = "ヴィルヘルム、以前君はビクトリアはワラーキ村を離れたと言ってたね…？",
  ui_story_5084_50840301_33_dialog_content = "ふっ、その通りだ。",
  ui_story_5084_50840301_34_dialog_content = "ワラーキ、これほど聡明で優秀なお嬢さんを前にしてもなお、\n厳格に行うというのか？",
  ui_story_5084_50840301_35_dialog_content = "ビクトリア嬢、久しぶりだね。",
  ui_story_5084_50840301_36_dialog_content = "はい。",
  ui_story_5084_50840301_37_dialog_content = "ポルフィリオ、彼女を選んだのは真理の主のお導きによるもの。私やワラーキにとっては、やむをえぬことと思うしかない。",
  ui_story_5084_50840301_38_dialog_content = "フハハハ、誰も責められぬ。責めるなら、我々が同じ「血の一族」でありながら、異なる道を有することでも責めるしかない。",
  ui_story_5084_50840301_39_dialog_content = "真理の主はまた降臨なさるのか？\n主より選ばれし後継者の資格か信仰心が足りなかったのか？",
  ui_story_5084_50840301_40_dialog_content = "すべてをワラーキの責任にはできない。これは我ら12名の当主の責任だな。",
  ui_story_5084_50840301_41_dialog_content = "ハハハハッ！耳が痛いよ、ポルフィリオ。",
  ui_story_5084_50840301_42_dialog_content = "さてと、啓示に背いてはならない。それならば…真理の主は彼女になにかを伝えたいのであろう…",
  ui_story_5084_50840301_43_dialog_content = "当主諸君！",
  ui_story_5084_50840301_44_dialog_content = "今回の聖鳴祭で啓示を受けし者について――異議はなかろう？",
  ui_story_5084_50840301_45_dialog_content = "…",
  ui_story_5084_50840301_46_dialog_content = "異議なし…",
  ui_story_5084_50840301_47_dialog_content = "異議があったからといってどうなる？",
  ui_story_5084_50840301_48_dialog_content = "フン…",
  ui_story_5084_50840301_49_dialog_content = "早く始めましょう。真理の主が待ちくたびれておられるわ。",
  ui_story_5084_50840301_50_dialog_content = "ビクトリア・ワラーキ、緊張することはない。",
  ui_story_5084_50840301_51_dialog_content = "私が神聖なる正殿内を先導し、棺の中まで送ってやる。",
  ui_story_5084_50840301_52_dialog_content = "心を静めて頭を整理しろ。真理に対する理解を主に示すのだ。",
  ui_story_5084_50840301_53_dialog_content = "…",
  ui_story_5084_50840301_54_dialog_content = "（さっき街で信者たちが、「自分をいけにえ」とか話してたけど…この儀式は一体…）",
  ui_story_5084_50840301_55_dialog_content = "（当主たちからはなんだか危ない香りがするし…）",
  ui_story_5084_50840301_56_dialog_content = "（ビクトリアがほんとに「いけにえ」にされたらどうしよう！？）",
  ui_story_5084_50840301_57_dialog_content = "（棺に入っちゃう前に聞かないと！）",
  ui_story_5084_50840301_58_option_content = "精神感知",
  ui_story_5084_50840301_59_dialog_content = "やっと来たわね。",
  ui_story_5084_50840301_60_dialog_content = "まずいことになってるんじゃ…ほんとにあの人に連れられて棺に入って、「いけにえ」になるつもり！？",
  ui_story_5084_50840301_61_dialog_content = "そうよ。",
  ui_story_5084_50840301_62_dialog_content = "そんな…じゃあ僕とメイはどうすれば！？",
  ui_story_5084_50840301_63_dialog_content = "スカーレイの話を覚えている？",
  ui_story_5084_50840301_64_dialog_content = "もちろん！「運命はすでに刻まれた。もはや…質問もできぬ」！？",
  ui_story_5084_50840301_65_dialog_content = "質問しちゃ駄目なのか…",
  ui_story_5084_50840301_66_dialog_content = "わかったようね。",
  ui_story_5084_50840301_67_dialog_content = "ここに来た時点であなたはおいてけぼりなのよ。",
  ui_story_5084_50840301_68_dialog_content = "質問もできなくて、あなたの頭の中は「？」だらけで今にもあふれ出しそうなんじゃない？",
  ui_story_5084_50840301_69_dialog_content = "頭から出てる煙、見えちゃった？",
  ui_story_5084_50840301_70_dialog_content = "直感に従えばいいわ。そして私と共に見届けましょう。",
  ui_story_5084_50840301_71_dialog_content = "ビクトリア！",
  ui_story_5084_50840301_72_dialog_content = "それでは…",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>ブワーッ！ブワブワーーッ！！</color>",
  ui_story_5084_50840301_74_dialog_content = "急いで棺の中へ！",
  ui_story_5084_50840301_75_dialog_content = "…",
  ui_story_5084_50840301_76_dialog_content = "風…？ビクトリア様、ホントに中に入っちゃった！",
  ui_story_5084_50840301_77_option_content = "精神感知",
  ui_story_5084_50840301_78_dialog_content = "（感知が何かに遮られてる…）",
  ui_story_5084_50840301_79_dialog_content = "はは…",
  ui_story_5084_50840301_80_dialog_content = "ハハ……ハハハハ……",
  ui_story_5084_50840301_81_dialog_content = "フフフッ…フハハハハッ！",
  ui_story_5084_50840301_82_dialog_content = "（笑い声…彼らは一体なにを…）",
  ui_story_5084_50840301_83_dialog_content = "ハーッハッハッハッ…",
  ui_story_5084_50840301_84_dialog_content = "（指導者であるヴィルヘルムさんまで…？）",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>ブワーッ！ブワブワーーッ！！</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName？",
  ui_story_5084_50840301_87_dialog_content = "メイ、大丈夫だ。僕がついてる！",
  ui_story_5084_50840301_88_dialog_content = "あれ！？",
  ui_story_5084_50840301_89_dialog_content = "黒い風のせいでロウソクが消えたみたい…殿堂中何ひとつ見えないよ！",
  ui_story_5084_50840301_90_dialog_content = "あの笑い声、怪しすぎる…なにか企んでたんじゃ？",
  ui_story_5084_50840301_91_dialog_content = "ヴィルヘルムさんがビクトリアにしてた話も…",
  ui_story_5084_50840301_92_dialog_content = "ビクトリアは無事だよね！？あの人たちなんで笑ってたんだ？\nいや…このままじゃダメだ！",
  ui_story_5084_50840301_93_option_content = "強制感知——",
  ui_story_5084_50840301_94_dialog_content = "（なんとか…ほんの少しだけ見えた…でもなんなんだろうこれ…）",
  ui_story_5084_50840301_95_dialog_content = "この数年、真理結社をまとめるのは大変だっただろう？ヴィルヘルム・ワラーキ。",
  ui_story_5084_50840301_96_dialog_content = "信者が棺に入ることの意味を知りながら、<color=#FFB400>アストン・ワラーキ</color>の娘を選んだ。なかなか計算高い男だ。",
  ui_story_5084_50840301_97_dialog_content = "あれは真理結社の前指導者である兄の娘。\nその娘の世話をするのも私の務めだ。",
  ui_story_5084_50840301_98_dialog_content = "（ヴィルヘルムさんはビクトリアの…叔父さん？）",
  ui_story_5084_50840301_99_dialog_content = "ワラーキ、うわべだけの言葉はもう聞き飽きた。",
  ui_story_5084_50840301_100_dialog_content = "君が次なる手を探しあぐねているのはわかっている。",
  ui_story_5084_50840301_101_dialog_content = "共にお前の姪を「食べる」か？それともお前たちが一緒に…",
  ui_story_5084_50840301_102_dialog_content = "待て――",
  ui_story_5084_50840301_103_dialog_content = "ヴィルヘルム、何をするつもりだ？\nあんな話をしておきながら、これはどういうことだ？",
  ui_story_5084_50840301_104_dialog_content = "ああ。君とてすでに決心したはずだ、クラビス。",
  ui_story_5084_50840301_105_dialog_content = "…",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>ブワーッ！ブワブワーーッ！！</color>",
  ui_story_5084_50840301_107_dialog_content = "（ああもう…この風邪魔だな…）",
  ui_story_5084_50840301_108_dialog_content = "（クラビスさん、ヴィルヘルムさん、ビクトリア…いったい何を考えてるんだろう？）",
  ui_story_5084_50840301_109_dialog_content = "ちょっと、腕をそんなに強くつかまないで、PlayerName！また縫わなきゃいけなくなっちゃうでしょ…",
  ui_story_5084_50840301_110_dialog_content = "ごめん…でも…",
  ui_story_5084_50840301_111_dialog_content = "いまの力加減はちょうどいい感じ。",
  ui_story_5084_50840301_112_dialog_content = "どうにかしないと…でも、この状況はいったい…",
  ui_story_5084_50840301_113_dialog_content = "ビクトリアも叔父さんも、どういうつもりなんだろう？\nどうしてビクトリアをいけにえに…",
  ui_story_5084_50840301_114_dialog_content = "PlayerName、どうするか考えた？あ…ロウソクの火が揺れ出した…どっかに行くんじゃない？",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>コツ、コツ……</color>",
  ui_story_5084_50840401_2_dialog_content = "この音は…！",
  ui_story_5084_50840401_3_dialog_content = "にゃあ？",
  ui_story_5084_50840401_4_dialog_content = "よしよしベビーちゃん、大丈夫だよ。あたしがいるからね。",
  ui_story_5084_50840401_5_dialog_content = "何か言ってよね。1人かと思ったよ。",
  ui_story_5084_50840401_6_dialog_content = "違う場所に来たみたいだ…いい匂い。これは…服？",
  ui_story_5084_50840401_7_dialog_content = "え？",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>ギイィ――</color>",
  ui_story_5084_50840401_9_dialog_content = "誰か来た！",
  ui_story_5084_50840401_10_dialog_content = "うっ…なにすんのよ…うぐっ！",
  ui_story_5084_50840401_11_dialog_content = "…ふっ、昨日着たこの服は、もはや歴史の一部だ。",
  ui_story_5084_50840401_12_dialog_content = "この生地はサンドペーパーのようではないか。\n僕は芸術家であって木工職人ではないぞ…",
  ui_story_5084_50840401_13_dialog_content = "これは…ありきたりな色味だな…芸術家がこんな平凡な色を受けつけると思うか。",
  ui_story_5084_50840401_14_dialog_content = "チッ、この僕にふさわしい服が1着もないではないか！\n子供服だと…？とうに大人の服を着る年頃だというのに！",
  ui_story_5084_50840401_15_dialog_content = "僕としたことが！なぜ父上の話を真に受けてしまったのだ！",
  ui_story_5084_50840401_16_dialog_content = "あの2人の訪問者は、このカロン様の「フォーマル」な服装にふさわしくない！",
  ui_story_5084_50840401_17_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5084_50840401_18_dialog_content = "…？",
  ui_story_5084_50840401_19_dialog_content = "カロン！！！？",
  ui_story_5084_50840401_20_dialog_content = "しかも…僕たちの姿が見えてない？",
  ui_story_5084_50840401_21_dialog_content = "ふぅはぁ――！PlayerName、やっと離してくれた！あの子、知り合い？",
  ui_story_5084_50840401_22_dialog_content = "芸術家…「カロン様」…あの髪型…あの表情…\n知ってるなんてもんじゃないよ！",
  ui_story_5084_50840401_23_dialog_content = "さっき僕たち、あの子の目の前に立ってたよね？",
  ui_story_5084_50840401_24_dialog_content = "うん。服を選んでた。ム…このいい香りがする服はなかなかユニークね。\nあたしには作れないな…",
  ui_story_5084_50840401_25_dialog_content = "カロンのクローゼット…この時代のカロンは見た感じ10歳ちょっとか…",
  ui_story_5084_50840401_26_dialog_content = "うーん…カロンの年齢はともかく、ここが過去ってことははっきりしたね。",
  ui_story_5084_50840401_27_dialog_content = "さっきの聖鳴祭…ビクトリアは1915年の聖鳴祭だって言ってた。つまり…",
  ui_story_5084_50840401_28_dialog_content = "というか、このロウソクは一体どうなってるの？\nロウソクの火が揺れると別の場所に移動する。今回もまたメイと一緒だ。",
  ui_story_5084_50840401_29_dialog_content = "あんたってとことんバカ。そりゃ左手でロウソクを持って、\n右手であたしと「ベビーちゃん」をつかんでたからでしょうよ。",
  ui_story_5084_50840401_30_dialog_content = "スカーレイさんはスンゴイものをいっぱい持ってるんだから。\nあんたが魔法を信じないなら、なにを言っても無駄だけど。",
  ui_story_5084_50840401_31_dialog_content = "…？こんなことが起きてるのに不思議だと思わないの？",
  ui_story_5084_50840401_32_dialog_content = "それってうれしい不思議か怖い不思議かどっち？",
  ui_story_5084_50840401_33_dialog_content = "アハハッ、あたしはどっちも好きだけど！",
  ui_story_5084_50840401_34_dialog_content = "カロンには僕らが見えず、声も聞こえないみたいだった。それもロウソクのせいかな…",
  ui_story_5084_50840401_35_dialog_content = "真理の殿堂に紛れ込めたのもだけど…\n僕らの姿が見えるのは未来から一緒に来たビクトリアだけだった。",
  ui_story_5084_50840401_36_dialog_content = "このロウソクは小説に出てくるような、隠れ身の道具だったのか！",
  ui_story_5084_50840401_37_dialog_content = "アハハッ、そうかも！",
  ui_story_5084_50840401_38_dialog_content = "棺に入ったビクトリアはどうなったんだろう？\nネイルスとファウストの行方も分からないし…",
  ui_story_5084_50840401_39_dialog_content = "僕たちがここに来たのは本当に心の導きに従ったからなのかな……",
  ui_story_5084_50840401_40_dialog_content = "さっきなに考えてた？",
  ui_story_5084_50840401_41_dialog_content = "ロウソクの火が揺れた時？確か…",
  ui_story_5084_50840401_42_dialog_content = "「クラビスさん、ヴィルヘルムさん、ビクトリア…いったい何を考えてるんだろう？」",
  ui_story_5084_50840401_43_dialog_content = "カロンの言ってた「父上」と「2人の訪問者」がその3人のことだとしたら…",
  ui_story_5084_50840401_44_dialog_content = "スカーレイの言ってた「ロウソクが導いてくれる」っていうのは、このことだったんだ！",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>ギイィ――</color>",
  ui_story_5084_50840401_46_dialog_content = "僕がこんなことをするのは、芸術に偏見は禁物だと純粋に思うから。\nこの靴下はお気に入りだけど今回はしょうがない。彼らのために履き替えてやろう。",
  ui_story_5084_50840401_47_dialog_content = "（本当に服選びしてたのか…）",
  ui_story_5084_50840401_48_dialog_content = "「カロン様はいつもどこでそれほど魅力的な靴下をお買い求めになるのですか？」",
  ui_story_5084_50840401_49_dialog_content = "「カロン様は今まで会った中で最もセンスのある方です…」",
  ui_story_5084_50840401_50_dialog_content = "大人ってこういうもの？ふんっ、ほっといてほしいけどね…",
  ui_story_5084_50840401_51_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5084_50840401_52_dialog_content = "…",
  ui_story_5084_50840401_53_dialog_content = "うーん、やっぱり子どもの頃から変わってたんだな…",
  ui_story_5084_50840401_54_dialog_content = "行くよ、メイ。あとをつけてみよう！僕から離れないでね。",
  ui_story_5084_50840401_55_dialog_content = "わかってるって！",
  ui_story_5084_50840401_56_dialog_content = "久しぶりだな、クラビス。",
  ui_story_5084_50840401_57_dialog_content = "クラビス叔父さま。",
  ui_story_5084_50840401_58_dialog_content = "ビクトリア様！ビクト――",
  ui_story_5084_50840401_59_dialog_content = "この距離なら見えてるはずだよ。僕たちに反応しないってことは、昔の彼女なんじゃ？",
  ui_story_5084_50840401_60_dialog_content = "僕たちが知ってるビクトリアと瓜二つではあるけど…",
  ui_story_5084_50840401_61_dialog_content = "バカねえ。ビクトリア様は高貴な血の一族だよ。覚醒してからは年をとらないんだってば。",
  ui_story_5084_50840401_62_dialog_content = "…ってゆうか、PlayerName。過去の人にはあたしたちの姿は見えないのに、なんでまだ隠れてるの？",
  ui_story_5084_50840401_63_dialog_content = "あ！そうだった…ここで目にした人や出来事にびっくりしちゃったからかな？",
  ui_story_5084_50840401_64_dialog_content = "ハハッ…2人揃って訪ねて来るとは実に珍しい。",
  ui_story_5084_50840401_65_dialog_content = "フン…",
  ui_story_5084_50840401_66_dialog_content = "カロンは？",
  ui_story_5084_50840401_67_dialog_content = "いつものことだ。\n客の姿を見るなり、身だしなみを整えに行ったよ…",
  ui_story_5084_50840401_68_dialog_content = "…",
  ui_story_5084_50840401_69_dialog_content = "あら、カロンさん。素敵な靴下ね。",
  ui_story_5084_50840401_70_dialog_content = "…！ふん、何を言われても、僕は…",
  ui_story_5084_50840401_71_dialog_content = "挨拶は？",
  ui_story_5084_50840401_72_dialog_content = "…ヴィルヘルム叔父さま、こんにちは。",
  ui_story_5084_50840401_73_dialog_content = "それとこちらはそのヴィルヘルム叔父さまの姪、ビクトリア。\nお前のいとこだ。",
  ui_story_5084_50840401_74_dialog_content = "初めまして、遠い親戚さん。",
  ui_story_5084_50840401_75_dialog_content = "…初めまして。",
  ui_story_5084_50840401_76_dialog_content = "カロン、ビクトリアにお菓子をあげなさい。",
  ui_story_5084_50840401_77_dialog_content = "…分かりました。",
  ui_story_5084_50840401_78_dialog_content = "ところで、旧市街地まで出向いてくるとは、\nワラーキ村の方は片付いたのか？",
  ui_story_5084_50840401_79_dialog_content = "道中少々苦労はしたがね。だがクラビス、君も知っての通り、\n私は君に会うためなら距離など厭わない。",
  ui_story_5084_50840401_80_dialog_content = "…",
  ui_story_5084_50840401_81_dialog_content = "…",
  ui_story_5084_50840401_82_dialog_content = "いつまで私をじろじろ見ているつもり？",
  ui_story_5084_50840401_83_dialog_content = "あの陰気な奴らの仲間なのか？",
  ui_story_5084_50840401_84_dialog_content = "「陰気な奴ら」とは誰のことかしら？",
  ui_story_5084_50840401_85_dialog_content = "ヴィルヘルム・ワラーキと同じ、結社の奴らだ。",
  ui_story_5084_50840401_86_dialog_content = "私は真理結社の者ではないわ。でも指導者の名前を呼び捨てにするのは、\nお行儀がいいとは言えないわね。",
  ui_story_5084_50840401_87_dialog_content = "奴らと仲がいいなら、みんな悪人だ。芸術家の勘だよ。\n父上に言われたんじゃなかったら、誰が君らなんかに会うものか。",
  ui_story_5084_50840401_88_dialog_content = "あら、そんなに嫌いなのに、\n会うとなれば熱心におしゃれをするのね。",
  ui_story_5084_50840401_89_dialog_content = "…！これは芸術のためだ！",
  ui_story_5084_50840401_90_dialog_content = "あら、芸術がわかるの？なら芸術とは何かしら？",
  ui_story_5084_50840401_91_dialog_content = "僕たちはいつか必ず死を迎える。でも、ひとつだけ死とは無縁の物がある。\nそれが何だか分かるかい？",
  ui_story_5084_50840401_92_dialog_content = "芸術だよ！",
  ui_story_5084_50840401_93_dialog_content = "芸術は地獄から禁断の花を咲かせ、三途の川を切り開き、\n永久に動く列車を走らせることができる。",
  ui_story_5084_50840401_94_dialog_content = "そして僕はその列車の車掌になる。\n魂の渡し人として、芸術として――永遠に生きるんだ。",
  ui_story_5084_50840401_95_dialog_content = "永遠に生きる…フフ。\nなら、私はいつかあなたの乗客になるのね。",
  ui_story_5084_50840401_96_dialog_content = "もちろんだ！いや…まだダメだ。\nあの陰気な奴らが僕の傑作をけなした時…",
  ui_story_5084_50840401_97_dialog_content = "子供といっても、もうそれなりの年だろう？\n小便器におかしな愛着を示すとはな…",
  ui_story_5084_50840401_98_dialog_content = "…酔って方角がわからなくなった輩のように、\nここではしゃいでいたな。",
  ui_story_5084_50840401_99_dialog_content = "決めたんだ。僕の列車には僕の芸術を解する人しか乗せないと…",
  ui_story_5084_50840401_100_dialog_content = "長生きをしすぎると言動が粗野になる。\n一番ダメなのはセンスを失うことだ。僕はそういう奴らの相手はしない。",
  ui_story_5084_50840401_101_dialog_content = "自分に自信があるのね。",
  ui_story_5084_50840401_102_dialog_content = "もちろん。旧市街地で僕ほどのセンスの持ち主はいないからね。",
  ui_story_5084_50840401_103_dialog_content = "将来は演劇や音楽、鉄道模型、芸術の結社を作るつもりだよ…",
  ui_story_5084_50840401_104_dialog_content = "はっきり言って、僕はあいつらの追い求める真理をとっくに見抜いてる。\n芸術、それこそが真理だ。",
  ui_story_5084_50840401_105_dialog_content = "どうかな？まだ入りたい組織が見つかっていないなら、\n勇気を出してカロン様の加入審査に挑戦してみるというのは？",
  ui_story_5084_50840401_106_dialog_content = "フフ、面白いわね。それで、審査というのは？",
  ui_story_5084_50840401_107_dialog_content = "簡単さ。僕の列車がここを通る時、五感を駆使して僕の芸術世界に入るんだ！\nその後、芸術に対する心構えを見せてくれたらいい。",
  ui_story_5084_50840401_108_dialog_content = "わかったわ。始めましょう。",
  ui_story_5084_50840401_109_dialog_content = "少し待っててくれ。\n部外者にそういうものを見せるなと父上に言われているんでね。",
  ui_story_5084_50840401_110_dialog_content = "すぐに車掌のパフォーマンスと芸術の神髄を見せてあげるからね！",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>しばらくして…</color>",
  ui_story_5084_50840401_112_dialog_content = "さあ、耳を澄ませ！\nレールに世界の末日を前にした叫び声が響いている――ガタンゴトン――！",
  ui_story_5084_50840401_113_dialog_content = "見よ、これが末日を前に永遠へと向かう終末列車だ！",
  ui_story_5084_50840401_114_dialog_content = "永遠を渇望する芸術家たちを乗せて、\n光輝く空の果てへとワープする！",
  ui_story_5084_50840401_115_dialog_content = "鎖はすでに断たれ、もうその体を束縛されることもない。\nただひとつ残された無数の車輪で、いつまでも休むことなく走り続ける！",
  ui_story_5084_50840401_116_dialog_content = "ヘッドを高く持ち上げ、蒼穹を目指す！この僕――\nカロン車掌の先導のもと、呪われた深淵から逃げ出すんだ！",
  ui_story_5084_50840401_117_dialog_content = "僕は地獄に命ずる――門を開けよと。新世界の朝日を迎えるんだ！",
  ui_story_5084_50840401_118_dialog_content = "うわあ…ホントに闇を走る列車が目に浮かんだ…",
  ui_story_5084_50840401_119_dialog_content = "さすがカロン…彼のいる場所がステージになるんだな…",
  ui_story_5084_50840401_120_dialog_content = "ジャジャジャジャーン！恐れることなく、\n僕の奏でる旧世界と新世界の交響曲をとくと聞くがいい！",
  ui_story_5084_50840401_121_dialog_content = "進め、進め、新世界の扉を開け！そこは不朽の楽園！",
  ui_story_5084_50840401_122_dialog_content = "…",
  ui_story_5084_50840401_123_dialog_content = "次は君の番だ！",
  ui_story_5084_50840401_124_dialog_content = "フフ、パフォーマンスの才能はあるようね。\nでも新世界の扉なんてただの幻想よ。",
  ui_story_5084_50840401_125_dialog_content = "あなたが渇望する新世界の扉は目に見えない砦となって、\n突然目の前に落ちて来る。",
  ui_story_5084_50840401_126_dialog_content = "そして列車のレールに火がつき、\n赤と黄色の縞模様の巨大な物体があなたの幻想を燃やすの。",
  ui_story_5084_50840401_127_dialog_content = "死、それこそが真理。終結の序曲を捧げましょう！\n永遠の命は底なしの恐怖、無尽の脅威よ！",
  ui_story_5084_50840401_128_dialog_content = "恐怖は人を縮み上がらせる。\n人は永遠の命という名の檻に閉じ込められ、永遠に出口を見出せない。",
  ui_story_5084_50840401_129_dialog_content = "巨大なるものに射すくめられたあなたは、もてあそばれるちっぽけな傀儡。\nもがくことも抵抗することもできない。",
  ui_story_5084_50840401_130_dialog_content = "顔を上げなさい！",
  ui_story_5084_50840401_131_dialog_content = "果てなき支配――それが新世界の真相よ！",
  ui_story_5084_50840401_132_dialog_content = "…！",
  ui_story_5084_50840401_133_dialog_content = "真相が見えない者たちのバカげた会話の中では、\nあなたの狂乱は娯楽として消費されるだけ！",
  ui_story_5084_50840401_134_dialog_content = "真の芸術とは、恐怖を喚起することよ！",
  ui_story_5084_50840401_135_dialog_content = "…うわああああああああ！",
  ui_story_5084_50840401_136_dialog_content = "…き、君は――！",
  ui_story_5084_50840401_137_dialog_content = "永遠たる芸術もこの刺激には勝てないでしょう？",
  ui_story_5084_50840401_138_dialog_content = "フフッ、アハハハハハ…！",
  ui_story_5084_50840401_139_dialog_content = "…うわあああん！！！",
  ui_story_5084_50840401_140_dialog_content = "早く僕の列車を…止めて！止めてってば！",
  ui_story_5084_50840401_141_dialog_content = "アハハハハ…",
  ui_story_5084_50840401_142_dialog_content = "ビクトリア様の親戚って、おもしろい子だね。",
  ui_story_5084_50840401_143_dialog_content = "え？そっち…？\nカロンをからかうビクトリアの方は気にならないの！？",
  ui_story_5084_50840401_144_dialog_content = "どうりでカロンはビクトリアのことを話す時、何とも言えない顔をするわけだね。\nこれのどこが芸術なんだか…！",
  ui_story_5084_50840401_145_dialog_content = "それはできぬ相談だ、ヴィルヘルム…",
  ui_story_5084_50840401_146_dialog_content = "いったい何を恐れている？\nクラビス、まさか異変が起こり始めていることに気づいていないのか？",
  ui_story_5084_50840401_147_dialog_content = "ポルフィリオと当主たちは、\nワラーキの一族から分家して以来、戒律を無視し始めた…",
  ui_story_5084_50840401_148_dialog_content = "こんなことをしたところで君には誰も救えない。",
  ui_story_5084_50840401_149_dialog_content = "だが今の真理結社は私や君、村人の誰にとっても災いでしかない。\nこれまでは血の一族の戒律が抑止力であったというのに！",
  ui_story_5084_50840401_150_dialog_content = "血の一族は生来血を好むもの…君も私も皆そうだ。\n君や私は運が良かっただけだ。",
  ui_story_5084_50840401_151_dialog_content = "…？血脈、血脈と…君はいつからにそんな言葉を口にするようになったのだ？",
  ui_story_5084_50840401_152_dialog_content = "そんな言い草はよせ、ヴィルヘルム。\n私は単に事実を否定しないだけだよ…",
  ui_story_5084_50840401_153_dialog_content = "あの<color=#FFB400>鍵</color>は、君を傷つけるだけだ。",
  ui_story_5084_50840401_154_dialog_content = "死を前にした兄はわざわざそれを<color=#FFB400>藤蔓人</color>から取り戻し、君に渡した…\n私の手に渡すためにそうしたのは明らかだ。",
  ui_story_5084_50840401_155_dialog_content = "…君が<color=#FFB400>藤蔓人</color>から無理やり奪い取るのを避けるためという可能性もある。",
  ui_story_5084_50840401_156_dialog_content = "常識外れではあっても、\n君は跡継ぎとしてもう何年も真理結社を取り仕切ってきた。",
  ui_story_5084_50840401_157_dialog_content = "それはすべて古の予言に刻印されたこと。",
  ui_story_5084_50840401_158_dialog_content = "運命には逆らえぬと、君は私以上にわかっているはずだ。",
  ui_story_5084_50840401_159_dialog_content = "違う、そうではない！",
  ui_story_5084_50840401_160_dialog_content = "私が信じるのは真理の主。ワラーキの存亡などに興味はない！\n少なくとも、私は運命といわれるものなど信じない…",
  ui_story_5084_50840401_161_dialog_content = "己の身に降りかかる運命であろうと、\nそれを甘んじて受け入れようとは思わない。",
  ui_story_5084_50840401_162_dialog_content = "私は徹頭徹尾、心の導きにのみに従う。\nそれが真理というもの。",
  ui_story_5084_50840401_163_dialog_content = "では、ビクトリアはどうする？\nあの娘を兄上から託されたのだろう――",
  ui_story_5084_50840401_164_dialog_content = "クラビス、兄の話はよしてくれ。",
  ui_story_5084_50840401_165_dialog_content = "ビクトリアは私以上にこの身の力に無頓着で、ワラーキ村にも一切興味がない。\n自分のことは自分でできる娘だ。",
  ui_story_5084_50840401_166_dialog_content = "ふっ…それも兄が私に下した罰なのかもしれないな。",
  ui_story_5084_50840401_167_dialog_content = "ヴィルヘルム…",
  ui_story_5084_50840401_168_dialog_content = "ならば…家族を大事にするといい。",
  ui_story_5084_50840401_169_dialog_content = "…うわあああん！！！",
  ui_story_5084_50840401_170_dialog_content = "…",
  ui_story_5084_50840401_171_dialog_content = "ビクトリア、そろそろ時間だ。",
  ui_story_5084_50840401_172_dialog_content = "…",
  ui_story_5084_50840401_173_dialog_content = "もう帰っちゃうの？こっちは何も分からなかったんだけど…\nついて行かなきゃ…考えるんだ…そう、考えなきゃ…",
  ui_story_5084_50840401_174_dialog_content = "やった！ロウソクの炎がまた揺れ始めた。\nねえ、早く――",
  ui_story_5084_50840401_175_dialog_content = "泣くな…",
  ui_story_5084_50840401_176_dialog_content = "狂ってる…どうかしてるよ…！",
  ui_story_5084_50840401_177_dialog_content = "そのガラクタを片づけなさい、今すぐにだ！",
  ui_story_5084_50840401_178_dialog_content = "…うう、ぐすっ…",
  ui_story_5084_50840501_1_dialog_content = "これでわかった。ロウソクの炎が揺れた時、\n僕はヴィルヘルムさんは何を考えてるんだろうって思ってた。",
  ui_story_5084_50840501_2_dialog_content = "つまりここは…ヴィルヘルム様の家ってこと？",
  ui_story_5084_50840501_3_dialog_content = "ヴィルヘルム様だ！",
  ui_story_5084_50840501_4_dialog_content = "憂鬱な顔で指輪を握ってる…",
  ui_story_5084_50840501_5_dialog_content = "何か考え事をしてるとしても、僕たちには分からないね。",
  ui_story_5084_50840501_6_dialog_content = "超有名な空の末裔さん、\n盗み聞きに成功したら絶対教えてよね。",
  ui_story_5084_50840501_7_dialog_content = "だ、誰が感知能力を使って盗み聞きするって？",
  ui_story_5084_50840501_8_dialog_content = "でもそうしないと、なに考えてるかわからないじゃん。",
  ui_story_5084_50840501_9_dialog_content = "…",
  ui_story_5084_50840501_10_dialog_content = "ぐずぐずしないで。\n大人なんだから、さっさと決断しなさいよ！",
  ui_story_5084_50840501_11_dialog_content = "分かったよ。ただ感知するだけなら、\nスカーレイの言ったルールに違反したことにはならないだろうし…",
  ui_story_5084_50840501_12_option_content = "感知――",
  ui_story_5084_50840501_13_dialog_content = "遺物に潜むささやきは…身に着けた者にしか分からない。\n瞬時に何千回と殺され、何万回と食いかじられる痛みを味わうのだ…",
  ui_story_5084_50840501_14_dialog_content = "ワラーキ…血の一族には…本当に活路はないのだろうか…",
  ui_story_5084_50840501_15_dialog_content = "光霊に生まれながらこの日の射さぬ暗い村に蟄居し、\n代々力を継承する。",
  ui_story_5084_50840501_16_dialog_content = "血の一族の先祖に導かれて身を潜め、逃避しながら、死せるがごとき一生を送る…",
  ui_story_5084_50840501_17_dialog_content = "何が先祖の意思だ…力の継承だ…\nワラーキは統治体制を維持するために、子孫の生死すら顧みないではないか。",
  ui_story_5084_50840501_18_dialog_content = "ワラーキ一族は血に代わるものを摂取する習慣を身につけた今でも、\n結局はその罪深き力の源から離れられぬままだ。",
  ui_story_5084_50840501_19_dialog_content = "（血に代わるもの…ビクトリアがよく口にする生命の甘露って…\nまさか本当に…）",
  ui_story_5084_50840501_20_dialog_content = "この恐ろしい指輪は…",
  ui_story_5084_50840501_21_dialog_content = "くっ…",
  ui_story_5084_50840501_22_dialog_content = "近ごろ当主たちは狂おしいほど血を求めるようになった…",
  ui_story_5084_50840501_23_dialog_content = "ああ…クラビス、君と口論をしたあの日からもう3年が過ぎた。\n君は今、いったい何をしているのだろう。",
  ui_story_5084_50840501_24_dialog_content = "（ビクトリアとヴィルヘルムさんがカロンのお父さんを訪ねたのが3年前なら…\n今は何年だろう？）",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>ガチャ――</color>",
  ui_story_5084_50840501_26_dialog_content = "…",
  ui_story_5084_50840501_27_dialog_content = "この時代のビクトリア…？",
  ui_story_5084_50840501_28_dialog_content = "あの感じは…確かに過去のビクトリアで間違いない。",
  ui_story_5084_50840501_29_dialog_content = "また昔のビクトリア様なの！？\nで、さっきはなにを盗み聞きしたワケ？",
  ui_story_5084_50840501_30_dialog_content = "ビクトリアが入って来た時、ヴィルヘルムさんが指輪を中指にはめたんだけど、\nその瞬間、感知が何かに妨害されたみたいなんだ…",
  ui_story_5084_50840501_31_dialog_content = "それで感知をやめたんだ？",
  ui_story_5084_50840501_32_dialog_content = "うん…あの指輪はヴィルヘルムさんの精神に大きなダメージを与えるかもしれない。\nでも今はまず、2人が何を話すのか聞いてみよう。",
  ui_story_5084_50840501_33_dialog_content = "うっ…",
  ui_story_5084_50840501_34_dialog_content = "戻ったのね…なぜ今回は3か月も家を空けていたの？",
  ui_story_5084_50840501_35_dialog_content = "…君には関わりのないことだ。",
  ui_story_5084_50840501_36_dialog_content = "その目つきは何なのかしら…恨みや得体の知れない感情が宿っている…",
  ui_story_5084_50840501_37_dialog_content = "ヴィルヘルム・ワラーキ、答えてちょうだい。\n何があったの？",
  ui_story_5084_50840501_38_dialog_content = "誰が部屋に入っていいと言った？",
  ui_story_5084_50840501_39_dialog_content = "真理結社の指導者でありながら、務めを放り出して遊歴ばかり…\n家を空けている時間も増える一方だわ。",
  ui_story_5084_50840501_40_dialog_content = "何度も言っただろう。君には関係ない。今すぐ出て行け。",
  ui_story_5084_50840501_41_dialog_content = "いつもそうやって私との会話を拒むのね。でも今晩は聖鳴祭よ。\nその前に最後に話せると思ったのだけれど。",
  ui_story_5084_50840501_42_dialog_content = "真理について、私たちについて…",
  ui_story_5084_50840501_43_dialog_content = "出て行け！今すぐにだ！",
  ui_story_5084_50840501_44_dialog_content = "…",
  ui_story_5084_50840501_45_dialog_content = "ヴィルヘルム様、怖すぎ…でもなんであんな急に…",
  ui_story_5084_50840501_46_dialog_content = "…うぐ…<size=45>ぐわっ…！</size>",
  ui_story_5084_50840501_47_dialog_content = "ヴィルヘルム様の様子がヘンだ…早くなんとかしないと！",
  ui_story_5084_50840501_48_dialog_content = "指輪のせい…？",
  ui_story_5084_50840501_49_option_content = "精神感知――",
  ui_story_5084_50840501_50_dialog_content = "フハハハハッ！あの女の指をかみ砕け！首をひねり潰せ！",
  ui_story_5084_50840501_51_dialog_content = "黙れ…",
  ui_story_5084_50840501_52_dialog_content = "指導者の座を守るために、真の指導者の前でぬけぬけと\n己を狂わせる指輪を身に着けるというのか。",
  ui_story_5084_50840501_53_dialog_content = "殺したいのはあの女か…それとも自分か、どちらだ？",
  ui_story_5084_50840501_54_dialog_content = "ふっ…痛みが麻痺するよう調教したのはお前ではないか…",
  ui_story_5084_50840501_55_dialog_content = "ワラーキ一族はお前の手によって滅びる。",
  ui_story_5084_50840501_56_dialog_content = "くっ…私を破滅に追いこみたいのなら、真理結社もろとも…",
  ui_story_5084_50840501_57_dialog_content = "あの女が自らの組織を作り、ワラーキの血脈を排除すれば、\n真理結社は生まれ変わる。",
  ui_story_5084_50840501_58_dialog_content = "あの女がワラーキを破滅させる。",
  ui_story_5084_50840501_59_dialog_content = "私もその中の1人になると？",
  ui_story_5084_50840501_60_dialog_content = "お前は彼らに殺されることでしか生き残れぬ…",
  ui_story_5084_50840501_61_dialog_content = "お前はいったい何の話をしているのだ？",
  ui_story_5084_50840501_62_dialog_content = "お前に死ねと言っているのだ！",
  ui_story_5084_50840501_63_dialog_content = "（なんて恐ろしい声なんだろう！\nヴィルヘルムさんを精神的に追い詰めようとしてるみたいだ…）",
  ui_story_5084_50840501_64_dialog_content = "（まさか…遺物が力の源で、\nそれを身に着けた者にとてつもない苦しみを与えるってこと？）",
  ui_story_5084_50840501_65_dialog_content = "（確かに真理結社らしいけど…）",
  ui_story_5084_50840501_66_dialog_content = "（それにしても、この声はどこから聞こえてるんだろう？\n指輪の最初の所有者？ワラーキのご先祖さん？それとも…）",
  ui_story_5084_50840501_67_dialog_content = "<size=45>う…わああああああ！</size>",
  ui_story_5084_50840501_68_dialog_content = "これ以上運命に逆らうのなら…",
  ui_story_5084_50840501_69_dialog_content = "出て…ゆけ！！！",
  ui_story_5084_50840501_70_dialog_content = "身の程知らずな。",
  ui_story_5084_50840501_71_dialog_content = "私の体から…<size=45>出ていけ！！！</size>",
  ui_story_5084_50840501_72_dialog_content = "主よ…！！！真理の道はどこにあるというのです！！！",
  ui_story_5084_50840501_73_dialog_content = "（ヴィルヘルムさん、失神寸前だ！）",
  ui_story_5084_50840501_74_dialog_content = "（声は意識の中で具像化して魔物になる…\nだったら、僕にもできることがあるはずだ！）",
  ui_story_5084_50840502_1_dialog_content = "ほお？新たな力を身につけたようだな…",
  ui_story_5084_50840502_2_dialog_content = "静かで…密やかな…",
  ui_story_5084_50840502_3_dialog_content = "…",
  ui_story_5084_50840502_4_dialog_content = "（まずい！バレたかも…）",
  ui_story_5084_50840502_5_dialog_content = "褒美として、おもしろいものを見せてやろう。",
  ui_story_5084_50840502_6_dialog_content = "彼に真理の祝福あれ。",
  ui_story_5084_50840502_7_dialog_content = "…ついにまた大事を成し遂げた。",
  ui_story_5084_50840502_8_dialog_content = "信者の血…久方ぶりの美味だ…",
  ui_story_5084_50840502_9_dialog_content = "して、そこからどんな真理を悟った？",
  ui_story_5084_50840502_10_dialog_content = "悟りか…ただ感激しかない。",
  ui_story_5084_50840502_11_dialog_content = "赤い月が空にかかる時のみ、\n血の一族は血への欲望を満たせる。",
  ui_story_5084_50840502_12_dialog_content = "信者は崇高な呪文を唱えながら踊り狂い、自らを傷つけ、先を争うようにいけにえとなる。\n彼らには理解しえない主に触れるためだけに。",
  ui_story_5084_50840502_13_dialog_content = "何百年もずっと…\n我々はそうして持ちつ持たれつの関係を続けてきたのだ…",
  ui_story_5084_50840502_14_dialog_content = "でも、それだけではとても足りないわ…",
  ui_story_5084_50840502_15_dialog_content = "聖鳴祭の夜だというのに、\nなぜもっと敬虔な信者を連れてこないの？",
  ui_story_5084_50840502_16_dialog_content = "それが信者の血を口にすることによって得た悟りか？",
  ui_story_5084_50840502_17_dialog_content = "さあ、どうかな。",
  ui_story_5084_50840502_18_dialog_content = "主が彼らの体を巡る時、我らはその血をすする。\n悟りし真理を後世に伝えるために。",
  ui_story_5084_50840502_19_dialog_content = "それが我ら当主が信者たちと結んだ契約だ。",
  ui_story_5084_50840502_20_dialog_content = "そこから真理をうかがい知ることができねば、\nいくらいけにえがいようと意味はない。",
  ui_story_5084_50840502_21_dialog_content = "君は悟りを開いたのか？",
  ui_story_5084_50840502_22_dialog_content = "もちろん。",
  ui_story_5084_50840502_23_dialog_content = "諸君、これは我が血の一族秘伝の戒律である。",
  ui_story_5084_50840502_24_dialog_content = "当主の地位にしかと向き合い、\nあの殺人狂の二の舞を演じぬよう願いたい。",
  ui_story_5084_50840502_25_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840502_26_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840502_27_dialog_content = "血脈が覚醒した時にすでに見ている。",
  ui_story_5084_50840502_28_dialog_content = "聖鳴祭に伝わる古い儀式だ。先祖たちは子羊の血を飲み干し、\n恍惚状態の中で神の啓示を得た。",
  ui_story_5084_50840502_29_dialog_content = "待って…！それって…聖鳴祭で啓示を受けた者は\n当主たちに食べられちゃうってこと？",
  ui_story_5084_50840502_30_dialog_content = "だから、あの時みんな笑ってたの！？",
  ui_story_5084_50840502_31_dialog_content = "ビクトリアは食べられちゃったってこと！？",
  ui_story_5084_50840502_32_dialog_content = "誰だ…？",
  ui_story_5084_50840502_33_dialog_content = "おや？お前の部屋に来客があったようだな。",
  ui_story_5084_50840502_34_dialog_content = "…",
  ui_story_5084_50840502_35_dialog_content = "PlayerName…なんかした？\nヴィルヘルム様、あたしたちに気づいてない？",
  ui_story_5084_50840502_36_dialog_content = "ごめん…さっきちょっと興奮しすぎたかも…",
  ui_story_5084_50840502_37_dialog_content = "ヴィルヘルムさんの意識の中で、恐ろしいものを見たんだ…",
  ui_story_5084_50840502_38_dialog_content = "ビクトリアが心配になってきた。もっと見て確めないと！",
  ui_story_5084_50840502_39_option_content = "精神感知――",
  ui_story_5084_50840502_40_dialog_content = "ならば、これは？",
  ui_story_5084_50840502_41_dialog_content = "姪を差し出しても、主の啓示は得られなかった。\nそれで頭がおかしくなったのか？",
  ui_story_5084_50840502_42_dialog_content = "やれやれ、君とつまらぬ遊びをするのも\nもううんざりだ。",
  ui_story_5084_50840502_43_dialog_content = "ヴィルヘルム！教典は私の手中にある。\n真理を知るのは私だ！",
  ui_story_5084_50840502_44_dialog_content = "…！これは予言か…？聖鳴祭…今夜…",
  ui_story_5084_50840502_45_dialog_content = "（教会にいた当主だ！今夜の聖鳴祭でビクトリアがいけにえにされる…\nつまり、今は1915年ってことだね！）",
  ui_story_5084_50840502_46_dialog_content = "信じぬというのか？",
  ui_story_5084_50840502_47_dialog_content = "…これが私…ヴィルヘルム・ワラーキの最期か？",
  ui_story_5084_50840502_48_dialog_content = "まだワラーキの持つ力を完全に理解していないお前が、\n己の不遇を理由に血の一族を死刑に処すというのか。",
  ui_story_5084_50840502_49_dialog_content = "いつの世でも若輩者は戒律や教義を侮るもの。",
  ui_story_5084_50840502_50_dialog_content = "だが真理結社の真の指導者が、お前でないことは確か。",
  ui_story_5084_50840502_51_dialog_content = "フフ…アハハハハ…",
  ui_story_5084_50840502_52_dialog_content = "真理？バカバカしい…",
  ui_story_5084_50840502_53_dialog_content = "兄の高貴な手に長らく留まっていたせいで、\n性格まで似てしまったようだな？",
  ui_story_5084_50840502_54_dialog_content = "私に当主を継がせる一方で、ビクトリアが指導者になった暁には\n自ら身を引けという呪いを残した…",
  ui_story_5084_50840502_55_dialog_content = "狙いをつけた者に偽りの未来を見せ、\nその者の意志を捻じ曲げ、己の目的を達成する。",
  ui_story_5084_50840502_56_dialog_content = "その手口は嫌というほど知っている…",
  ui_story_5084_50840502_57_dialog_content = "一度間違いを犯した私が同じ轍を踏むと思うか？",
  ui_story_5084_50840502_58_dialog_content = "ビクトリアを葬る気は一切ないのだな？",
  ui_story_5084_50840502_59_dialog_content = "ああ。",
  ui_story_5084_50840502_60_dialog_content = "迷いが見えるぞ。",
  ui_story_5084_50840502_61_dialog_content = "あの子を葬ろうとしているのは当主たちだ。私はワラーキ家の次男、その死に大した意味はない。\nだが奴らはビクトリアの強大化を恐れている。",
  ui_story_5084_50840502_62_dialog_content = "仮に予言が真実であるならば…",
  ui_story_5084_50840502_63_dialog_content = "ビクトリアの血脈覚醒はまだ先だ。\n私の伝える真理にも耳を傾けようとしない。",
  ui_story_5084_50840502_64_dialog_content = "私が死ねば、あの害虫どもが彼女を放ってはおくまい…",
  ui_story_5084_50840502_65_dialog_content = "ビクトリア…ビクトリア…",
  ui_story_5084_50840502_66_dialog_content = "（あれ？ビクトリアを心配してるの？）",
  ui_story_5084_50840502_67_dialog_content = "そうだ、真理結社の指導者たる私が啓示を受けし者を宣言すればいいのだ。だが…",
  ui_story_5084_50840502_68_dialog_content = "ビクトリアは今夜の聖鳴祭には出ないと言っていた…\nいったいどこへ行ったのか…",
  ui_story_5084_50840502_69_dialog_content = "ビクトリアはちょうど教会の壇上に上がったところだ。\n彼女はほんとにいけにえにされたんだ！",
  ui_story_5084_50840502_70_dialog_content = "いったい誰だ…？",
  ui_story_5084_50840502_71_dialog_content = "（ま、まずい…！）",
  ui_story_5084_50840502_72_dialog_content = "ふっ、まだ奥の手を残していたか。",
  ui_story_5084_50840502_73_dialog_content = "PlayerName！もしかしてまたやらかした…？",
  ui_story_5084_50840502_74_dialog_content = "…だってビクトリアをいけにえにするって言うから、つい…",
  ui_story_5084_50840502_75_dialog_content = "ビクトリア様をいけにえに…それって今夜？\nじゃあ前と一緒じゃない！？",
  ui_story_5084_50840502_76_dialog_content = "…ヴィルヘルムさんはビクトリアをすごく心配してるみたいだったけど、\n何をしようとしてるのか確かめないと…",
  ui_story_5084_50840502_77_dialog_content = "この書斎には…\nまだ<color=#FFB400>アストン・ワラーキ</color>の形見が残っているのか？",
  ui_story_5084_50840502_78_dialog_content = "それとも…主？",
  ui_story_5084_50840502_79_dialog_content = "先ほどビクトリアがいけにえになるとおっしゃいましたが…\n本当ですか？",
  ui_story_5084_50840502_80_dialog_content = "主？",
  ui_story_5084_50840502_81_dialog_content = "言え。今しがた誰と話をしていた？",
  ui_story_5084_50840502_82_dialog_content = "主だ…！",
  ui_story_5084_50840502_83_dialog_content = "…うぐっ！<size=45>忌々しい指輪め！！！！</size>",
  ui_story_5084_50840502_84_dialog_content = "私を殺せ…もう解放してくれ！！！",
  ui_story_5084_50840502_85_dialog_content = "お前もずいぶんとねじ曲がった奴だ。",
  ui_story_5084_50840502_86_dialog_content = "くっ…ぐわあああ！",
  ui_story_5084_50840502_87_dialog_content = "ハハハハハ――！真理結社の指導者は私！この私だ！！！",
  ui_story_5084_50840502_88_dialog_content = "（指輪の力がまたヴィルヘルムさんにダメージを与えた。どうしよう…）",
  ui_story_5084_50840502_89_dialog_content = "不甲斐ない奴だ。\nお前は死ぬことでしか生き残れぬと言っただろう。",
  ui_story_5084_50840502_90_dialog_content = "死など恐れはしない…\nだがビクトリアは…どうすれば！！！",
  ui_story_5084_50840502_91_dialog_content = "主よ…",
  ui_story_5084_50840502_92_dialog_content = "ビクトリアはこれからどうすれば…！！！",
  ui_story_5084_50840502_93_dialog_content = "完全に錯乱してる。このままじゃ死んじゃうよ！",
  ui_story_5084_50840502_94_dialog_content = "PlayerNameは感知してる精神に話しかけられるんでしょ？\nやってみたら？",
  ui_story_5084_50840502_95_dialog_content = "むやみに話しかけて、過去に影響が出てもまずいし…",
  ui_story_5084_50840502_96_dialog_content = "メイも真理の主を信仰してるよね？どんな言葉を聞いたら、\n苦しみや疑問を抱くことなく穏やかになったり、信用したりできる？",
  ui_story_5084_50840502_97_dialog_content = "そりゃ「真理の祝福あれ」と「導きのままに」でしょ。",
  ui_story_5084_50840502_98_dialog_content = "それだけでいいの…？じゃあやってみるよ…",
  ui_story_5084_50840502_99_option_content = "精神感知――",
  ui_story_5084_50840502_100_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840502_101_dialog_content = "…",
  ui_story_5084_50840502_102_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50840502_103_dialog_content = "真理の、祝福あれ…",
  ui_story_5084_50840502_104_dialog_content = "あなたは…いったい…",
  ui_story_5084_50840502_105_dialog_content = "（成功したみたいだ。これ以上失言しないように気をつけよう…）",
  ui_story_5084_50840502_106_dialog_content = "失礼だが、私はもはや人心を操る「神」を信じられない。\n私の心にある真理にもはや疑いの余地はないのだ。",
  ui_story_5084_50840502_107_dialog_content = "真理結社は…否、少なくともビクトリアの将来はこのままではいけない。",
  ui_story_5084_50840502_108_dialog_content = "真理の主を信じているのなら、分かるはずだ。",
  ui_story_5084_50840502_109_dialog_content = "今この時現れたのは、私に何か伝えるためだろう…？",
  ui_story_5084_50840502_110_dialog_content = "…導きのままに。",
  ui_story_5084_50840502_111_dialog_content = "…つまり現実を受け入れ、当主どもに食らわれる日を待てと…",
  ui_story_5084_50840502_112_dialog_content = "そしてビクトリアにも血の一族の呪いを引き継がせ、\n吸血鬼に殺されろと？",
  ui_story_5084_50840502_113_dialog_content = "（違う…悪い方向に向ってる気がする…）",
  ui_story_5084_50840502_114_dialog_content = "…そんなことが許されてなるものか！",
  ui_story_5084_50840502_115_dialog_content = "私がここまでこられたのは、一族からつまはじきにされた後、信奉する真理の修行に\nひとり励んできたからだ。その真理とはこんなものではない！",
  ui_story_5084_50840502_116_dialog_content = "啓示などというものを信じたせいで、真理結社はここまで堕落したのだ…",
  ui_story_5084_50840502_117_dialog_content = "私は必ずや…呪いを解く。",
  ui_story_5084_50840502_118_dialog_content = "なんとしても…",
  ui_story_5084_50840502_119_dialog_content = "…まだ指導者の息がかかっていない聖物は、\n<color=#FFB400>あれ</color>しかない…",
  ui_story_5084_50840502_120_dialog_content = "赤い月…藤蔓が人の姿に化す時、\n墓守の一族は墓所の主の到来を待つ。",
  ui_story_5084_50840502_121_dialog_content = "だが祖先の棺を運ぶ以外には、<color=#FFB400>鍵</color>を入手するしか陵墓に入る方法はない…\nあるいは当主らが一堂に会し立ち合うのなら、入れるのだが…",
  ui_story_5084_50840502_122_dialog_content = "ふっ、ヴィルヘルムよ！食われる寸前だというのにまだそのような掟にこだわるか。\nどうりで他人にもてあそばれるわけだ…！",
  ui_story_5084_50840502_123_dialog_content = "クラビスが鍵を渡してくれずとも、\n代々ワラーキ家に仕えてきた「藤蔓人」なら…",
  ui_story_5084_50840502_124_dialog_content = "私の得た啓示を知れば、きっと開けてくれるに違いない。",
  ui_story_5084_50840502_125_dialog_content = "墓所には巡行が始まる前に入らねば。",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>ゴオオ――！</color>",
  ui_story_5084_50840502_127_dialog_content = "メイ、しっかりつかまって！",
  ui_story_5084_50840502_128_dialog_content = "今度はどこに行くの？",
  ui_story_5084_50840502_129_dialog_content = "ワラーキの墓所だ！",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>ワラーキ村、縫い物屋の店先</color>",
  ui_story_5084_50840601_2_dialog_content = "賢明で器用なご婦人に真理の祝福あれ。",
  ui_story_5084_50840601_3_dialog_content = "寛大な紳士に真理の祝福あれ。なんと清々しいお方でしょう。\nきっと今年の啓示を受けし者に選ばれますわ。",
  ui_story_5084_50840601_4_dialog_content = "そう願いたいものです。ではこれにて。\n今夜の祝典でお会いしましょう、遅刻は厳禁ですよ。",
  ui_story_5084_50840601_5_dialog_content = "では祝典で。",
  ui_story_5084_50840601_6_dialog_content = "…私はなぜ…ここへ？",
  ui_story_5084_50840601_7_dialog_content = "あの、お客様も祝典のローブのお受け取りですか？",
  ui_story_5084_50840601_8_dialog_content = "祝典のローブ…？",
  ui_story_5084_50840601_9_dialog_content = "あら、きっと他の店のお客様ですね。",
  ui_story_5084_50840601_10_dialog_content = "ただうちは村で一番の老舗なんですよ。\n聖鳴祭のローブの注文も一番多くいただいています。",
  ui_story_5084_50840601_11_dialog_content = "辺鄙な村に住む信者さんは、\n祝典の夜にこぞってローブを取りに来られます。",
  ui_story_5084_50840601_12_dialog_content = "よろしければ、うちでローブを買い替えられてはいかがです？\nお買い得ですよ。",
  ui_story_5084_50840601_13_dialog_content = "…",
  ui_story_5084_50840601_14_dialog_content = "ほら、赤い月がもうすぐ姿を現します。",
  ui_story_5084_50840601_15_dialog_content = "…赤い月…聖鳴祭は今夜ですか…",
  ui_story_5084_50840601_16_dialog_content = "導師は祝典で私を啓示を受けし者に選ぶとおっしゃいました。\nですから、まずは清らかな衣装をそろえようと思いまして。",
  ui_story_5084_50840601_17_dialog_content = "啓示を受けし者！？\nそれは本当ですか…？",
  ui_story_5084_50840601_18_dialog_content = "啓示を受けし者を宣言なさるのはヴィルヘルム・ワラーキ様のはず。\nあなたはどうやって選ばれたのですか？",
  ui_story_5084_50840601_19_dialog_content = "ヴィルヘルム・ワラーキ様こそ私の導師です。墓所で出会ったのです。",
  ui_story_5084_50840601_20_dialog_content = "墓所…？ワラーキ家の墓所ですか…！？ならば、あなたは本当に…\nあの、どうやって真理を悟ったか教えていただけませんか？",
  ui_story_5084_50840601_21_dialog_content = "…私はいつも懺悔していますが、皆から避けられているようです。\n導師を除いては…",
  ui_story_5084_50840601_22_dialog_content = "懺悔…今日は聖鳴祭…赤い月…ああ、分かった気がします…",
  ui_story_5084_50840601_23_dialog_content = "啓示を受けしお方がここにいらしたのは、\n私にその真理を伝えるため…",
  ui_story_5084_50840601_24_dialog_content = "私は聖鳴祭にかこつけて信者からお金を受け取った…\nだから真理に近づけなかった…",
  ui_story_5084_50840601_25_dialog_content = "啓示をお授けくださりありがとうございます…",
  ui_story_5084_50840601_26_dialog_content = "ここで少し休憩していかれませんか？\n母や娘と超特急でローブを仕上げますので！",
  ui_story_5084_50840601_27_dialog_content = "そ、そんな申し訳ない…ただ偶然通りかかって、\n導師の居場所を尋ねようとしただけなのですが。",
  ui_story_5084_50840601_28_dialog_content = "偶然じゃありません。ここへいらしたのは真理、真理の導きです！\n勝手に色々申し上げてすみません――",
  ui_story_5084_50840601_29_dialog_content = "いえ、本当にその必要は…",
  ui_story_5084_50840601_30_dialog_content = "ママ？なにしてるの！？お客さんがイライラしながら待ってるよ！",
  ui_story_5084_50840601_31_dialog_content = "お客様に伝えて。\nうちのローブをタダで差し上げます、お代はいりませんって！",
  ui_story_5084_50840601_32_dialog_content = "はあ？",
  ui_story_5084_50840601_33_dialog_content = "今から、この啓示を受けしお方にローブを作って差し上げるの！",
  ui_story_5084_50840601_34_dialog_content = "今から？",
  ui_story_5084_50840601_35_dialog_content = "そうよ。",
  ui_story_5084_50840601_36_dialog_content = "おばあちゃん、絶対怒るよ…",
  ui_story_5084_50840601_37_dialog_content = "私の言う通りにして。おばあちゃんには私から説明するから。",
  ui_story_5084_50840601_38_dialog_content = "わかった…",
  ui_story_5084_50840601_39_dialog_content = "我が…主よ！私は先ほどまた過ちを犯しました…",
  ui_story_5084_50840601_40_dialog_content = "わずかばかりの金銭ならば…持ち合わせています…\nこの方々が儲け損なったお金を補填できればよいのですが…",
  ui_story_5084_50840601_41_dialog_content = "でもこれ以上縫い物屋の親子の気持ちを無にはできません…",
  ui_story_5084_50840601_42_dialog_content = "ヴィルヘルム。",
  ui_story_5084_50840601_43_dialog_content = "他人の名を呼び捨てするとはよい度胸だ。行く手を塞ぐ気か？\n私は今から聖鳴祭の儀式を執り行かなければならない。",
  ui_story_5084_50840601_44_dialog_content = "真理の細部を忘れ、現実に目を覆い隠されたか。",
  ui_story_5084_50840601_45_dialog_content = "お前は自らの責任を担いきれず、私に押し付けようとまでした…",
  ui_story_5084_50840601_46_dialog_content = "当主どもの手先か？かかって来い！",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>ロウソクが再び燃え上り、周囲にまた新たな光景が浮かび上がった――\n見るからに古そうな墓所が目の前に現れた</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>陰鬱な風が真正面から吹きつけ、藤蔓に長年積もる埃を吹き飛ばした</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>不意に藤蔓がうごめき始めた。それは思いのままに広がり、懐に閉じ込めた人物を解き放った…</color>",
  ui_story_5084_50840601_50_dialog_content = "着いたよ…あの人は…",
  ui_story_5084_50840601_51_dialog_content = "私はどうやってここへ…？",
  ui_story_5084_50840601_52_dialog_content = "さっき遭遇した「あの者」か？秘法を操って私をここへ送り込み…\n私の代わりに儀式に参加しようと…",
  ui_story_5084_50840601_53_dialog_content = "赤い月が隠れている…今はいつだ？まさか聖鳴祭を逃したのか？",
  ui_story_5084_50840601_54_dialog_content = "あなたは栄えある啓示を与えられたのです。",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>墓所入口の藤蔓は絡み合い、人の姿を形作った。\nその顔はやせこけ、目は憂いを帯びていた</color>",
  ui_story_5084_50840601_56_dialog_content = "ご先祖様の墓所はすでに開いております。",
  ui_story_5084_50840601_57_dialog_content = "これは…どういうことだ？",
  ui_story_5084_50840601_58_dialog_content = "<color=#FFB400>鍵</color>はここにございます。感じます…「あの炎」の存在を。",
  ui_story_5084_50840601_59_dialog_content = "炎？ここで唯一燃えてるのは…このロウソクだけでしょ？",
  ui_story_5084_50840601_60_dialog_content = "まさか…僕が原因なの？僕の声がヴィルヘルムさんをここに導いて、この扉を開けたの？",
  ui_story_5084_50840601_61_dialog_content = "いったい何を変えちゃったんだろう？",
  ui_story_5084_50840601_62_dialog_content = "待ってくれ、私はなにも…",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>ヴィルヘルムの言葉をさえぎるように藤蔓の人型は消え去り、\n青苔に覆われた地面に戻って寡黙な門番へと姿を変えた</color>",
  ui_story_5084_50840601_64_dialog_content = "墓所の扉が開き、墓守に進入を許された…",
  ui_story_5084_50840601_65_dialog_content = "私は一切手を下していない。\nまさかこれが真理の思し召しなのか？",
  ui_story_5084_50840601_66_dialog_content = "運命が私をここへ導いた。\n主は私に自らの使命を果たすよう望まれたのだ。",
  ui_story_5084_50840601_67_dialog_content = "中に入ってみなければ。",
  ui_story_5084_50840601_68_dialog_content = "どうするつもりだろう…メイ、後を追うよ！",
  ui_story_5084_50840601_69_dialog_content = "ワラーキの先祖よ、啓示が存在するのならば、\nより明確にお示しを…",
  ui_story_5084_50840601_70_dialog_content = "先祖の棺はどこだ！？\n巡行が終われば、ここに戻されるはず…",
  ui_story_5084_50840601_71_dialog_content = "ワラーキ家の安眠の地を冒涜するとは何事だ…いや…",
  ui_story_5084_50840601_72_dialog_content = "やはり見あたらない…先祖の棺も、教典までなくなっている…",
  ui_story_5084_50840601_73_dialog_content = "当主どもが早々に手を打ったのか？",
  ui_story_5084_50840601_74_dialog_content = "ビクトリアの身が危ない…！",
  ui_story_5084_50840601_75_dialog_content = "「霜夜の紳士」！村の教会へ！",
  ui_story_5084_50840601_76_dialog_content = "かっこいい黒馬だね…じゃなかった！さっさと追いかけよう！",
  ui_story_5084_50840601_77_dialog_content = "死徒？なぜここを徘徊しているのだ！？",
  ui_story_5084_50840601_78_dialog_content = "信者の遺体？やはり村でゆゆしき事態が…！",
  ui_story_5084_50840601_79_dialog_content = "穢れにまみれた下等な輩が不遜にもこの地に足を踏み入れ、\n信者を傷つけるとは言語道断！",
  ui_story_5084_50840601_80_dialog_content = "意識を失った愚か者め、\nさては貴様らの主が解き放ったのだな。",
  ui_story_5084_50840601_81_dialog_content = "ならばこのまま浄化してやろう！",
  ui_story_5084_50840602_1_dialog_content = "おお、我らが指導者…ヴィルヘルム・ワラーキ様、\nなんと魅力に満ちたお方。",
  ui_story_5084_50840602_2_dialog_content = "あのお方の啓示によって、\n私は真理の扉の向こうを垣間見た。",
  ui_story_5084_50840602_3_dialog_content = "信者たちは化け物どもの悪行に一切気づいていないようだ…",
  ui_story_5084_50840602_4_dialog_content = "聖鳴祭の儀式はすでに終わった。\n当主たちはまだ教会にいるはず…",
  ui_story_5084_50840602_5_dialog_content = "や…やっと追いついた…ふぅ…ふぅ…",
  ui_story_5084_50840602_6_dialog_content = "メイ、あそこ！前に君が布教した信者たちだ。\nってことは、時間が繋がったんだ！",
  ui_story_5084_50840602_7_dialog_content = "あの時の僕たちがきっと中にいるはずだよ！",
  ui_story_5084_50840602_8_dialog_content = "信者たちがこぞって帰っていったので、儀式は終わったものと思っていました。\nまさかあなたがここで待っていてくださるとは。",
  ui_story_5084_50840602_9_dialog_content = "ネイルス！どうしてここに！？",
  ui_story_5084_50840602_10_dialog_content = "その恰好は…？",
  ui_story_5084_50840602_11_dialog_content = "善良な縫い物屋が作ってくれたのです。\nとても感激しました。",
  ui_story_5084_50840602_12_dialog_content = "導師、私をお呼びくださり、心より感謝いたします。",
  ui_story_5084_50840602_13_dialog_content = "君は…",
  ui_story_5084_50840602_14_dialog_content = "え？ネイルスは何の話をしてるの？",
  ui_story_5084_50840602_15_dialog_content = "ネイルスさんの話はいつもよくわかんない…",
  ui_story_5084_50840602_16_dialog_content = "私は嬉しいのです。この度の儀式のいけにえになれることが！",
  ui_story_5084_50840602_17_dialog_content = "私のあずかり知らぬことだ。失礼する。",
  ui_story_5084_50840602_18_dialog_content = "ポルフィリオ、教典はどこだ？",
  ui_story_5084_50840602_19_dialog_content = "逆に聞くが、さっきの黒風はなんだ？\nビクトリアはどこへ行った！",
  ui_story_5084_50840602_20_dialog_content = "ビクトリア？",
  ui_story_5084_50840602_21_dialog_content = "姪を差し出しても、主の啓示は得られなかった。\nそれで頭がおかしくなったのか？",
  ui_story_5084_50840602_22_dialog_content = "やれやれ、君とつまらぬ遊びをするのも\nもううんざりだ。",
  ui_story_5084_50840602_23_dialog_content = "ヴィルヘルム！教典は私の手中にある。\n真理を知るのは私だ！",
  ui_story_5084_50840602_24_dialog_content = "ただ…今年の儀式はもう終わったが、\nまだ話し合いの余地はある。",
  ui_story_5084_50840602_25_dialog_content = "予言で見た光景だ…ふっ、話し合うだと？\n私を手にかけるつもりだろう！",
  ui_story_5084_50840602_26_dialog_content = "お芝居はもういい。手下に命じて罪なき信者を傷つけたのは貴様だろう。\nだが、化け物どもは私がすべて浄化した！",
  ui_story_5084_50840602_27_dialog_content = "かくなるうえは…",
  ui_story_5084_50840602_28_dialog_content = "我々に屈する気はないようだな…私はまだ聖言を聞かねばならない。\n2人とも、ここまでご苦労であった。",
  ui_story_5084_50840602_29_dialog_content = "そうはさせない！",
  ui_story_5084_50840602_30_dialog_content = "ヴィルヘルム、無駄だ。教典は私の手中にある。\n運命はすでに我々の味方だ…",
  ui_story_5084_50840602_31_dialog_content = "「クサリヘビ」、出番だ。",
  ui_story_5084_50840602_32_dialog_content = "導師に何をするのです？啓示を受けし者は私です。",
  ui_story_5084_50840602_33_dialog_content = "どこのどいつだ？",
  ui_story_5084_50840602_34_dialog_content = "ヴィルヘルムにも味方がいるのなら、\nそいつを先にやっちまわないとな。",
  ui_story_5084_50840602_35_dialog_content = "真理結社につらなる家の当主でありながら、\n信者を傷つけるなどもってのほか！",
  ui_story_5084_50840602_36_dialog_content = "他人より自分の心配をしたらどうだ、ウハハハッ！",
  ui_story_5084_50840602_37_dialog_content = "ヴィルヘルム…！",
  ui_story_5084_50840602_38_dialog_content = "我が主よ、あなたの痛みを私に与え、苦しみを背負わせたまえ。\nどうか私を取り込み、堕落させたまえ。真理は必ずや暴力を凌駕するでしょう…",
  ui_story_5084_50840602_39_dialog_content = "ダメです、ネイルスさん！早く逃げて――",
  ui_story_5084_50840602_40_dialog_content = "ダメだよ、メイ！僕たちは介入しちゃいけないんだ…\nスカーレイの言葉を忘れたの？",
  ui_story_5084_50840602_41_dialog_content = "全部僕のせいだ…僕が話しかけたせいで変わっちゃったんだ…\nなんとかして助けなきゃ！まだロウソクがあるし、きっと方法はある！",
  ui_story_5084_50840602_42_dialog_content = "ふっ、これは驚いた。\n敬虔な頑固者か。",
  ui_story_5084_50840602_43_dialog_content = "死ね！",
  ui_story_5084_50840602_44_dialog_content = "主よ、あなたの儀式がこれほどまでに残酷とは。信者はみな同様の経験をするのでしょうか？\n彼らはいかにこの苦難を乗り越えるのでしょう。",
  ui_story_5084_50840602_45_dialog_content = "私は辛酸に耐え、呑み下し、自らの罪を洗い流します。\n苦しみという呪いを受け止め、なめつくし、魂の傷口を焼き払うのです――",
  ui_story_5084_50840602_46_dialog_content = "苦しみが他者に及ばぬよう、私にすべての苦痛をお与えください。\nさあ、我が身の傷をもって、その大罪を祓い清めてくださいますよう！",
  ui_story_5084_50840602_47_dialog_content = "私がその痛みをもって、彼らの罪を贖います。",
  ui_story_5084_50840602_48_dialog_content = "（このままじゃネイルスが殺されちゃう！どうにかしないと…\n燭台！どうかこの状況を変えられる時間へ僕を…）",
  ui_story_5084_50840602_49_dialog_content = "愚か者めが！",
  ui_story_5084_50840602_50_dialog_content = "彼らには儀式を執り行う気も、君の魂を清める気もない。\nただ君を殺そうとしているのだ！",
  ui_story_5084_50840602_51_dialog_content = "君は苦行者か？\nならば生き抜いて、もがき苦しみながら真理をつかみとれ！",
  ui_story_5084_50840602_52_dialog_content = "導師？",
  ui_story_5084_50840602_53_dialog_content = "生きるのだ！",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>ヴィルヘルムは驚くべき力でネイルスを引き起こし、扉の外へ放り出した。\n開いた扉からは黒風が吹き込んできた</color>",
  ui_story_5084_50840602_55_dialog_content = "あっ、ロウソクが消えた！",
  ui_story_5084_50840602_56_dialog_content = "次はどうする？思う存分かかってこい！\nこのヴィルヘルム・ワラーキが易々と屈すると思うな！",
  ui_story_5084_50840602_57_dialog_content = "私の剣を、とくと味わうがいい！",
  ui_story_5084_50840602_58_dialog_content = "出でよ、<color=#FF0000>赤流</color>！我が魔剣よ！\n我が血を喰らい、敵の生気を奪うのだ！",
  ui_story_5084_50840602_59_dialog_content = "どうなってるの…戦うの？",
  ui_story_5084_50840602_60_dialog_content = "わかんないよ。なにも見えないもん！",
  ui_story_5084_50840602_61_dialog_content = "場面がまた変わりかけてるけど、最後まで見届けないと！\nなんとか制御して…転送を止める――",
  ui_story_5084_50840602_62_dialog_content = "メイ、僕につかまって後ろに下がって！",
  ui_story_5084_50840602_63_dialog_content = "くそっ、ここは暗すぎる。",
  ui_story_5084_50840602_64_dialog_content = "こうなると、やつとて1人では一溜りもないはず。",
  ui_story_5084_50840602_65_dialog_content = "あっ！",
  ui_story_5084_50840602_66_dialog_content = "さてと、次は誰だ？",
  ui_story_5084_50840602_67_dialog_content = "クラビス、私の背後に回れ。共に戦おう！",
  ui_story_5084_50840602_68_dialog_content = "…",
  ui_story_5084_50840602_69_dialog_content = "無駄だ。たとえ頭をかち割られても、俺は死なない。",
  ui_story_5084_50840602_70_dialog_content = "では遠慮なく頭をかち割って耐えがたい痛みを与えてやろう！",
  ui_story_5084_50840602_71_dialog_content = "すごい…1人で大勢に立ち向かってる。\nしかも暗いのに…全然負けてない。",
  ui_story_5084_50840602_72_dialog_content = "仲間だろう…早く手を貸せ。",
  ui_story_5084_50840602_73_dialog_content = "口で言うのは簡単だがな…",
  ui_story_5084_50840602_74_dialog_content = "まだ他人を当てにしているのか？デービー、貴様の死は必然！\n期待するだけ無駄だ！",
  ui_story_5084_50840602_75_dialog_content = "取り引きを忘れたか…",
  ui_story_5084_50840602_76_dialog_content = "…",
  ui_story_5084_50840602_77_dialog_content = "<size=45>あ――！！</size>",
  ui_story_5084_50840602_78_dialog_content = "え？どういうこと？\n急にヴィルヘルムさんの気配が消えた…まさか…",
  ui_story_5084_50840602_79_dialog_content = "早くつかまって、たぶん…次の場所に「送られる」！",
  ui_story_5084_50840602_80_dialog_content = "…どういうこと？どうして、こんなことに？",
  ui_story_5084_50840602_81_dialog_content = "…ヴィルヘルムさんが本当に死んじゃってたら…\nビクトリアはどうすれば？",
  ui_story_5084_50840602_82_dialog_content = "PlayerName、さっきのヴィルヘルム様ってぜんぜん冷酷じゃなかったよね？\nホントにビクトリア様をいけにえにしたのかな…",
  ui_story_5084_50840602_83_dialog_content = "僕も同じこと考えてたんだ…ロウソクの力で移動を始めてから出会ったヴィルヘルムさんと\n儀式の時のヴィルヘルムさんはまるで別人みたいだった…",
  ui_story_5084_50840602_84_dialog_content = "僕が話しかけたから、こうなったのかな…",
  ui_story_5084_50840602_85_dialog_content = "それとも2人のヴィルヘルムさんの間には、別のつながりがあるとか…",
  ui_story_5084_50840602_86_dialog_content = "ビクトリア様は今どこにいるんだろう…",
  ui_story_5084_50840602_87_dialog_content = "いけにえの儀式で、聖鳴祭の後ヴィルヘルムさんが失踪したって言ってたよね？\n今ビクトリアは、その失踪の真相を明かそうとしてるのかも。",
  ui_story_5084_50840602_88_dialog_content = "あのいけにえの儀式には…まだ何かある…\nビクトリアが過去に介入したのも、きっと調べたいことがあるからなんだ。",
  ui_story_5084_50840602_89_dialog_content = "ヴィルヘルムさんとの間にも長い間誤解があるみたいだし…\n口に出せない思いが色々あるんだと思う。",
  ui_story_5084_50840700_1_dialog_content = "ここ、ロウソクや花壇がいっぱいあるね！PlayerName、あれは…棺！？",
  ui_story_5084_50840700_2_dialog_content = "たぶん、そうだね…",
  ui_story_5084_50840700_3_dialog_content = "あたしたち、今度はどこに来たのかな？",
  ui_story_5084_50840700_4_dialog_content = "窓の外はなんだか気味が悪い感じだね…",
  ui_story_5084_50840700_5_dialog_content = "ここは崖に立つ古城だ！誰がこんな場所に建てたんだろう…",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>コツコツコツ――</color>",
  ui_story_5084_50840700_7_dialog_content = "あっ、ビクトリア様だ！",
  ui_story_5084_50840700_8_dialog_content = "どうしてだろう…さっきビクトリアのことを考えてたからかな？",
  ui_story_5084_50840700_9_dialog_content = "待って、もう1人いる。",
  ui_story_5084_50840700_10_dialog_content = "君もヴィルヘルムを訪ねて来たのか？",
  ui_story_5084_50840700_11_dialog_content = "奴の住まいに来るのは、敵のほかは親族しかいないからな。",
  ui_story_5084_50840700_12_dialog_content = "どこへ行ったの？",
  ui_story_5084_50840700_13_dialog_content = "残念だが、私にもわからない。\n何も残さずに立ち去ったからね。",
  ui_story_5084_50840700_14_dialog_content = "それは残念ね。\nあの人にも心を許せる親友の1人や2人はいると思っていたのに。",
  ui_story_5084_50840700_15_dialog_content = "かつては確かにそうだった。",
  ui_story_5084_50840700_16_dialog_content = "ヴィルヘルムが…無鉄砲な行いをしなければ、\nいつまでも親友でいられただろう。",
  ui_story_5084_50840700_17_dialog_content = "ビクトリア、君は少しも理解していない…自分の叔父を。\nそうだろう？",
  ui_story_5084_50840700_18_dialog_content = "あんな人を理解したいとは思わないわ。",
  ui_story_5084_50840700_19_dialog_content = "君の父上が真理結社の指導者になるまで、\nヴィルヘルムはその座を奪おうと必死だった。",
  ui_story_5084_50840700_20_dialog_content = "彼は欲に目がくらみ、極論に走り、それを真理として崇めた。",
  ui_story_5084_50840700_21_dialog_content = "だからこそ、先祖の力を継承する際に錯乱してしまったのだ…\nあの時奴はすでに一族の異端者であったのに、それを認めようとはしなかった。",
  ui_story_5084_50840700_22_dialog_content = "その未練から彼は野心家の傀儡となり、\n結局は一族から追放された。",
  ui_story_5084_50840700_23_dialog_content = "…あの人の過去に興味はないわ。",
  ui_story_5084_50840700_24_dialog_content = "あの人の支配から逃れられて、心からうれしいもの。",
  ui_story_5084_50840700_25_dialog_content = "外遊中に主の啓示を聞いたの…\n今日はお別れを言いに来ただけ。",
  ui_story_5084_50840700_26_dialog_content = "私は啓示のあった場所に向かい、\n真理の主の降臨を待つつもりよ。",
  ui_story_5084_50840700_27_dialog_content = "君はワラーキの血脈を受け継ぐ者だ。\n自分自身で決めればいい。",
  ui_story_5084_50840700_28_dialog_content = "それはそうと、1つ教えてくださる？あの時あの人が…\nヴィルヘルムがあなたから借りようとしていたものは何だったの？",
  ui_story_5084_50840700_29_dialog_content = "あの<color=#FFB400>鍵</color>は、君を傷つけるだけだ。",
  ui_story_5084_50840700_30_dialog_content = "死を前にした兄はわざわざそれを<color=#FFB400>藤蔓人</color>から取り戻し、君に渡した…\n私の手に渡すためにそうしたのは明らかだ。",
  ui_story_5084_50840700_31_dialog_content = "…君が<color=#FFB400>藤蔓人</color>から強奪するのを避けるため\nという可能性もある。",
  ui_story_5084_50840700_32_dialog_content = "…あれは「万門の鍵」だ…\n野心に燃える者は、ただひたすら翻弄されるだけだ。",
  ui_story_5084_50840700_33_dialog_content = "…ビクトリア、どうか達者でな。\n君はまだ重責を担ったばかり。真理を探る旅はまだまだ続くはずだ。",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>ビクトリアはクラビスの背中を見送り、立ち去るのを見届けると、\nようやく身を翻しヴィルヘルムの部屋に入った</color>",
  ui_story_5084_50840700_35_dialog_content = "私には理解できない人…あなたは今どこにいるの？",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>彼女は部屋をぐるりと見回し、最後にあのきらびやかな棺を開くと\nふわりとそこに横たわった</color>",
  ui_story_5084_50840700_37_dialog_content = "あなたを親のように思えたら…\nあなたが追い求めるもののすべてを理解できるのかしら？",
  ui_story_5084_50840700_38_dialog_content = "（この感じ…ビクトリアが記憶をたどってる…）",
  ui_story_5084_50840700_39_dialog_content = "今日は一堂に会し、皆でワラーキ家当主の死を悼もうではないか。",
  ui_story_5084_50840700_40_dialog_content = "今日より彼ら2人は先祖の列に加えられる。\n独り残された哀れな娘――ビクトリア・ワラーキよ。",
  ui_story_5084_50840700_41_dialog_content = "こちらへ。この指輪を自らの手でお父上の墓碑に供えたまえ。\nこれは彼の栄誉の証。今この瞬間も我々の敬意は彼と共にあるべきだ。",
  ui_story_5084_50840700_42_dialog_content = "お父さま…お母さま…",
  ui_story_5084_50840700_43_dialog_content = "慌てずともよい――\n独り残された娘が混乱に陥り、悲しみに暮れるのは当然のこと。",
  ui_story_5084_50840700_44_dialog_content = "安心なさい。我々が君のそばで、共にこの困難な時を乗り越えよう――\nそうだ、私の名はデービー・ポルフィリオという。",
  ui_story_5084_50840700_45_dialog_content = "お父上が血脈の混乱を平定してくださったお陰で、\n私は得がたい理性を手にすることができた。",
  ui_story_5084_50840700_46_dialog_content = "私はクラビス・アブラハムだ。\n我が家とワラーキとの友情は永遠だ。",
  ui_story_5084_50840700_47_dialog_content = "助けが必要な時は、いつでも声をかけてほしい。",
  ui_story_5084_50840700_48_dialog_content = "お嬢様…私めの名などお知りになる必要はございません。\n召使いとお呼びください。",
  ui_story_5084_50840700_49_dialog_content = "お父さまも…そう呼んでいらしたの？",
  ui_story_5084_50840700_50_dialog_content = "グレイブと呼んでおられました…",
  ui_story_5084_50840700_51_dialog_content = "時間とはなんと残酷なものよ。俺はもう自分の名を忘れてしまった…\nみなは俺を<color=#FFB400>クサリヘビ</color>と呼ぶ。お嬢さんもそう呼んでくれたらいい。",
  ui_story_5084_50840700_52_dialog_content = "これにて儀式を終え、ワラーキ家の当主は安息を得た。\n諸君、そろそろ未来を語る頃合いではないか。",
  ui_story_5084_50840700_53_dialog_content = "ビクトリア嬢、君はこの指輪の力に耐えるにはまだ若すぎる。",
  ui_story_5084_50840700_54_dialog_content = "これはしばらく私が預かっておく――心配は無用だ。\nワラーキ以外の者にとっては、どこにでもある指輪と同じ…",
  ui_story_5084_50840700_55_dialog_content = "そうか？\nでは、なぜそれほどまで執着するのだ？",
  ui_story_5084_50840700_56_dialog_content = "ヴィルヘルム・ワラーキ！？",
  ui_story_5084_50840700_57_dialog_content = "フン、ワラーキ家の血統がもう1人いるのを忘れるな。\n真理結社の指導者になれるのは、ワラーキのみ。",
  ui_story_5084_50840700_58_dialog_content = "…",
  ui_story_5084_50840700_59_dialog_content = "ワラーキ家を追放された異端者が、\nよくもビクトリア嬢の前でそのような妄言を口にできるものだ！",
  ui_story_5084_50840700_60_dialog_content = "目に焼きつけよ、今こそ私が先祖の知恵と力を継承する時だ！",
  ui_story_5084_50840700_61_dialog_content = "うっ…",
  ui_story_5084_50840700_62_dialog_content = "ハハハハッ！その落胆した顔はなんだ？\nワラーキ家の者が指輪をはめる姿を見たくなかったようだな。",
  ui_story_5084_50840700_63_dialog_content = "見届けよ！\nこのヴィルヘルム・ワラーキが暗影で君たちを覆いつくしてやろう。",
  ui_story_5084_50840700_64_dialog_content = "私こそが先祖に認められしワラーキの新当主！",
  ui_story_5084_50840700_65_dialog_content = "ヴィルヘルム…まだ野心を捨てていなかったのか。",
  ui_story_5084_50840700_66_dialog_content = "フッ…フハハハッ、ビクトリア嬢、\n叔父上は正統な後継者である君に地位を譲るつもりはないようだ。",
  ui_story_5084_50840700_67_dialog_content = "これはワラーキ家の問題。我々がむやみに手出しすべきではない…\nこれにて失礼する。",
  ui_story_5084_50840700_68_dialog_content = "ヴィルヘルム・ワラーキ…叔父さま…",
  ui_story_5084_50840700_69_dialog_content = "どこへ行くの？",
  ui_story_5084_50840700_70_dialog_content = "もちろんここを離れ、\n受け継いだ領地に向かうに決まっている。",
  ui_story_5084_50840700_71_dialog_content = "ビクトリア、今日から私が後見人だ。\n私が当主を務める間は、指示に従ってもらう。",
  ui_story_5084_50840700_72_dialog_content = "…いつか私は天啓を得る。その指輪は父の形見。\nそれは私のものよ。",
  ui_story_5084_50840700_73_dialog_content = "好きにするがいい。\nだが今は私の手の中にある。",
  ui_story_5084_50840700_74_dialog_content = "ただ…天啓と言ったな？ビクトリア、君はずいぶんと早熟なようだが――\n答えてみろ、真理とは何か？",
  ui_story_5084_50840700_75_dialog_content = "真理とは…知識。",
  ui_story_5084_50840700_76_dialog_content = "ふっ、ビクトリア・ワラーキ。我々は同じ血統につらなる者。\nだが頭脳、パワー、能力…それに姿形、どれをとっても私の方が優れている。",
  ui_story_5084_50840700_77_dialog_content = "にも関わらず、この指輪が自分のものだと思うのはなぜだ？",
  ui_story_5084_50840700_78_dialog_content = "私こそが真のワラーキ、真理結社の指導者だ！",
  ui_story_5084_50840700_79_dialog_content = "まずは…証明してみせろ――己がワラーキの名にふさわしい者だとな。\n私の顔に泥を塗るなよ。",
  ui_story_5084_50840700_80_dialog_content = "（ヴィルヘルムさん…ずいぶん厳しいな…\n本気で言ってるのかな…子ども相手に？）",
  ui_story_5084_50840700_81_dialog_content = "（でも、その「子ども」っていうのもビクトリアだし…\nうーん、おかしいな。僕たちが会ったヴィルヘルムさんはこんなんじゃ…）",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>外では閃光が走り、雷鳴がとどろいていた。\n幼いビクトリアは両親の棺を開け、その中に入った</color>",
  ui_story_5084_50840700_83_dialog_content = "お父さま…お母さま…",
  ui_story_5084_50840700_84_dialog_content = "私はどうすればいいの？教えて…",
  ui_story_5084_50840700_85_dialog_content = "家…？どうやって戻ってきたのかしら…",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>ガサッ――</color>",
  ui_story_5084_50840700_87_dialog_content = "ワラーキの家で騒いでいるのは誰――",
  ui_story_5084_50840700_88_dialog_content = "…なぜあなたがここに？使用人たちは？",
  ui_story_5084_50840700_89_dialog_content = "全員暇をとらせた。これからは時間が我々の従僕だ。\n時間ならいくらでもある。",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>ヴィルヘルム・ワラーキ――ビクトリアの生活に突如として現れたこの人物が、\nこの日から叔父として彼女を常に監督することとなった</color>",
  ui_story_5084_50840700_91_dialog_content = "こんな檻の中で暮らすなど、ビクトリア嬢もなんと気の毒な。\n我々も心を痛めてはいるのだが、いかんともしがたく…実に申し訳ない。",
  ui_story_5084_50840700_92_dialog_content = "ヴィルヘルムが「当主の長」である限り、我々も言いなりになるより他ない。\n君に近づくなと警告されたのだが…",
  ui_story_5084_50840700_93_dialog_content = "君の健康を案じて、無謀にもはせ参じた…\nこれでようやく安心できたよ。",
  ui_story_5084_50840700_94_dialog_content = "あの人はひたすら私を警戒しているのです。\n私があなた方と共謀して自分の地位を奪うのではないかと。",
  ui_story_5084_50840700_95_dialog_content = "そう、彼は恐れているのだ…君のお父上は彼を凌駕する才能の持ち主だった。\n彼など、もはや時代遅れの異端児にすぎない。",
  ui_story_5084_50840700_96_dialog_content = "ビクトリア嬢、確かめたいのだが、君もお父上と同様、天賦の才を持っているはず…\nならば、先祖の聖杯と共鳴できるのかね？",
  ui_story_5084_50840700_97_dialog_content = "それは一体どのような感覚なのだ？",
  ui_story_5084_50840700_98_dialog_content = "感覚…誰かが脳内に入ってきて、\nかつてどんな美酒が流行ったかを語るような感覚でしょうか。",
  ui_story_5084_50840700_99_dialog_content = "淡々と物語を語ることもあります。それはまるで…",
  ui_story_5084_50840700_100_dialog_content = "おい！\n誰がこのヴィルヘルム・ワラーキの領地に入っていいと言った？",
  ui_story_5084_50840700_101_dialog_content = "フッ、ヴィルヘルムか。ビクトリア嬢のことが気になったものでね。\nすぐにお暇する。",
  ui_story_5084_50840700_102_dialog_content = "この子はつつがなく暮らしている。\n「新鮮な血液」に期待するのは止してもらおうか。",
  ui_story_5084_50840700_103_dialog_content = "ましてや君の期待に沿うように、\n嘘を吹きこむなどもってのほか！",
  ui_story_5084_50840700_104_dialog_content = "私が誰と話をしようと、叔父さまの許可は必要ないわ。",
  ui_story_5084_50840700_105_dialog_content = "世間知らずにも程がある。\nかび臭い本に没頭していては、世事に疎い知識人になるだけだ。",
  ui_story_5084_50840700_106_dialog_content = "先祖の墓の中に「紅血の教典」という本があるのは知っているな？\nそこに記された啓示は、どれだけ古書を漁っても知りえないものだ。",
  ui_story_5084_50840700_107_dialog_content = "だが君は両親が亡くなってから、先祖の陵墓に参っていないな。",
  ui_story_5084_50840700_108_dialog_content = "まあいい。真理結社を嫌うのは間違いではない。\nだが、それには感情ではなく、正当な理由がなくてはならない。",
  ui_story_5084_50840700_109_dialog_content = "さもなくば、ただの子どもの癇癪だ。",
  ui_story_5084_50840700_110_dialog_content = "誰の指図も受けたくない。\nそのために私は強くならなければいけない。",
  ui_story_5084_50840700_111_dialog_content = "そうして私は、儀式や太古の遺物との共鳴を通じて、\n真理のありかを探し始めた…",
  ui_story_5084_50840700_112_dialog_content = "どこなの？「古代の秘密の教え」はどこにあるの…",
  ui_story_5084_50840700_113_dialog_content = "真理の主は自ら私の夢に降臨され、\nヴィルヘルムに不在を気づかれる前に、主の秘密を見つける手助けをしてくださった…",
  ui_story_5084_50840700_114_dialog_content = "あっ！",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>星</color>…<color=#FFB400>星</color>を呑み込んでいる…時間がない、時間が…<color=#FFB400>再生の時</color>は近い…",
  ui_story_5084_50840700_116_dialog_content = "<size=45>終結の真の意味はあの闇の中にある――！</size>",
  ui_story_5084_50840700_117_dialog_content = "この愚か者め！手の中にある物は何だ？\nむやみに太古の遺物と共鳴するとは何事だ！",
  ui_story_5084_50840700_118_dialog_content = "昔日の知恵、狂人の啓示――\nヴィルヘルム・ワラーキの名のもとに、その娘から離れろ！",
  ui_story_5084_50840700_119_dialog_content = "…あっ！",
  ui_story_5084_50840700_120_dialog_content = "…ゆっくり眠るがいい。",
  ui_story_5084_50840700_121_dialog_content = "助けてくれたの？なぜここにいると…",
  ui_story_5084_50840700_122_dialog_content = "遺物の特性を見分ける目を持つことから始めろ。\nさもなくば、次は君の骨を拾わなければならなくなる。",
  ui_story_5084_50840700_123_dialog_content = "ついでに言っておくが、誤解するな。\n真理結社の指導者たる私が、兄の娘に危害を加えたと疑われたくないから助けただけだ。",
  ui_story_5084_50840700_124_dialog_content = "君を手元に置くのも、地位を守るのに便利だからにすぎない。",
  ui_story_5084_50840700_125_dialog_content = "何しろ血の一族というのは、瀕死の者を見ると、\n助けるよりもひねり殺して新鮮な血を味わいたくなるものだからな。",
  ui_story_5084_50840700_126_dialog_content = "ヴィルヘルム・ワラーキ…！",
  ui_story_5084_50840700_127_dialog_content = "尊大で傲慢で忌々しいヴィルヘルム・ワラーキ。\nあの人はいつもおかしな理屈をこじつけては、私の人生を縛りつけようとする。",
  ui_story_5084_50840700_128_dialog_content = "でも、その憎らしい叔父以外の人たちも、皆似たり寄ったり。",
  ui_story_5084_50840700_129_dialog_content = "当主たちはそろいもそろって腹に一物ある、愚かな変わり者ばかり…\n中にはうじ虫のごとく無知な一族もいる。まるで肉の塊がぞろぞろ村を歩いているよう。",
  ui_story_5084_50840700_130_dialog_content = "彼らの喧伝する愚かで邪悪な思想は、真理を求める信者たちには何の役にも立たない。\nそんな人たちに迷える子羊は救えない。",
  ui_story_5084_50840700_131_dialog_content = "警戒を怠ってはいけない…\nどこまでも慎重に、真理結社の因習に染まらないようにしなければ。",
  ui_story_5084_50840700_132_dialog_content = "真理の主の啓示を聞き、\n私が目にした「結末」を回避するために。",
  ui_story_5084_50840700_133_dialog_content = "近ごろ家にこもっているようだな。\n太古の遺物への関心が薄れたのか？",
  ui_story_5084_50840700_134_dialog_content = "君の父親も私も、今の君くらいの年頃にはすでに血脈が覚醒し\n真理の道に大いなる興味を抱いていたものだが。",
  ui_story_5084_50840700_135_dialog_content = "それとも君は未だに無知で、\n「真理とはなにか」の答えを導き出せずにいるのか？",
  ui_story_5084_50840700_136_dialog_content = "…旅に出ることにしたの。真理の足跡を探すわ。",
  ui_story_5084_50840700_137_dialog_content = "ほお、好きにすればいい。",
  ui_story_5084_50840700_138_dialog_content = "こうして私は己の真理の啓示を追い求める旅に出た。",
  ui_story_5084_50840700_139_dialog_content = "家を出て、私は世界をより深く知ることができた。",
  ui_story_5084_50840700_140_dialog_content = "真理を悟るにつれて、血脈もようやく覚醒を始めた。\n…でも私はまだ真理結社には入るまいと自分に言い聞かせていた。",
  ui_story_5084_50840700_141_dialog_content = "けれど悟りを開き、答えを探し当てたと伝えた時には、\nあの人はもう私の答えに興味はなかった。",
  ui_story_5084_50840700_142_dialog_content = "戻ったのね…3か月も留守にするなんて、何かあったのかしら？",
  ui_story_5084_50840700_143_dialog_content = "…君には関わりのないことだ。",
  ui_story_5084_50840700_144_dialog_content = "その目つきは何なのかしら…恨みや得体の知れない感情が宿っている…",
  ui_story_5084_50840700_145_dialog_content = "ヴィルヘルム・ワラーキ、答えてちょうだい。\n何があったの？",
  ui_story_5084_50840700_146_dialog_content = "誰が部屋に入ってよいと言った？",
  ui_story_5084_50840700_147_dialog_content = "真理結社の指導者でありながら、務めを放り出して遊歴ばかり…\n家を空けている時間も増える一方だわ。",
  ui_story_5084_50840700_148_dialog_content = "何度も言っただろう。君には関係ない。今すぐ出て行け。",
  ui_story_5084_50840700_149_dialog_content = "いつもそうやって私との会話を拒むのね。でも今晩は聖鳴祭よ。\nその前に最後に話せると思ったのだけれど。",
  ui_story_5084_50840700_150_dialog_content = "真理について、私たちについて…",
  ui_story_5084_50840700_151_dialog_content = "出て行け！今すぐにだ！",
  ui_story_5084_50840700_152_dialog_content = "…",
  ui_story_5084_50840700_153_dialog_content = "結局、最後まで理解できないままだった。",
  ui_story_5084_50840700_154_dialog_content = "おそらく私も「最後」を逃した1人なのね。",
  ui_story_5084_50840700_155_dialog_content = "尊大で傲慢で忌々しいヴィルヘルム・ワラーキ。\n理解できないまま会えなくなった最後の家族――今、どこにいるのかしら？",
  ui_story_5084_50840700_156_dialog_content = "（ビクトリアは、ヴィルヘルムさんの仲をこんなふうに記憶してたんだ…）",
  ui_story_5084_50840700_157_dialog_content = "（でもヴィルヘルムさんは、ずっとビクトリアを守ろうとしてた…）",
  ui_story_5084_50840700_158_dialog_content = "（1人で錯乱に耐えて、他の当主たちみたいに信者の血を楽しむこともしなかった。\n最後まで他人のことを思って、ネイルスを救った…）",
  ui_story_5084_50840700_159_dialog_content = "（それなのにヴィルヘルムさんは、死ぬまでずっと…誤解され続けてきたんだ…）",
  ui_story_5084_50840700_160_dialog_content = "（ビクトリアにも…本当のヴィルヘルムさんが見えてるのかな…）",
  ui_story_5084_50840801_1_dialog_content = "あ、ロウソクの炎が揺れはじめた――\nまたどっかに飛ばされるの？",
  ui_story_5084_50840801_2_dialog_content = "ビクトリアだ…当主たちもいる…\nどうして集まってるんだろう？",
  ui_story_5084_50840801_3_dialog_content = "あれ？ビクトリア様の隣にいるのってファウストさん？\n今、こっちを見たような…",
  ui_story_5084_50840801_4_dialog_content = "まさか…",
  ui_story_5084_50840801_5_option_content = "感知",
  ui_story_5084_50840801_6_dialog_content = "ファウスト、聞こえる?",
  ui_story_5084_50840801_7_dialog_content = "もちろん。何を聞きたいのかも分かっているよ。",
  ui_story_5084_50840801_8_dialog_content = "今ここにいるビクトリア様は、僕たちのよく知るビクトリア様だ。",
  ui_story_5084_50840801_9_dialog_content = "だったら…そのビクトリアがどうしてあの人たちと…",
  ui_story_5084_50840801_10_dialog_content = "ヴィルヘルムが失踪してすでに3年。ワラーキ家の末裔は\n今やクラビスとヴィルヘルムの姪ビクトリアのみ…",
  ui_story_5084_50840801_11_dialog_content = "（3年か…ヴィルヘルムさんが殺害されたのは1915年だから、今は1918年？）",
  ui_story_5084_50840801_12_dialog_content = "だが、子息を真理結社に入れようとしないクラビス・アブラハムには、\n当然ながら結社に居場所はない。",
  ui_story_5084_50840801_13_dialog_content = "今指導者の座は空席のままだ。あの指輪も一向に見つからない。\nおそらくヴィルヘルムと共に消えたのだろう。",
  ui_story_5084_50840801_14_dialog_content = "つまりビクトリア、\n君が先祖の知恵を継承する機会は失われた…",
  ui_story_5084_50840801_15_dialog_content = "あら、わざわざそれを言うために、大勢の当主を集めたの？",
  ui_story_5084_50840801_16_dialog_content = "君は真理を探求する旅が好きだと聞いた。\nならば、旅に出るといい。",
  ui_story_5084_50840801_17_dialog_content = "ここを出て行くもよし、我がポルフィリオ家の一員になるもよし。\nいずれにせよ、君は指導者になる資格を失った。",
  ui_story_5084_50840801_18_dialog_content = "今日は聖鳴祭だ。真理結社の指導者の座は…",
  ui_story_5084_50840801_19_dialog_content = "ヴィルヘルムが消えて数年、\nこんな腐りきった会合をよく吐き気もせず、開いてこられたものね？",
  ui_story_5084_50840801_20_dialog_content = "飲むべきでない血を飲んでいるのなら、\nたとえ血の一族でも代償を支払うべきよ。",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>ビクトリアは手近なグラスを取ると、赤い美酒をテーブルにぶちまけた。\nするとグラスの底からヴィルヘルムが身につけていた指輪が現れた</color>",
  ui_story_5084_50840801_22_dialog_content = "…？",
  ui_story_5084_50840801_23_dialog_content = "…ヴィルヘルムの指輪だ。",
  ui_story_5084_50840801_24_dialog_content = "あの人は姿を消す前に、この指輪を私に託した。\n先祖の言葉なら、もう飽きるほど聞いたわ。",
  ui_story_5084_50840801_25_dialog_content = "さあ、これを見た後で、真理結社の指導者の座について、\n何か言いたいことはあるかしら？",
  ui_story_5084_50840801_26_dialog_content = "あり得ない！",
  ui_story_5084_50840801_27_dialog_content = "計画は変更だな…",
  ui_story_5084_50840801_28_dialog_content = "そう、計画――ここにいる皆さんは全員、ある計画に関わっている。",
  ui_story_5084_50840801_29_dialog_content = "それが3年前の聖鳴祭で、自らいけにえになることで得た啓示よ。",
  ui_story_5084_50840801_30_dialog_content = "3年前…いけにえ…",
  ui_story_5084_50840801_31_dialog_content = "いや、そんなはずはない！",
  ui_story_5084_50840801_32_dialog_content = "まだ他人を当てにしているのか？デービー、貴様の死は必然！\n他人に期待するだけ無駄だ！",
  ui_story_5084_50840801_33_dialog_content = "取り引きを忘れたか…",
  ui_story_5084_50840801_34_dialog_content = "…",
  ui_story_5084_50840801_35_dialog_content = "<size=45>ああ！！</size>",
  ui_story_5084_50840801_36_dialog_content = "おお、かわいそうなヴィルヘルム。\n誰にも認められず、故郷で犬死にするとはな。",
  ui_story_5084_50840801_37_dialog_content = "…",
  ui_story_5084_50840801_38_dialog_content = "跡継ぎがいなければ、\nワラーキの指輪を伝えることに意味はない。",
  ui_story_5084_50840801_39_dialog_content = "何をしているのだ？\n指輪を粉々にしてしまったら、この先…",
  ui_story_5084_50840801_40_dialog_content = "我々には無用の長物だ。\n粉々にしてヴィルヘルムの副葬品にしてやろうではないか。",
  ui_story_5084_50840801_41_dialog_content = "これでもう不安におびえることもない。",
  ui_story_5084_50840801_42_dialog_content = "当主の長としてのワラーキの束縛は、\nもはや過去のもの！",
  ui_story_5084_50840801_43_dialog_content = "指輪は…ヴィルヘルムと共に…",
  ui_story_5084_50840801_44_dialog_content = "すべて…知っているのか？",
  ui_story_5084_50840801_45_dialog_content = "あら？知らない方がよかったかしら？",
  ui_story_5084_50840801_46_dialog_content = "…指輪をはめただと？啓示を授かっただと？",
  ui_story_5084_50840801_47_dialog_content = "先祖の承認なくして、継承は成立しない！",
  ui_story_5084_50840801_48_dialog_content = "先祖から授かったワラーキの名と指輪が「舞い戻った」ことこそ承認の証よ。\nさあ、指輪をはめてみせましょうか。",
  ui_story_5084_50840801_49_dialog_content = "PlayerName！あの指輪、ビクトリア様を錯乱させたりしない！？",
  ui_story_5084_50840801_50_dialog_content = "メイ、今自分が何をすべきか分かった！\nどうしてここに来たのかも、だんだん分かってきた。",
  ui_story_5084_50840801_51_option_content = "精神感知――",
  ui_story_5084_50840801_52_dialog_content = "うっ…まただわ…",
  ui_story_5084_50840801_53_dialog_content = "あのささやき…昔日の啓示…",
  ui_story_5084_50840801_54_dialog_content = "安心して、ビクトリア。\n僕がちゃんと抑えててあげる！",
  ui_story_5084_50840801_55_dialog_content = "空の末裔！？なるほど、そういうことだったのね。\nこれが真理の主の思し召し…なら、頼んだわよ。",
  ui_story_5084_50840801_56_dialog_content = "指輪を…本当にはめたぞ…",
  ui_story_5084_50840801_57_dialog_content = "何をそんなに心配しているのかしら？\n真のワラーキに先祖の言葉を受け止められないはずがないでしょう？",
  ui_story_5084_50840801_58_dialog_content = "フフッ――ハハハハ――",
  ui_story_5084_50840801_59_dialog_content = "あの笑い方…",
  ui_story_5084_50840801_60_dialog_content = "見届けよ！\nこのヴィルヘルム・ワラーキが暗影で君たちを覆いつくしてやろう。",
  ui_story_5084_50840801_61_dialog_content = "私こそが先祖に認められしワラーキの新当主！",
  ui_story_5084_50840801_62_dialog_content = "ワラーキ…！",
  ui_story_5084_50840801_63_dialog_content = "見届けよ、ワラーキの後継者を！",
  ui_story_5084_50840802_1_dialog_content = "ならばこのまま浄化してやろう！",
  ui_story_5084_50840802_2_dialog_content = "どういうこと？この画面は…？",
  ui_story_5084_50840802_3_dialog_content = "指輪が伝えてきたんだよ。必死で止めようとしたんだけど…",
  ui_story_5084_50840802_4_dialog_content = "「他者」の意志とは関係ない、\nもっと高度な所からくる「雑音」みたいなんだ。",
  ui_story_5084_50840802_5_dialog_content = "悪意は感じないわ。\n続きを見せてちょうだい。",
  ui_story_5084_50840802_6_dialog_content = "<size=45>ああ！！</size>",
  ui_story_5084_50840802_7_dialog_content = "君の血をいただこう。私に「資格」を！",
  ui_story_5084_50840802_8_dialog_content = "ヴィルヘルム・ワラーキ、\n君こそが先祖の啓示を得る<color=#FFB400>鍵</color>なのだ！ウハハハハッ！",
  ui_story_5084_50840802_9_dialog_content = "ヴィルヘルム…！",
  ui_story_5084_50840802_10_dialog_content = "ヴィルヘルム、君から出立を告げる手紙を受け取った時、\nてっきりビクトリアとの安住の地を見つけたのだと思っていたのに…",
  ui_story_5084_50840802_11_dialog_content = "なぜ戻ってきたのだ？愚かなことを…\nいや…フッ…ハハハ…",
  ui_story_5084_50840802_12_dialog_content = "ハハハッ…愚かなのは私も同じだな。\n<color=#FFB400>こんな輩</color>を安易に信じてしまったのだから。",
  ui_story_5084_50840802_13_dialog_content = "我らが先祖よ、ヴィルヘルム・ワラーキを受け入れたまえ。\n彼はワラーキの名誉に恥じぬ男。野心はその血の中で燃える唯一の不純物。",
  ui_story_5084_50840802_14_dialog_content = "我ら罪人の裏切りに遭いし彼の罪を洗い流し、\nそのすべてを私に担わせたまえ。",
  ui_story_5084_50840802_15_dialog_content = "私の唯一の願いは、この魂が呪いを存分に受けし後、\nカロンと妻が無事にこの地を離れること…",
  ui_story_5084_50840802_16_dialog_content = "ヴィルヘルム、かつての心腹の友よ。\n棺の中で安らかに眠れ。",
  ui_story_5084_50840802_17_dialog_content = "本当なの？ヴィルヘルムが…死んでいたなんて…",
  ui_story_5084_50840802_18_dialog_content = "これが…指輪の伝えたかった真実だというの？",
  ui_story_5084_50840802_19_dialog_content = "3年前指輪を無理やり握らせた人が、もうこの世にいない…？",
  ui_story_5084_50840802_20_dialog_content = "…これからどうするの？",
  ui_story_5084_50840802_21_dialog_content = "私にはわかるわ。私たちは今、確実に真相に迫っている。",
  ui_story_5084_50840802_22_dialog_content = "最初は、主が私をここへお導きになったのは、\n真理結社の指導者となった私に何かを見せ、立ち会わせるためだと思っていた。",
  ui_story_5084_50840802_23_dialog_content = "でも、いけにえとなり、あなたがやって来たことで気づいた。\n私も当事者として介入すべきだと。主の恩恵と拭い去れぬ憎しみを胸にね。",
  ui_story_5084_50840802_24_dialog_content = "それは力を操る能力と理性を持った私にしかできないこと――",
  ui_story_5084_50840802_25_dialog_content = "真理の主よ、私の疑問に答え、\n復讐の機会をお与えくださったことに感謝いたします。",
  ui_story_5084_50840802_26_dialog_content = "今夜は聖鳴祭よ。この争いは先祖の啓示を巡って起きたもの。\nなら、先祖の立ち会いの下で決着をつけましょう。",
  ui_story_5084_50840802_27_dialog_content = "皆さん、長らくお待たせしてしまったようね。",
  ui_story_5084_50840802_28_dialog_content = "私は真理の主の啓示を受け、自身の使命を理解したわ。",
  ui_story_5084_50840802_29_dialog_content = "その指輪…痛みを感じないの？",
  ui_story_5084_50840802_30_dialog_content = "ヴィルヘルムがはめた時は、そんなに楽そうではなかったわ。",
  ui_story_5084_50840802_31_dialog_content = "どんな啓示を受けたというのだ？",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>ビクトリアは立ち上がり、長机の上座へと向かった</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>門派を粛清せよ。</color>",
  ui_story_5084_50840802_34_dialog_content = "なに！？",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>黒風が吹きこみ、窓がガタガタ揺れた。太古の力を操る継承者が当主たちに最後通牒を突きつけるかのように</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>ガシャン――</color>",
  ui_story_5084_50840802_37_dialog_content = "クサリヘビさん、動揺してグラスを落とすのは\nとても優雅とはいえないな。",
  ui_story_5084_50840802_38_dialog_content = "…",
  ui_story_5084_50840802_39_dialog_content = "指輪は…何を告げたのだ！",
  ui_story_5084_50840802_40_dialog_content = "デービー！ここは真理の殿堂よ。",
  ui_story_5084_50840802_41_dialog_content = "…！",
  ui_story_5084_50840802_42_dialog_content = "すべては先祖の祝典に端を発している。\nならば今夜の祝典で何もかもお終いにしましょう。",
  ui_story_5084_50840802_43_dialog_content = "ワラーキの新当主として、\n今夜の聖鳴祭の準備をしなければ。",
  ui_story_5084_50840802_44_dialog_content = "皆さん――赤い月が空にかかり、鐘の音が教会中に鳴り響く時、\n再び一堂にに会し、長い夜を終わらせましょう。",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>薄暗い常夜灯の下で、デービーは血の海に浸っていた。\n同じ部屋には彼の狂信者の他に、目も当てられぬほど痛めつけられたクラビスがいた</color>",
  ui_story_5084_50840900_2_dialog_content = "…ヴィルヘルムは死んだのか、死んでいないのか！？",
  ui_story_5084_50840900_3_dialog_content = "さっさと…吐け…！",
  ui_story_5084_50840900_4_dialog_content = "これ以上…痛めつけても無駄だ。\n知っていることはすべて話した…",
  ui_story_5084_50840900_5_dialog_content = "私はこの手でヴィルヘルムを棺に寝かせ、\nその死を見届けた…",
  ui_story_5084_50840900_6_dialog_content = "3年前の聖鳴祭の儀式で、\nヴィルヘルムはビクトリアを棺から逃がした。",
  ui_story_5084_50840900_7_dialog_content = "我慢の限界に達した我々は、やつを始末することにした。\n我々を縛りつけるあの指輪と共に。",
  ui_story_5084_50840900_8_dialog_content = "それがなぜ3年後の今日、\nビクトリアが指輪をつけて現れたのだ？",
  ui_story_5084_50840900_9_dialog_content = "あの2人はいったい何を企んでいるのだ？",
  ui_story_5084_50840900_10_dialog_content = "この教典には一切文字が書かれていない。\nここにはあなたの望む「聖言」など存在しないわ。",
  ui_story_5084_50840900_11_dialog_content = "それにしてもあのワラーキ家のお嬢ちゃん、\n父親にそっくりね。",
  ui_story_5084_50840900_12_dialog_content = "クッ、ククク…ウハハハッ――",
  ui_story_5084_50840900_13_dialog_content = "なに、どうしたのよ？",
  ui_story_5084_50840900_14_dialog_content = "我々のなんと滑稽なことよ。ヴィルヘルムの虚勢にだまされ、\nためらっているうちに選択の余地さえ失ってしまうとは。",
  ui_story_5084_50840900_15_dialog_content = "あの老いぼれ夫婦が死んだ時、\nビクトリアとヴィルヘルムも始末しておくべきだったのだ。",
  ui_story_5084_50840900_16_dialog_content = "あの時のビクトリアは覚醒前で、\n今ほど手ごわくはなかったというのに。",
  ui_story_5084_50840900_17_dialog_content = "デービー、俺たちはワラーキ家に長いこと服従しすぎて、忘れてしまったのかもな…\n「真理」なんて外から持ち込まれたゴミみたいなもんだってことをさ。",
  ui_story_5084_50840900_18_dialog_content = "もっともだ。血に親しみ、血から力を吸い取ることこそ、\n我々血の一族の生き方だ！",
  ui_story_5084_50840900_19_dialog_content = "力もないのに、「断言」、「重複」、「封鎖」、「欲望」のみを多用し、\n<color=#FFB400>真理の主</color>への信仰を広めるのは外道でしかない！",
  ui_story_5084_50840900_20_dialog_content = "もう手遅れだ…\nあの娘はすでに指輪の力を手に入れ、我々を滅ぼそうとしている。",
  ui_story_5084_50840900_21_dialog_content = "時間は半日も残されていない。何をしようと、我々はもう…",
  ui_story_5084_50840900_22_dialog_content = "黙れ！ヴィルヘルムとて、あのふざけた指輪をつけていたにも関わらず、\n結局は私に血を吸いつくされたではないか！",
  ui_story_5084_50840900_23_dialog_content = "フン、だが忌々しいことに、やつは先祖の承認を得た者ではなかった。\nそのせいで血をすすっても結局教典との契約は果たせなかった。",
  ui_story_5084_50840900_24_dialog_content = "それでも増え続ける信者のお陰で、私は力を蓄え…\n今や教典の呼びかけをかすかに聞けるまでになった！",
  ui_story_5084_50840900_25_dialog_content = "あと一歩…あと一歩なのだ。\n私も教典に啓示を浮かび上がらせることができる！",
  ui_story_5084_50840900_26_dialog_content = "我々の血脈はワラーキ家に迫害され、\nひたすら利益を奪われ続けた。",
  ui_story_5084_50840900_27_dialog_content = "血をすするという性にさえ、やつらは制限を加えた…\n今思えば、ワラーキはただ我々の力を恐れていただけなのかもしれない。",
  ui_story_5084_50840900_28_dialog_content = "何をする気だ…",
  ui_story_5084_50840900_29_dialog_content = "計画通り…今夜は何があろうと儀式に出る。\nその場を取り仕切り、教典が私を認めたと信者たちに知らしめるのだ。",
  ui_story_5084_50840900_30_dialog_content = "ビクトリアに協力する者が現れない限り、\nすべてうまくいくはずだ。",
  ui_story_5084_50840900_31_dialog_content = "あの叔父と姪の2人が頼れるのは今や墓所のみ。藤蔓人は根っからの臆病者だ。\nパンニング、クサリヘビ、ケルピー、任せたぞ。",
  ui_story_5084_50840900_32_dialog_content = "ああ。",
  ui_story_5084_50840900_33_dialog_content = "私はヴィルヘルムを倒した。\nビクトリアとて仕留められるはずだ。",
  ui_story_5084_50840900_34_dialog_content = "今はただ力の補充に努めるのみ。\nあの娘が今夜どんな小細工を仕掛けてくるか楽しみだ。",
  ui_story_5084_50840900_35_dialog_content = "うっ…デービー…",
  ui_story_5084_50840900_36_dialog_content = "…というわけなんだ。何度も時空を越えたから、\n毎回そこがいつのどこなのか、すぐには分からなかったんだけど。",
  ui_story_5084_50840900_37_dialog_content = "啓示は難解なものだけど、\nその思し召しには必ず理由がある。",
  ui_story_5084_50840900_38_dialog_content = "私たちのいる「今」の3年前――1915年\n私は聖鳴祭でヴィルヘルムに遭遇し、その指示で棺に入った。",
  ui_story_5084_50840900_39_dialog_content = "あの時、ヴィルヘルムは指輪を動かしていたの。\nその見慣れない動作ですぐにわかった…",
  ui_story_5084_50840900_40_dialog_content = "あの人は何かを伝えようとしている――\nだから儀式に参加することにしたのよ。",
  ui_story_5084_50840900_41_dialog_content = "だた、目が覚めた時にはもう「今」だった。",
  ui_story_5084_50840900_42_dialog_content = "私は3年の時を越えて、家のベッドで目覚めたわ。\nその時手にしていたのは一族に代々伝わる指輪だけだった。",
  ui_story_5084_50840900_43_dialog_content = "それはヴィルヘルムが儀式の最後に私に託したもの。",
  ui_story_5084_50840900_44_dialog_content = "僕もあの屋敷で目が覚めたんだよ。\nちょうど誰かがビクトリア様宛の手紙を届に来てね。",
  ui_story_5084_50840900_45_dialog_content = "届け人が去った後、ここはどこだろうと考えていたら、\nビクトリア様がドアを開けて部屋に入ってきたのさ。",
  ui_story_5084_50840900_46_dialog_content = "手紙には聖鳴祭の前に開かれる当主会談に参加しろとだけ書いてあった。\n当主たちは明らかに私の登場に戸惑っていたわね。",
  ui_story_5084_50840900_47_dialog_content = "ということは、私の存在を知っていたのは手紙の差出人だけってことになるわ。\nしかもその「私」がこの時代にいるはずのない「ビクトリア」だってことも知っていた。",
  ui_story_5084_50840900_48_dialog_content = "そうだ、ビクトリア様…あたしたちネイルスさんにも会いました。\nでも、様子がちょっとヘンで…",
  ui_story_5084_50840900_49_dialog_content = "ネイルスさんのことを知らないヴィルヘルム様に、\n「呼んでくれて感謝します」とか言ってたんです…",
  ui_story_5084_50840900_50_dialog_content = "3年前聖鳴祭にいたヴィルヘルムさんが\nそうさせたってことなのかな？",
  ui_story_5084_50840900_51_dialog_content = "あの人は私たちの見た光景の中では死んでいたけれど、\n過去ではまだ生きているわ。",
  ui_story_5084_50840900_52_dialog_content = "3年前の聖鳴祭で、あの人はきっと何かしたのよ。\nただ、その只中にいた私たちには知る由もなかった。",
  ui_story_5084_50840900_53_dialog_content = "でも、私には分かるわ。確実に真相に迫ってきている。",
  ui_story_5084_50840900_54_dialog_content = "ずっとお聞きしたかったのですが、1918年の聖鳴祭の折、「今」のビクトリア様はどこで何をなさっていたのですか？",
  ui_story_5084_50840900_55_dialog_content = "1918年は確か…私はまだ外遊中で、会議には参加しなかったはず。",
  ui_story_5084_50840900_56_dialog_content = "あの年の聖鳴祭当日、私はワールプール町に泊まっていた。\nそれが夜になって突然、戻って教典を入手せよとの天啓を聞いたの。",
  ui_story_5084_50840900_57_dialog_content = "気づいた時にはもう、私はワラーキの墓所の<color=#FFB400>棺</color>の中にいて、教典を握っていた。",
  ui_story_5084_50840900_58_dialog_content = "そして教典に突如として、ワールプール町を認め、\n私を真理結社の指導者に指名するとの啓示が現れたのよ。",
  ui_story_5084_50840900_59_dialog_content = "それが過去に来る前、指輪に触れた時に目にした記憶よ。",
  ui_story_5084_50840900_60_dialog_content = "今…ワラーキの墓所の<color=#FFB400>棺</color>とおっしゃいましたか？\nなぜ…<color=#FFB400>棺</color>だったのでしょう？",
  ui_story_5084_50840900_61_dialog_content = "おそらく…私にも棺で眠る習慣があったからでしょう。",
  ui_story_5084_50840900_62_dialog_content = "（うーん…棺か…ご両親の棺…ヴィルヘルムさんの棺…）",
  ui_story_5084_50840900_63_dialog_content = "つまり、ワラーキ家の棺には私たちには知りえない力があるということでしょうか？",
  ui_story_5084_50840900_64_dialog_content = "時空を超える力とか？",
  ui_story_5084_50840900_65_dialog_content = "PlayerNameが持っている燭台もそうよ。\n火が点っている間は様々な場所を行き来できるの。",
  ui_story_5084_50840900_66_dialog_content = "3年前の聖鳴祭では、\nヴィルヘルムさんが墓所の扉を開けるのにも役立った…",
  ui_story_5084_50840900_67_dialog_content = "スカーレイさん…\nいったいどんだけお宝を持ってるの！？",
  ui_story_5084_50840900_68_dialog_content = "スカーレイの一族は墓守として、\nビクトリア様を墓には入れないようにしてきました。",
  ui_story_5084_50840900_69_dialog_content = "「時が満ちていない」というのが理由でしたが…\nその「時」がなぜ今なのでしょう？",
  ui_story_5084_50840900_70_dialog_content = "ヴィルヘルムの失踪、ひいてはその死の裏には、\n何か別の深い意味があるのかもしれないわ。",
  ui_story_5084_50840900_71_dialog_content = "あの人は今日の「危機」を前々から予見していたようね。\nまるで私たちが「その渦中に入る」のを待っていたかのようだわ。",
  ui_story_5084_50840900_72_dialog_content = "あの人は以前、私に真理とは何かと尋ね、それを懸命に追い求めよと言った。\nでも今思えば、あの人が待っていたのは、私が「正しい答え」を出すことではなかったのね。",
  ui_story_5084_50840900_73_dialog_content = "真理に答えなどないもの。",
  ui_story_5084_50840900_74_dialog_content = "あるのは、答えを探し続ける強い信念だけ。",
  ui_story_5084_50840900_75_dialog_content = "私はもうその答えの力を知っている。\nだから恐れることなく「当主」たちの排除を決意したの。",
  ui_story_5084_50840900_76_dialog_content = "それでも、私は3年前、あの人と話して、\n自分の探究がどんなものか、わかってもらいたかったわ…",
  ui_story_5084_50840900_77_dialog_content = "（…2人ともただ意地を張ってるだけなのに、\nこれだけ時間が経っても、まだ分かり合えないのかな…？）",
  ui_story_5084_50840900_78_dialog_content = "とにかく、何としても確めるわ…\nこの指輪が私の元に舞い戻った意味を…",
  ui_story_5084_50840900_79_dialog_content = "（ここまで来たら、僕もちゃんと答えが知りたい…）",
  ui_story_5084_50840900_80_dialog_content = "（僕の見てきたヴィルヘルムさんがどうしてビクトリアの記憶の中の姿と違うのか…\n僕の見てきたヴィルヘルムさんは、ビクトリアを守ろうと必死だった…）",
  ui_story_5084_50840900_81_dialog_content = "（あともう少し…今はまだ霧に包まれてる鍵さえ見つけられれば、\nビクトリアにもまだ答えを伝えるチャンスがある気がする…）",
  ui_story_5084_50840900_82_dialog_content = "（そうだ、燭台…いつも僕が知りたいって思うと、その場所へ連れて行ってくれてたのに、\nどうして今は動かないんだろう？）",
  ui_story_5084_50840900_83_dialog_content = "（はぁ…真理結社の人たちの執念って、こうやって鍛えられてきたのかな…）",
  ui_story_5084_50840900_84_dialog_content = "日が暮れたわ。聖鳴祭の儀式が間もなく始まるわね。\n残された時間もあとわずかよ。",
  ui_story_5084_50840900_85_dialog_content = "時間…？あ、本当だ。ロウソクが残り少なくなってる…",
  ui_story_5084_50840900_86_dialog_content = "心配はいらないわ。何をすべきかはわかっているもの。",
  ui_story_5084_50840900_87_dialog_content = "当主会談での脅しは、彼らの力への渇望を掻き立てただけでしょうね。\nおそらく捨て身で対抗してくるわ。",
  ui_story_5084_50840900_88_dialog_content = "でも万が一、あの人たちが逃げてたらどうするの？\nすごい威圧感だったし…",
  ui_story_5084_50840900_89_dialog_content = "デービーは逃げないわ。\n彼は野心家だもの。目的を達するまで決して満足しない。",
  ui_story_5084_50840900_90_dialog_content = "それにデービーはおそらく、\nすでに「今」の紅血の教典を手に入れている。",
  ui_story_5084_50840900_91_dialog_content = "当主の長に登り詰め、真理結社を奪い取るため、\n残って今夜の儀式を取り仕切ろうと躍起になっているはずよ。",
  ui_story_5084_50840900_92_dialog_content = "野心とは恐ろしいものよ。\nだからこそ、ヴィルヘルムもデービーも憑りつかれたの。",
  ui_story_5084_50840900_93_dialog_content = "じゃあ僕たちはどこへ行けばいいの？",
  ui_story_5084_50840900_94_dialog_content = "先祖代々の墓地で――確かめたいものがあるの。\n予想通りだとすれば、デービーも手下を向かわせたはずよ。",
  ui_story_5084_50840900_95_dialog_content = "ビクトリア様、待ってください…\nネイルスさんはどうすれば？",
  ui_story_5084_50840900_96_dialog_content = "まだ村にいるんです。",
  ui_story_5084_50840900_97_dialog_content = "大丈夫よ。ネイルスはすでに主の加護を受けている。\n真理が正しい場所に導いてくれるわ。",
  ui_story_5084_50840900_98_dialog_content = "でもビクトリア様…\nあたし、ネイルスさんが当主たちに痛めつけられてるのを見たんです…",
  ui_story_5084_50840900_99_dialog_content = "だから、心配で…ずっと探しに行きたいと思ってたんですけど、\nそうしたら、みんなも危険なんじゃないかと思って…",
  ui_story_5084_50840900_100_dialog_content = "迷ってもいいのよ。思いやりは美徳だもの。\nメイ、自分の思うようにやってみなさい。",
  ui_story_5084_50840900_101_dialog_content = "ファウスト、メイとここに残って。ネイルスをお願いね。",
  ui_story_5084_50840900_102_dialog_content = "私は空の末裔と一緒に行くわ。\n今晩教会で落ち合いましょう。",
  ui_story_5084_50841001_1_dialog_content = "入口の藤蔓から血が流れてる…\n棺もこじ開けられてるし…先を越されちゃったの？",
  ui_story_5084_50841001_2_dialog_content = "血の一族の戒律を無視して…\n先人たちの骸まで荒らすとは。",
  ui_story_5084_50841001_3_dialog_content = "ここだよ、僕たちが前に見た場所だ！",
  ui_story_5084_50841001_4_dialog_content = "クラビスさんがヴィルヘルムさんを棺に入れてた…",
  ui_story_5084_50841001_5_dialog_content = "でも、ここにその棺はないようね。",
  ui_story_5084_50841001_6_dialog_content = "お…お嬢様？ビクトリアお嬢様ですか…？",
  ui_story_5084_50841001_7_dialog_content = "グレイブ？無事だったのね。\n血を流す藤蔓を見て、てっきりあなたも…",
  ui_story_5084_50841001_8_dialog_content = "3年です…この3年間、ワラーキ家がこの地を放っておかれたせいで、\nすべてが滅茶苦茶になってしまいました。",
  ui_story_5084_50841001_9_dialog_content = "ヴィルヘルム様が亡くなり、お嬢様も行方知れずとなり…\nあの者たちはどんな犠牲も厭わず先祖の遺物を手に入れようとしました。",
  ui_story_5084_50841001_10_dialog_content = "私の家族を捕らえ、痛めつけ、私をさいなみ続けました…",
  ui_story_5084_50841001_11_dialog_content = "デービーです！デービーは全てを奪うつもりです。\nワラーキ家の従僕である私の力も奪おうとしているのです…",
  ui_story_5084_50841001_12_dialog_content = "…ごめんなさい。何年も留守にしている間に、\nあなたやご家族を辛い目に遭わせてしまったわ。",
  ui_story_5084_50841001_13_dialog_content = "グレイブ、ヴィルヘルムは…本当に死んだの？",
  ui_story_5084_50841001_14_dialog_content = "クラビス様、いったい…何を…？",
  ui_story_5084_50841001_15_dialog_content = "…遺体を1つ安置したまでだ。",
  ui_story_5084_50841001_16_dialog_content = "私の愚かな友をよろしく頼む。",
  ui_story_5084_50841001_17_dialog_content = "クラビス様…クラビス様…",
  ui_story_5084_50841001_18_dialog_content = "ヴィルヘルム様の死は確かです…\nクラビス様が勝手にあの鍵を使って墓所に入り、埋葬したのです。",
  ui_story_5084_50841001_19_dialog_content = "…空の末裔、中に入ってみましょう。",
  ui_story_5084_50841001_20_dialog_content = "グレイブ、安心して。\n今夜、主の立ち会いの下、すべてが終わるわ。",
  ui_story_5084_50841001_21_dialog_content = "お嬢様…どうかお気をつけて…",
  ui_story_5084_50841001_22_dialog_content = "墓所の奥で…やつらがあちこち壊しながら…\n何かを捜しています…",
  ui_story_5084_50841001_23_dialog_content = "おやおや、誰かと思いきや。",
  ui_story_5084_50841001_24_dialog_content = "我らがワラーキ家のお嬢ちゃまか。",
  ui_story_5084_50841001_25_dialog_content = "…お嬢様！",
  ui_story_5084_50841001_26_dialog_content = "藤蔓人、まだくたばっていなかったのか…",
  ui_story_5084_50841001_27_dialog_content = "デービーが、\nワラーキ家の小娘を始末しろと言っていたな？",
  ui_story_5084_50841001_28_dialog_content = "先手必勝だ。",
  ui_story_5084_50841001_29_dialog_content = "愚かね…",
  ui_story_5084_50841001_30_dialog_content = "ワラーキ家の墓所を土足で荒らして、\n先祖の眠りを邪魔するとはなんたる狼藉。",
  ui_story_5084_50841001_31_dialog_content = "今夜の儀式であなたたち全員を罰するつもりだったけど、\n先に手を出されるとは思ってもいなかったわ。",
  ui_story_5084_50841002_1_dialog_content = "ビクトリア…「ケルピー」っていう当主が、\n地下に潜り込んで逃げた…",
  ui_story_5084_50841002_2_dialog_content = "フフ、これで残るは2人だけ。\n終わりを受け入れる準備はできているかしら？",
  ui_story_5084_50841002_3_dialog_content = "待て…ワラーキ家のお嬢様も、もういい大人だ。\nデービーとよく話し合ってみたらどうだ？",
  ui_story_5084_50841002_4_dialog_content = "ありえない！外の世界を3年見てきただけで、\nいったいどこからそんな力が…",
  ui_story_5084_50841002_5_dialog_content = "3年？狭い世界に閉じこもっていたあなたたちには、\n到底理解できないでしょうね。",
  ui_story_5084_50841002_6_dialog_content = "この力はたった3年の蓄積で成ったものではない…\nでも、その秘密をあなたたちに教える気はないわ。",
  ui_story_5084_50841002_7_dialog_content = "欲望に支配され真理の道を破壊した狂徒よ、\n死して聖鳴祭のプレリュードを奏でなさい！",
  ui_story_5084_50841002_8_dialog_content = "（…スカーレイは歴史を変えちゃいけないって言ってた…\nビクトリアがこの人たちを殺したら…過去が変わっちゃうんじゃ…）",
  ui_story_5084_50841002_9_dialog_content = "（それとも…ビクトリアの今の無意識の行動も、実はもう歴史の一部なのかな？）",
  ui_story_5084_50841002_10_dialog_content = "あら？",
  ui_story_5084_50841002_11_dialog_content = "「蛇の秘法」だよ…お嬢ちゃんには理解できまい？",
  ui_story_5084_50841002_12_dialog_content = "首をはねられても、蛇は脱皮して再生するのさ…",
  ui_story_5084_50841002_13_dialog_content = "それなら、何度でもはねてやるわ！",
  ui_story_5084_50841002_14_dialog_content = "ま、待て！お前に俺は殺せない！",
  ui_story_5084_50841002_15_dialog_content = "誰も殺すなんて言ってないでしょう？\nただ…首をはねられる痛みに、あなたは耐えられるかしら？",
  ui_story_5084_50841002_16_dialog_content = "許しを乞い、泣き叫び…\n<size=45>もがき苦しむがいいわ！</size>",
  ui_story_5084_50841002_17_dialog_content = "（ビクトリアには…こんなに残酷な一面もあったんだね…）",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>ひっそりした墓所の中、壁際の棺が突然開き、中から人が現れた――</color>",
  ui_story_5084_50841002_19_dialog_content = "そいつを痛めつけたところで意味はない。",
  ui_story_5084_50841002_20_dialog_content = "！？",
  ui_story_5084_50841002_21_dialog_content = "…ヴィ、ヴィルヘルム？？？",
  ui_story_5084_50841002_22_dialog_content = "まさか！\nとっくに死んだはずだろう！",
  ui_story_5084_50841002_23_dialog_content = "…やはり生きていたのね。",
  ui_story_5084_50841002_24_dialog_content = "いや、私は確かに死んだ。長い間時の河を漂っていたが、\n今ようやく主の思し召しを悟った。",
  ui_story_5084_50841002_25_dialog_content = "3年前の聖鳴祭は…あなただったのね。",
  ui_story_5084_50841002_26_dialog_content = "運命が私をここへ導いたのだ。3年などほんの一瞬にすぎない。\nだが…おそらくここが最後の停泊地となるだろう。",
  ui_story_5084_50841002_27_dialog_content = "…！？",
  ui_story_5084_50841002_28_dialog_content = "（分かった！僕が見ていたのは、やっぱり2人のヴィルヘルムさんだったんだ）",
  ui_story_5084_50841002_29_dialog_content = "（ビクトリアをいけにえにしたのも、今まで起こったことのすべてを動かしてたのも…\n一度は死んだヴィルヘルムさんだったんだ）",
  ui_story_5084_50841002_30_dialog_content = "持って行け。運命が君と共にあることを望んでいる。",
  ui_story_5084_50841002_31_dialog_content = "これは…紅血の教典？",
  ui_story_5084_50841002_32_dialog_content = "いいえ…これは私の知っているものではないわ。",
  ui_story_5084_50841002_33_dialog_content = "「新たな教典」だ。\nその持ち主には未来を導く者こそふさわしい。",
  ui_story_5084_50841002_34_dialog_content = "さあ、持て。これは君にしか操れない力だ。",
  ui_story_5084_50841002_35_dialog_content = "これで、そこにいるクズどもを始末すればいい。",
  ui_story_5084_50841002_36_dialog_content = "…嫌よ。",
  ui_story_5084_50841002_37_dialog_content = "…！？",
  ui_story_5084_50841002_38_dialog_content = "「あなた」からもらった力なんて必要ないわ――\n奴らに殺されたのはあなたでしょ。自分の仇は自分で討って。",
  ui_story_5084_50841002_39_dialog_content = "いったいどういうことだ？\nこのオレたちがまったく歯が立たないだと？",
  ui_story_5084_50841002_40_dialog_content = "このヴィルヘルムは俺たちが殺したヴィルヘルムじゃない。",
  ui_story_5084_50841002_41_dialog_content = "ヴィルヘルム、あの世でなにがあった！？\nそれだけでも教えてくれ。お前はどんな「真理」を見たんだ？",
  ui_story_5084_50841002_42_dialog_content = "…黙れ！",
  ui_story_5084_50841002_43_dialog_content = "真理は貴様の理解など求めてはいない。",
  ui_story_5084_50841002_44_dialog_content = "貴様らはただその血でもって、ワラーキ家の先祖を貶めた罪を償え！",
  ui_story_5084_50841002_45_dialog_content = "ワ…ラーキ…",
  ui_story_5084_50841002_46_dialog_content = "（一太刀で2人を倒しちゃった…ヴィルヘルムさん、強い…！）",
  ui_story_5084_50841002_47_dialog_content = "ヴィルヘルム、これは先祖の眠る棺でしょう…？\nいったい何があったの？",
  ui_story_5084_50841002_48_dialog_content = "なぜ消えたの？なぜ…今になってまた現れたの？",
  ui_story_5084_50841002_49_dialog_content = "復活したということ？それともただの幻影なのかしら？",
  ui_story_5084_50841002_50_dialog_content = "君は少しも変わっていないな。\n口を開けば質問ばかりだ。",
  ui_story_5084_50841002_51_dialog_content = "だが残念ながら時は流れ、私はすでこの世の者ではない。\n今それを議論したところで無意味だ。",
  ui_story_5084_50841002_52_dialog_content = "これで本当にお別れだ、ビクトリア。",
  ui_story_5084_50841002_53_dialog_content = "（もう行っちゃうの…？やっと再会できたのに…ずっと相手のことを思ってきたのに…\nこんな形で終わっちゃうなんて…）",
  ui_story_5084_50841002_54_dialog_content = "ヴィルヘルムさん、待ってください！",
  ui_story_5084_50841002_55_dialog_content = "PlayerName…",
  ui_story_5084_50841002_56_dialog_content = "君は…",
  ui_story_5084_50841002_57_dialog_content = "その声は…",
  ui_story_5084_50841002_58_dialog_content = "ああ…そうか…",
  ui_story_5084_50841002_59_dialog_content = "これが、運命というものか…",
  ui_story_5084_50841002_60_dialog_content = "ふっ…運命か…",
  ui_story_5084_50841002_61_dialog_content = "「運命」と呼ぼうが、何と呼ぼうが、構いません。",
  ui_story_5084_50841002_62_dialog_content = "でも、あの時あなたはその「運命」の導きに耳を傾け、自分の信じる真理を追い求め、\nビクトリアの将来を心配して墓所に向かいました。",
  ui_story_5084_50841002_63_dialog_content = "ビクトリアもその用意された「運命」の中で、ささやきを聞く苦しみや危険を冒してでも、\n指輪をはめて、あなたの行方を捜そうとしました…",
  ui_story_5084_50841002_64_dialog_content = "時空すら超えてきたのに、わだかまりを捨てて話をすることが、\nそんなに難しいんですか？",
  ui_story_5084_50841002_65_dialog_content = "2人が当主たちに立ち向って、剣を振るって戦ってた時…\n僕には2人を突き動かしてる感情が確かに「見え」たんです。",
  ui_story_5084_50841002_66_dialog_content = "ごめんなさい…また僕が余計なことを言って、\n何かを変えてしまったかもしれません…",
  ui_story_5084_50841002_67_dialog_content = "でも、これだけは自信をもって言えます――",
  ui_story_5084_50841002_68_dialog_content = "言葉こそ何かを変える最良の方法なんです…\n何も言わなかったら、相手を理解するチャンスなんて永遠に訪れません。",
  ui_story_5084_50841002_69_dialog_content = "…",
  ui_story_5084_50841002_70_dialog_content = "…",
  ui_story_5084_50841002_71_dialog_content = "問いや答えなんて、実はそんなに重要じゃないんです…\n重要なのは、今2人がここにいるってことだと思います。",
  ui_story_5084_50841002_72_dialog_content = "「運命」かどうかなんてことも関係ないんです。\n2人はいつだって自分の心に従って選択してきたでしょう？",
  ui_story_5084_50841002_73_dialog_content = "PlayerName…",
  ui_story_5084_50841002_74_dialog_content = "フフ、世の中の人が全員、あなたのようにまっすぐだったら、\n道を誤る人も少なくなるでしょうね。",
  ui_story_5084_50841002_75_dialog_content = "そのまっすぐな心は、君のような者だけが持つ宝だ。",
  ui_story_5084_50841002_76_dialog_content = "…どこから話すべきだろうか？",
  ui_story_5084_50841002_77_dialog_content = "時間の外を延々と漂ううちに…\n初めて安らかな眠りを求めている自分に気づいた。",
  ui_story_5084_50841002_78_dialog_content = "ビクトリア…私はようやく理解できた。兄は永遠の眠りを求めていたのだ。\nおそらく今の君になら分かるはずだ。",
  ui_story_5084_50841002_79_dialog_content = "心の命じるままに選択する。\n今までもそうやって数え切れぬほど選択を重ねてきた。",
  ui_story_5084_50841002_80_dialog_content = "礼を言わせてくれ…君がワラーキ家を血脈の呪いから解き放ってくれたお陰で、\n私は未来で滞りなく死を迎えることができる。",
  ui_story_5084_50841002_81_dialog_content = "あなたからお礼を言われるとは思わなかったわ…\nただ、ワラーキ家の血脈の呪いを解いたのが私だというのは…？",
  ui_story_5084_50841002_82_dialog_content = "空の末裔の言う通りだ。\nここまで見届けたら、問いや答えなどもう――",
  ui_story_5084_50841002_83_dialog_content = "重要よ！",
  ui_story_5084_50841002_84_dialog_content = "真理は人によって異なるもの。絶対的な答えはない。\nどこまでも探究し続ける信念こそが真実なのよ。",
  ui_story_5084_50841002_85_dialog_content = "…ならば、続きを聞かせてくれ。",
  ui_story_5084_50841002_86_dialog_content = "この世には「対立」や「苦難」が存在する。\n長命の種族は死に対する渇望ゆえに刹那の生を求め、同時により多くの未来を求める。",
  ui_story_5084_50841002_87_dialog_content = "このアイオリアに<color=#FFB400>救世主</color>は存在するのかしら？",
  ui_story_5084_50841002_88_dialog_content = "私は予言された大難が現実に起きるのをこの目で見た。\nでもだからこそ<color=#FFB400>救済</color>の存在を確信したの。",
  ui_story_5084_50841002_89_dialog_content = "つまり私の追い求める真理は<color=#FFB400>救済</color>――\nこの世からあらゆる堕落の種を消し去ることなの。",
  ui_story_5084_50841002_90_dialog_content = "物理的な制限や意識の束縛を越えて、至高の進化を遂げ、光霊は星々を目指す――\nそこにたどり着けるのは無上の真理だけよ。",
  ui_story_5084_50841002_91_dialog_content = "…啓示の告げた通り、君は成長し、十分に力をつけた。",
  ui_story_5084_50841002_92_dialog_content = "「星々」と言ったね…\n私は死を迎えた時、暗闇の中を流れる河を見た。",
  ui_story_5084_50841002_93_dialog_content = "そこにはこの世の因果が流れていた。\n少しでも揺れ動けば大難につながるものだ。",
  ui_story_5084_50841002_94_dialog_content = "長命の血の一族が無限に近い時間の果てに見つけるものは、\nその河の一粒の砂に過ぎない…",
  ui_story_5084_50841002_95_dialog_content = "たとえそうであっても、\nそれを追い求める執念が私を河へと向かわせる。",
  ui_story_5084_50841002_96_dialog_content = "ゆえに私は私の真理を信じる。実践の道はどこまでも辛く厳しいが、\n苦難を打ち払った後には、願う心がきっと因果の流れを変えられる。",
  ui_story_5084_50841002_97_dialog_content = "あなたはその信念が長く存在し続け、\nあなたの敵視する「運命の束縛」を超越すると考えているの？",
  ui_story_5084_50841002_98_dialog_content = "信念に従い、信念を実践する――そうすれば、運命を看破する契機は必ず見つかる。\nその時はこの手で因果の流れを変えてみせる。",
  ui_story_5084_50841002_99_dialog_content = "…さあ、行け、ビクトリア。\n己の道を進み、立ちはだかる障害を取り除け。",
  ui_story_5084_50841002_100_dialog_content = "言われなくてもそうするわ。",
  ui_story_5084_50841002_101_dialog_content = "デービーが私たちの村を死域に変えてしまう前に、阻止するのだ。",
  ui_story_5084_50841002_102_dialog_content = "あなたはどこへ？",
  ui_story_5084_50841002_103_dialog_content = "私は時間の外を漂う存在だ。\n運命でない限り、むやみに何かを変えることは許されない…",
  ui_story_5084_50841002_104_dialog_content = "…あの時の会話を終わらせることができるとは思ってなかったわ、叔父さま。",
  ui_story_5084_50841002_105_dialog_content = "ビクトリア、よくここまで…成長した。",
  ui_story_5084_50841002_106_dialog_content = "「災典」を持って行け。役に立つはずだ。",
  ui_story_5084_50841002_107_dialog_content = "真理を追い求めるのに必要な力ならもう持っているわ。\nそれは必要ない。",
  ui_story_5084_50841002_108_dialog_content = "…運命がまた君たちを引き合わせてくれるだろう。",
  ui_story_5084_50841002_109_dialog_content = "ビクトリア、これでお別れだ。",
  ui_story_5084_50841002_110_dialog_content = "君の信者…ネイルスという若者は見込みがあるな。",
  ui_story_5084_50841002_111_dialog_content = "真理結社の未来は君たちに任せた。",
  ui_story_5084_50841002_112_dialog_content = "…また会えるかしら？",
  ui_story_5084_50841002_113_dialog_content = "主に与えられた試練はやり遂げた。\nこれからは己のためにすべきことをするよ。",
  ui_story_5084_50841002_114_dialog_content = "すべてに片がついたら、\nまたここで会おう。",
  ui_story_5084_50841002_115_dialog_content = "…それから未来から来た空の末裔、\nあの時の私を真摯に導いてくれた君に礼を言う。",
  ui_story_5084_50841101_1_dialog_content = "もうっ、おばあちゃんのせいだよ…真理の主に伝えたいことがあるから、\n全部覚えてから行けなんて…",
  ui_story_5084_50841101_2_dialog_content = "おかげで後ろの方になっちゃったじゃん。\nこれじゃ巡行が見えないよ。",
  ui_story_5084_50841101_3_dialog_content = "おばあちゃんは足が悪いから、もう聖鳴祭には来られないでしょ。",
  ui_story_5084_50841101_4_dialog_content = "それでも信者のために生涯をかけて服を縫ってるの。\nだから、お前には代わりに真理の主への思いを届けてほしいのよ。",
  ui_story_5084_50841101_5_dialog_content = "後でママが抱っこして見せてあげるから――その代わり、おばあちゃんの言う通り、\n敬虔な気持ちで巡行を見るのよ。遊びと勘違いしちゃダメ。",
  ui_story_5084_50841101_6_dialog_content = "…わかった。",
  ui_story_5084_50841101_7_dialog_content = "あ、ここってあそこじゃん。PlayerNameに会った所だ。",
  ui_story_5084_50841101_8_dialog_content = "それにしても人が多いなぁ…\nどうすればネイルスさんを見つけられるんだろ？",
  ui_story_5084_50841101_9_dialog_content = "メイ…その時も、この奇妙なマントの人たちを見たかい？",
  ui_story_5084_50841101_10_dialog_content = "うーん…どうだったかな…",
  ui_story_5084_50841101_11_dialog_content = "きゃあ――！！！",
  ui_story_5084_50841101_12_dialog_content = "…？行こう！",
  ui_story_5084_50841101_13_dialog_content = "…死徒だ！死徒が出た――！",
  ui_story_5084_50841101_14_dialog_content = "偉大なる主よ…私を罰しておられるのですね！私は姉の日記を盗み見ただけでなく、\n公衆の面前で、その偽りの姿を暴きました…",
  ui_story_5084_50841101_15_dialog_content = "しかし当主様たちのお話では、私の身体は病に侵されているため、\nこの血はもう、あなた様のお気には召さないとのこと…",
  ui_story_5084_50841101_16_dialog_content = "ならば、この肉を割いて罰をお受けいたしましょう…！",
  ui_story_5084_50841101_17_dialog_content = "ママ…？",
  ui_story_5084_50841101_18_dialog_content = "ただ…娘に罪はありません。どうか、娘だけは…",
  ui_story_5084_50841101_19_dialog_content = "主よ！",
  ui_story_5084_50841101_20_dialog_content = "ああ、この方々は…私を罰するために、あなた様がお送りになったのですね。\n偉大なる真理の主よ！",
  ui_story_5084_50841101_21_dialog_content = "分かりました。喜んで罰をお受けします！",
  ui_story_5084_50841101_22_dialog_content = "――！",
  ui_story_5084_50841101_23_dialog_content = "ママ――！",
  ui_story_5084_50841101_24_dialog_content = "ああ…！",
  ui_story_5084_50841101_25_dialog_content = "は、早く…！！早く逃げなさい！",
  ui_story_5084_50841101_26_dialog_content = "マントのバケモノたちだ…道の向こうから血が流れてきてる…\n誰かが襲われてるよ！",
  ui_story_5084_50841101_27_dialog_content = "…！メイ、戦う準備だ！",
  ui_story_5084_50841101_28_dialog_content = "やはり…ビクトリア様の介入を始まりとして、\n「運命」が僕たちの介入を許したようだ。",
  ui_story_5084_50841101_29_dialog_content = "うん、わかった！悪い子には、お仕置きだよ！",
  ui_story_5084_50841101_30_dialog_content = "…痛みなど感じません！",
  ui_story_5084_50841101_31_dialog_content = "まだまだ……！",
  ui_story_5084_50841101_32_dialog_content = "ああ…！",
  ui_story_5084_50841101_33_dialog_content = "ママ――！！",
  ui_story_5084_50841101_34_dialog_content = "迷える子羊よ、恐れることはありません…\n「聖血」が固まってきた…",
  ui_story_5084_50841101_35_dialog_content = "お兄さんは…啓示を受けし者！どうして自分を刺してるの！？",
  ui_story_5084_50841101_36_dialog_content = "幼子よ、これは私の力ではありません…\n私は啓示を受けし者ではない、ネイルスです…",
  ui_story_5084_50841101_37_dialog_content = "真理の主はおっしゃいました――己を責めるな、哀れむなと。",
  ui_story_5084_50841101_38_dialog_content = "あなたの母上が私と同様、罪深き者ならば…\nこの私が――",
  ui_story_5084_50841101_39_dialog_content = "罪人に代わり、答えましょう！",
  ui_story_5084_50841101_40_dialog_content = "お兄さん…？それは…なに？",
  ui_story_5084_50841101_41_dialog_content = "罪…そして祝福でもあります…",
  ui_story_5084_50841101_42_dialog_content = "これが…導師のおっしゃった「聖血」の力なのですね！",
  ui_story_5084_50841101_43_dialog_content = "鮮やかに赤く燃え上がる炎…主が今、私の身体の中を流れていきます。\n私に火を点け、至上のぬくもりを与えくださっています！",
  ui_story_5084_50841101_44_dialog_content = "迷える子羊よ、しかと目に焼き付けるのです――",
  ui_story_5084_50841101_45_dialog_content = "真理の主が私たちの罪をお許しくださいます！",
  ui_story_5084_50841101_46_dialog_content = "…！",
  ui_story_5084_50841101_47_dialog_content = "あ、あなたは…あの時の…啓示を受けし者！\n「聖徒」となられたのですね！",
  ui_story_5084_50841101_48_dialog_content = "いえ…聖徒と呼ばれるには…私はまだ…",
  ui_story_5084_50841101_49_dialog_content = "その服…ずっと着ててくれたんだね…\nママとおばあちゃんと一緒に縫った聖徒の服…",
  ui_story_5084_50841101_50_dialog_content = "あなた方ご家族の心のこもった贈り物に感謝いたします。\nおかげで、今の私があります。",
  ui_story_5084_50841101_51_dialog_content = "あの時は、ヴィルヘルム様にも何かお考えがあったのでしょう…\n今年は必ずや啓示を受けし者となられるでしょう！",
  ui_story_5084_50841101_52_dialog_content = "導師が伝えてくださったのも、また崇高な真理――\n今、私の胸は感謝の気持ちでいっぱいです。",
  ui_story_5084_50841101_53_dialog_content = "ひとまず危険は去りました。さあ、今のうちにお逃げください。",
  ui_story_5084_50841101_54_dialog_content = "はい！真理の祝福あれ、「聖徒」ネイルス様！",
  ui_story_5084_50841101_55_dialog_content = "真理の祝福あれ、ネイルス様！",
  ui_story_5084_50841101_56_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50841101_57_dialog_content = "「聖徒」ネイルス様！",
  ui_story_5084_50841101_58_dialog_content = "僕たちも遠くから、あのバケモノを消すのを見ていたよ。",
  ui_story_5084_50841101_59_dialog_content = "ああ、メイ、ファウスト…お久しぶりです。",
  ui_story_5084_50841101_60_dialog_content = "なんだ、ぜんっぜん…元気じゃないですか！",
  ui_story_5084_50841101_61_dialog_content = "あたしもナビゲーターもすっごく心配したんですよ！",
  ui_story_5084_50841101_62_dialog_content = "私の思いあがりのせいで…皆さんに心配をかけてしまいました…\n懺悔しなければなりません…",
  ui_story_5084_50841101_63_dialog_content = "それにしても、さっきの力すご過ぎません！？\nまさか、その服のおかげですか？",
  ui_story_5084_50841101_64_dialog_content = "それも理由の1つでしょう…\nこの3年間、私はずっと先程の縫い物屋の親子の縫ってくれた服を着ていましたから。",
  ui_story_5084_50841101_65_dialog_content = "えっ…？どこにも行ってなかったんですか？\nまさか3年間…ずっとワラーキ村にいたとか？",
  ui_story_5084_50841101_66_dialog_content = "修行もすでに3年…導師には本当にたくさんの所へ連れて行っていただきました…\nずっと村に留まっていたわけではありません。",
  ui_story_5084_50841101_67_dialog_content = "導師…",
  ui_story_5084_50841101_68_dialog_content = "つまりは…「稀血」が新たな形を成すようになったのは、\nその導師と修行したから、ということかい？",
  ui_story_5084_50841101_69_dialog_content = "はい…導師はおっしゃいました。「稀血」は呪いではないと…",
  ui_story_5084_50841101_70_dialog_content = "「かの地で失い、この地で得る。かの地で罪を贖い、この地で恩恵を得る」と。",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>3年前…</color>",
  ui_story_5084_50841102_2_dialog_content = "偉大なる真理の主よ。\n信徒ネイルスにどうか解脱を賜りますようお願い申し上げます…",
  ui_story_5084_50841102_3_dialog_content = "私の血はけがれているのです…とうに準備はできています…",
  ui_story_5084_50841102_4_dialog_content = "ここは…",
  ui_story_5084_50841102_5_dialog_content = "ビクトリア様は敬虔が導いてくれるとおっしゃいましたが…\n今、私はこうしていけにえに…",
  ui_story_5084_50841102_6_dialog_content = "このまま…",
  ui_story_5084_50841102_7_dialog_content = "…",
  ui_story_5084_50841102_8_dialog_content = "…真理の主？",
  ui_story_5084_50841102_9_dialog_content = "あなた様は…偉大なる真理の主！",
  ui_story_5084_50841102_10_dialog_content = "今…「ビクトリア様」と言ったか？",
  ui_story_5084_50841102_11_dialog_content = "私は罪深き者です…でも、それはビクトリア様には関係のないことです。",
  ui_story_5084_50841102_12_dialog_content = "ビクトリア様は私を受け入れてくださいました。真理結社の仲間も私を守ってくれます。\nですが、私はこのけがらわしい血で世界をけがす以外、何の役にも立てないのです。",
  ui_story_5084_50841102_13_dialog_content = "真理結社の指導者ビクトリアのことか？\n君は、真理結社の者か？",
  ui_story_5084_50841102_14_dialog_content = "偉大なる主…私はネイルスと申します。",
  ui_story_5084_50841102_15_dialog_content = "ここには、君1人か？",
  ui_story_5084_50841102_16_dialog_content = "ビクトリア様とファウスト、メイ、空の末裔とは…\n星空の墓所に入った後にはぐれてしまいました。",
  ui_story_5084_50841102_17_dialog_content = "あなた様が皆を別の場所へお導きになったのですね…\n善良かつ勇敢で、輝かしい彼らは…",
  ui_story_5084_50841102_18_dialog_content = "「真理を導く者」は…",
  ui_story_5084_50841102_19_dialog_content = "君たちを導いていたのか…\n真理結社にまさか空の末裔が加わろうとは…",
  ui_story_5084_50841102_20_dialog_content = "「真理はその心にすでに表れている。彼こそは真理結社の変革の力、\n真理の祝福を受けし者。」",
  ui_story_5084_50841102_21_dialog_content = "真理の祝福を受けし者…",
  ui_story_5084_50841102_22_dialog_content = "君は真理の主に何を懺悔したいのだ？",
  ui_story_5084_50841102_23_dialog_content = "懺悔いたします…私は、生まれながらにして背負う罪を懺悔いたします。\nこれをご覧ください…",
  ui_story_5084_50841102_24_dialog_content = "このような血は私のような怪物にしか流れぬもの…\nこれは罪です。",
  ui_story_5084_50841102_25_dialog_content = "愚かなことを…",
  ui_story_5084_50841102_26_dialog_content = "な、なんとおっしゃいましたか…？",
  ui_story_5084_50841102_27_dialog_content = "太陽が沈むにはまだ早い。\n君の罪深き過去をじっくり聞いてやろうと言ったのだ。",
  ui_story_5084_50841102_28_dialog_content = "私が何をしようと構うな。話したいだけ話すがいい。",
  ui_story_5084_50841102_29_dialog_content = "ただし条件がある。その釘をしまいなさい。\nここはワラーキの墓所だ。1滴の血も落とすことは許されない。",
  ui_story_5084_50841102_30_dialog_content = "はい、我が偉大なる真理の主よ！",
  ui_story_5084_50841102_31_dialog_content = "それと言っておくが、私は真理の主ではない。",
  ui_story_5084_50841102_32_dialog_content = "では、あなた様はいったい…？",
  ui_story_5084_50841102_33_dialog_content = "ヴィルヘルムだ。そして当然ながら、ワラーキという…\nふさわしからぬ姓を持っている。",
  ui_story_5084_50841102_34_dialog_content = "…ワラーキですと！ビクトリア様と同じ高貴な一族の方なのですね！",
  ui_story_5084_50841102_35_dialog_content = "ふっ、高貴か。たかが符号にさほど恐れをなす必要もあるまい。",
  ui_story_5084_50841102_36_dialog_content = "今の私は真理結社と深い縁故を持つと同時に、時間の外を漂流する者――",
  ui_story_5084_50841102_37_dialog_content = "その私の前に君は現れた。さあ、答えてもらおう。\n誰が君を怪物と呼んだのだ？",
  ui_story_5084_50841102_38_dialog_content = "私の…弟です。私の両親…そして一族の全員が…",
  ui_story_5084_50841102_39_dialog_content = "先刻見せてくれたように、君が「稀血」の持ち主だからか？",
  ui_story_5084_50841102_40_dialog_content = "…もちろん、それだけではありません。私の存在自体が…\n弟を傷つけ、家族に恥をかかせたからです。",
  ui_story_5084_50841102_41_dialog_content = "弟は私の結社の友人たちと同じく、\n善良で、勇敢で輝いていました…",
  ui_story_5084_50841102_42_dialog_content = "にも関わらず、この力があるがゆえに、\n私ばかりが順調に叙爵昇叙し、騎士の戦いでも勝利を収め…",
  ui_story_5084_50841102_43_dialog_content = "一方の弟は…そうではありませんでした…",
  ui_story_5084_50841102_44_dialog_content = "敵対する一族の令息が弟に汚い手を使った時、\n私は身の程知らずにも前に出て、弟を守ろうとしました…",
  ui_story_5084_50841102_45_dialog_content = "ところが…",
  ui_story_5084_50841102_46_dialog_content = "弟は…弟はきっと、一族のことを考えてそうしたのでしょう。\n私のような者はあの純潔、高貴な地では、罪以外の何物でもありません。",
  ui_story_5084_50841102_47_dialog_content = "だから弟は私を解放しようと…「稀血」を人目にさらし…\n白夜城から追放されるようにしたのです。",
  ui_story_5084_50841102_48_dialog_content = "どこかで聞いたことのある話だ…",
  ui_story_5084_50841102_49_dialog_content = "その後、君は各地を転々とし、ビクトリアに受け入れられ、\n真理結社に行きついたというわけか？",
  ui_story_5084_50841102_50_dialog_content = "はい…かつて私は暗鬼との戦いの中で、この命を終えたいと思っていました…",
  ui_story_5084_50841102_51_dialog_content = "ですが、主は私の罪の深さをご存知なのです。「稀血」に幾度も生死の境から救わせ、\n私にこの罪の深さをしかと知らしめんとなさいました…",
  ui_story_5084_50841102_52_dialog_content = "懺悔が足りないのです…私には、まだ真理の主の懐に抱かれる資格がありません。",
  ui_story_5084_50841102_53_dialog_content = "…",
  ui_story_5084_50841102_54_dialog_content = "も、申し訳ございません、つい自分の話ばかり…ヴィルヘルム様、私は先程身の程知らずにも\nようやく許しを得、主の懐に抱かれたと思ったのです。",
  ui_story_5084_50841102_55_dialog_content = "私には、君は貴族の家に生まれ、\n類まれな才能に恵まれていたとしか聞こえないが。",
  ui_story_5084_50841102_56_dialog_content = "一方、才に恵まれなかった弟はそれを妬み、家長の地位を得ようと、\n君を亡き者にすべく手を尽くした。",
  ui_story_5084_50841102_57_dialog_content = "その弟は今、当主の座を継いだのか？",
  ui_story_5084_50841102_58_dialog_content = "弟は得るべきものを得たまでです…それに…\n私を「亡き者」にしようとなど、していません…",
  ui_story_5084_50841102_59_dialog_content = "ふっ、それはどうかな…白夜城貴族の子息が善良？勇敢？輝かしい？",
  ui_story_5084_50841102_60_dialog_content = "真理結社の12代目当主は白夜城から排斥を受けた「異端者」だった。",
  ui_story_5084_50841102_61_dialog_content = "もしその「異端者」がいなければ、今の真理結社はない。",
  ui_story_5084_50841102_62_dialog_content = "私は確かに白夜城から排斥された「異端者」です…\nでも弟は…",
  ui_story_5084_50841102_63_dialog_content = "では、話してみろ。君が家を出る時、弟はどのような顔をしていた？",
  ui_story_5084_50841102_64_dialog_content = "…",
  ui_story_5084_50841102_65_dialog_content = "おや？君は生涯忘れられないのではないか？\n人目もはばからず、兄を亡き者にしようとした弟が兄を見送る時の顔を？",
  ui_story_5084_50841102_66_dialog_content = "弟は…微笑み、私を祝福してくれました。",
  ui_story_5084_50841102_67_dialog_content = "ハハハ！他人を虐げ、迫害する者はいつの時代も、\nもっともらしい罪をその対象に着せるものだ。",
  ui_story_5084_50841102_68_dialog_content = "ゆえに君も己は罪深き者と思い込み、真理結社に入った。\nその後も長きにわたり、懺悔と自傷を続けてきたというわけだ。",
  ui_story_5084_50841102_69_dialog_content = "懺悔とは、己に対する嫌悪が源となっている――\n君は「稀血」を嫌悪しているのだ！",
  ui_story_5084_50841102_70_dialog_content = "そして、その嫌悪とは君が邪な者たちに抱く期待が生み出したもの。\n邪な者たちは悪辣な言葉を発し、君はそれを真実だと信じ込む。",
  ui_story_5084_50841102_71_dialog_content = "だが、教えてやる。「稀血」は怪物に与えられるものではない。\n真理の主の祝福だ。",
  ui_story_5084_50841102_72_dialog_content = "稀血が暗鬼を倒す助けとなっていることがその証だ。\nいいか、君には己を嫌悪すべき理由など一つもない。",
  ui_story_5084_50841102_73_dialog_content = "ネイルスよ、君の弟は君にふさわしくない。\nだが悲しいことに、君は良き兄だ。",
  ui_story_5084_50841102_74_dialog_content = "兄と弟が反目し、裏切り、疎遠になる…ヴィルヘルム・ワラーキよ！\n運命が私たちをこうして出会わせたのだ…",
  ui_story_5084_50841102_75_dialog_content = "なんと皮肉なことだろう！",
  ui_story_5084_50841102_76_dialog_content = "いいか、ネイルス。君こそ善良かつ勇敢たる者だ。\n輝かしいと呼ぶには…まだ足りぬかもしれないが…徳が高い…そう徳が高い。",
  ui_story_5084_50841102_77_dialog_content = "その「稀血」の力を他人を守ることに使うのなら、\n君は真の救いを得ることだろう。",
  ui_story_5084_50841102_78_dialog_content = "そのようにお考えになるとは…あなた様は勇敢です。\nですが、私は…",
  ui_story_5084_50841102_79_dialog_content = "君ならできる。",
  ui_story_5084_50841102_80_dialog_content = "…",
  ui_story_5084_50841102_81_dialog_content = "主は何人も眷顧しない。\n君が己を許さずにいるのに、主がどうして君を許そうか？",
  ui_story_5084_50841102_82_dialog_content = "覚えておくのだ。己を認めてこそ、主は君を認める。",
  ui_story_5084_50841102_83_dialog_content = "ヴィルヘルム様、なぜ私にそのようなことをお話しになるのですか？",
  ui_story_5084_50841102_84_dialog_content = "私は知っているのだ。\n今この時私たちが出会ったことで、運命が変わった。",
  ui_story_5084_50841102_85_dialog_content = "主が私を君のもとに送り込んだのだ。私はそう確信している。",
  ui_story_5084_50841102_86_dialog_content = "ネイルス、今はまだ生涯を終えるべき時ではない。\n君の生涯は今始まったのだ。どうだ、私と共に修行しないか？",
  ui_story_5084_50841102_87_dialog_content = "この身の罪を洗い流すことができるなら、\n何でもいたします。",
  ui_story_5084_50841102_88_dialog_content = "よし。ならばすぐに始めるとしよう。為すべきことがたくさんある。\nだが、ここはそれにふさわしくない…",
  ui_story_5084_50841102_89_dialog_content = "ここは終わりの時だ。君の3年間の修行はあの年の聖鳴祭に始まる。\n君たちがここへやってきた時だ。",
  ui_story_5084_50841102_90_dialog_content = "君の指導者はすでに戻っている。私の後ろにある棺に横たわり、\nワラーキ村の聖鳴祭を思い浮かべるのだ。そこに仲間たちもいる。",
  ui_story_5084_50841102_91_dialog_content = "再び目を開いたら、聖鳴祭の儀式に赴き、私を訪ねろ。\n君は啓示を受けし者に選ばれ、真理の祝福を受けるだろう。",
  ui_story_5084_50841102_92_dialog_content = "どうすれば、そこへ行けるのですか…？",
  ui_story_5084_50841102_93_dialog_content = "信念だ、ネイルス。",
  ui_story_5084_50841102_94_dialog_content = "君がここへ来られたのもその懺悔の信念があったからこそだ。\n己の身体で感じるといい。",
  ui_story_5084_50841102_95_dialog_content = "たった一瞬でも、その生を祝福できた時、君は真理を見ることができるだろう。",
  ui_story_5084_50841102_96_dialog_content = "信念、ですか…？",
  ui_story_5084_50841102_97_dialog_content = "そうだ。今この時から、私は君の導師だ。",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>ワラーキ村、縫い物屋の店先</color>",
  ui_story_5084_50841102_99_dialog_content = "…なぜ…私はここへ？",
  ui_story_5084_50841102_100_dialog_content = "あの、お客様も祝典のローブのお受け取りですか？",
  ui_story_5084_50841102_101_dialog_content = "祝典のローブ…？",
  ui_story_5084_50841102_102_dialog_content = "だからあの時、ワケのわかんないこと言ってたんですね…\nヴィルヘルム様とは、とっくのとっくに知り合いだったんだ…",
  ui_story_5084_50841102_103_dialog_content = "しかも、より不可解な方のヴィルヘルム様だったとは。",
  ui_story_5084_50841102_104_dialog_content = "私は本当に啓示を受けし者に選ばれたのかと思っていました…\n真理の殿堂へ行ったのも、そう思ってのことでしたから。",
  ui_story_5084_50841102_105_dialog_content = "こうして改めて話してみると、実に不思議でなりません。\n導師と初めて会ったのは、いつだと言うのが正しいのでしょう？",
  ui_story_5084_50841102_106_dialog_content = "導師は私を聖鳴祭当日に戻してくださいましたが、\nその時の導師は私のことは知らず…",
  ui_story_5084_50841102_107_dialog_content = "その後、どうなったんですか？\nヴィルヘルム様に教会の外に放り投げられてから、どうなったんです？",
  ui_story_5084_50841102_108_dialog_content = "…",
  ui_story_5084_50841102_109_dialog_content = "ああ…罪深き我が血液よ、ことごとく流れ去るのです…\nもう二度と主の赦しは乞いません…",
  ui_story_5084_50841102_110_dialog_content = "私は…私は罪深い…",
  ui_story_5084_50841102_111_dialog_content = "どこへ行こうとも、\n私はこの世に災厄をもたらす怪物でしかないのです。",
  ui_story_5084_50841102_112_dialog_content = "聖鳴祭に急ぐあまり、縫い物屋の親子の好意を無にしてしまった…",
  ui_story_5084_50841102_113_dialog_content = "私に出会ったせいで、収入を得る機会を失ってしまった…",
  ui_story_5084_50841102_114_dialog_content = "先程の方々は…私の本質を見抜いていた…\nだから私を啓示を受けし者と認めず、死を与えようとした…",
  ui_story_5084_50841102_115_dialog_content = "私は啓示を受けし者ではない…\n私のせいで導師は同門の方々と争うことに…",
  ui_story_5084_50841102_116_dialog_content = "私はどこへ行こうと、忌み嫌われる存在なのです…",
  ui_story_5084_50841102_117_dialog_content = "ううっ…ああ…",
  ui_story_5084_50841102_118_dialog_content = "手足がしびれてきました…先程まで感じていた冷たさが…\n今は懐かしい暖かさに変わっています…",
  ui_story_5084_50841102_119_dialog_content = "これもいい…",
  ui_story_5084_50841102_120_dialog_content = "罪深き心を抱き、静かに永遠の眠りにつけば、\n二度と世界に災いをもたらすことはありません。",
  ui_story_5084_50841102_121_dialog_content = "私は…",
  ui_story_5084_50841102_122_dialog_content = "私の言葉が足りなかったか。",
  ui_story_5084_50841102_123_dialog_content = "…？",
  ui_story_5084_50841102_124_dialog_content = "その素晴らしい「稀血」の力をなぜ、そこまで忌み嫌うのだ？",
  ui_story_5084_50841102_125_dialog_content = "…導師？導師ではありませんか！…ご無事だったのですか？",
  ui_story_5084_50841102_126_dialog_content = "動いてはならない。傷口を診てやろう。",
  ui_story_5084_50841102_127_dialog_content = "先程君が会っていたのは私で間違いない。\nだが、最初に会った私ではなく、今ここにいる私でもない。",
  ui_story_5084_50841102_128_dialog_content = "とにかく…私はずっとここから、中で起こる事を見ていたが、\n君に罪があるとはどうしても思えない。",
  ui_story_5084_50841102_129_dialog_content = "私は…あなた様には見えるはずです。この身体には怪物が…",
  ui_story_5084_50841102_130_dialog_content = "怪物だと？君のその能力は、かつての私から見ても恐ろしいほどに強大で、\nかつ真理結社とつながる定めにある力だ…",
  ui_story_5084_50841102_131_dialog_content = "いいか。私の見た未来の真理結社は、奇々怪々でありながら品位を失わず、\n感情豊かでありながら、知性の豊かな者たちが集まる組織だ。",
  ui_story_5084_50841102_132_dialog_content = "己にしかできぬことを追求し続けるのなら、\n時間の河は必ずや君を正しい場所へと送り、正しい人に出会わせてくれる。",
  ui_story_5084_50841102_133_dialog_content = "前に言ったはずだ。君は私と共に修行するのだと。\nならば、君の経験したこともまた修行の一部だ。",
  ui_story_5084_50841102_134_dialog_content = "だが身勝手にも罪深き心を抱いたまま眠りに就こうとしたところを見ると、\n私の言葉を信じていなかったようだな。",
  ui_story_5084_50841102_135_dialog_content = "ああ！我が導師よ…罰をお与えください…\n私は自ら誓ったことを行動に移しませんでした…",
  ui_story_5084_50841102_136_dialog_content = "まあいい。今まで君の心は屈辱を味わい尽くし、\n肉体も痛めつけられ、さすらってきた。君のせいではない。",
  ui_story_5084_50841102_137_dialog_content = "だが、今や君は正しい場所へとやってきたのだ。\n他の者にはないその力で、輝き燃え上がらねばならない。",
  ui_story_5084_50841102_138_dialog_content = "私が…ですか…？",
  ui_story_5084_50841102_139_dialog_content = "よく考えてみろ。他人はともかく、その「稀血」が一度でも\n君自身を傷つけたことはあったか？",
  ui_story_5084_50841102_140_dialog_content = "…",
  ui_story_5084_50841102_141_dialog_content = "のうのうと優雅な暮らしを享受する者たちが先を争って貶める宝も、\n苦境にさすらう者にとっては、頼みの綱となり得る。",
  ui_story_5084_50841102_142_dialog_content = "君は自ら己の魂を傷つけているのだ。他人の犯した罪で己を縛り付けている。\nそれは君や他の者たちを救おうとする、その力の意志を無下にすることに他ならない。",
  ui_story_5084_50841102_143_dialog_content = "君はなぜそれ程まで頑なに「稀血」の力が怪物を倒し、\n他の者たちを救えると信じようとしないのだ？",
  ui_story_5084_50841102_144_dialog_content = "皆…私を避け、忌み嫌うでしょう…",
  ui_story_5084_50841102_145_dialog_content = "またそれか…いいか。他人の事ばかりを気に掛けていたのはかつての君だ。\nこれから先は二度とそのような考え方をしてはいけない。",
  ui_story_5084_50841102_146_dialog_content = "君自身が言っていただろう？「罪を洗い流すことができるのなら、何でもする」と。\nならば、己に罪はないと信じることから始めるのだ。",
  ui_story_5084_50841102_147_dialog_content = "できるか？",
  ui_story_5084_50841102_148_dialog_content = "導師…",
  ui_story_5084_50841102_149_dialog_content = "分かっている。君は聡明だ。\n私の言っていることを理解できるはずだ。",
  ui_story_5084_50841102_150_dialog_content = "共に私の住まいへ来い。修行にはふさわしい所だ。",
  ui_story_5084_50841102_151_dialog_content = "そこを起点として、各村へ赴き、\n迷える子羊を探し、救えばいい。",
  ui_story_5084_50841102_152_dialog_content = "君のその力で子羊たちを救い、導くのだ。\nそうすれば、「稀血」は人々から祝福を受けるだろう。",
  ui_story_5084_50841102_153_dialog_content = "「稀血」が真理の祝福を浴び、さらに時を経たのち、\n君は修行で得たことを悟り、理解することができるだろう。",
  ui_story_5084_50841102_154_dialog_content = "…分かりました。",
  ui_story_5084_50841102_155_dialog_content = "そうして3年間…私はあちこちを巡り、自らの気性を正し、\n他人の言葉に耳を傾けてきました。",
  ui_story_5084_50841102_156_dialog_content = "他人の痛みを癒していくうち、\n「稀血」の力が少しずつ変わっていくことには気づいていましたが…",
  ui_story_5084_50841102_157_dialog_content = "先程、縫い物屋の親子を助けた時に初めて、\nこの3年間の修行が真に実を結んだのです。",
  ui_story_5084_50841102_158_dialog_content = "真理結社に入った後も、私は長い間耳を塞いだまま、\nひたすら己の心を吐露し、懺悔するばかりでした…",
  ui_story_5084_50841102_159_dialog_content = "導師は私の罪の根源にお気づきになっていたのです…\n私はその絶え間なき吐露で、真理の声を自ら遮断していたと…",
  ui_story_5084_50841102_160_dialog_content = "後ろ向きな言葉が私の思想を形づくり、\n罪をさらに深く重いものに変えていたのです…",
  ui_story_5084_50841102_161_dialog_content = "あまりにも浅はかな悟りがゆえに、\n真理は私の身に現れようとしなかったのです…",
  ui_story_5084_50841102_162_dialog_content = "本当は、真理はずっとこの信念の中にあったというのに…",
  ui_story_5084_50841102_163_dialog_content = "真理とは、苦痛と同様、誰かに加担することはありません。",
  ui_story_5084_50841102_164_dialog_content = "かの地で失ったものは私が失うべきもの、\nこの地で得たものもまた、私が得るべきものなのです。",
  ui_story_5084_50841102_165_dialog_content = "かの地で贖うべきは、真の罪でなければなりません。\nこの地で得た恩恵はすべて信者たちが私に与えてくれた祝福なのです。",
  ui_story_5084_50841102_166_dialog_content = "ネイルスさんの言ってること、半分以上わかんないけど…",
  ui_story_5084_50841102_167_dialog_content = "その顔を見てたら、なんだか心があったかくなってきました…\nあったかいお風呂に入ったみたいに。",
  ui_story_5084_50841102_168_dialog_content = "導師が教えてくださいました。「稀血」は罪などではなく、神聖なるものだと――\n私は常に真理の主の懐に抱かれているのですから。",
  ui_story_5084_50841102_169_dialog_content = "今のその様子を見たら、ビクトリア様もきっと喜ぶよ。",
  ui_story_5084_50841102_170_dialog_content = "ただ…ビクトリア様は順調だろうか？",
  ui_story_5084_50841102_171_dialog_content = "あたしはビクトリア様を信じてるよ！それにもっと大事なのは、\nあたしもビクトリア様の役に立てるって信じてることだよ！",
  ui_story_5084_50841102_172_dialog_content = "導師から修行も一段落着いたと言われました。\nならば、私はこの力で真理結社に貢献しなければなりません。",
  ui_story_5084_50841102_173_dialog_content = "行きましょう。この喜びをビクトリア様に、\nさらに多くの信者たちに伝えなければ。",
  ui_story_5084_50841201_1_dialog_content = "たとえ二度と乗客が現れずとも、僕は約束する。\n必ずやお父様を説得し、君をアストラ大陸一周旅行に連れて行こう。",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>ガタガタガタ――ガタガタ――</color>",
  ui_story_5084_50841201_3_dialog_content = "…待っていてくれ。窓を閉めてくる。",
  ui_story_5084_50841201_4_dialog_content = "うわ――！",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5084_50841201_6_dialog_content = "おかしい…最近あの忌々しい奴らがしょっちゅう\nこの辺りをうろついている…",
  ui_story_5084_50841201_7_dialog_content = "だが、お父様は窓を閉めろと言うだけで、後は心配するなとしか言わない。\nそれに…お父様はいったいどこにいるのだ…",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>赤い月がワラーキ村の空に浮かび、片時も休まず時を刻む歴史の振り子のように、\n聖鳴祭の真夜中の訪れを告げた</color>",
  ui_story_5084_50841201_9_dialog_content = "なんと幻想的な光景だろう…\n毎日こんな夜が訪れてくれればいいのに…",
  ui_story_5084_50841201_10_dialog_content = "真理結社の新しい指導者が今日決まるんだよな…\nだが、ちょっと前に人が殺されたって聞いたぞ…",
  ui_story_5084_50841201_11_dialog_content = "指導者が変わるのは珍しいことじゃない。でも当主様たちは\nワラーキの血筋以外の信者を排除してる――僕はそっちの方が気になるよ。",
  ui_story_5084_50841201_12_dialog_content = "この血のように赤い月の輝きは、\n唯一無二の血筋だけを照らすんだろう？",
  ui_story_5084_50841201_13_dialog_content = "真理の殿堂にある棺に入りたければ、主の教えに耳を傾けなきゃいけない。\nでも、それは僕たちがどうこうできるものじゃない。",
  ui_story_5084_50841201_14_dialog_content = "血統論なんて信じるものじゃないさ。\n3年前、真理の主はワラーキのお嬢様を拒絶なさったんだからね…",
  ui_story_5084_50841201_15_dialog_content = "代わりに隠者修行をしていた信者に降臨なさった。\n今やその方は聖徒となり、主の与えた力で人々を救っておられる。",
  ui_story_5084_50841201_16_dialog_content = "しかも、よその村の信者だったって話だ。もしかしたら…\nワラーキ村の外には、もっと大きな真理の地が広がってるのかもしれないね。",
  ui_story_5084_50841201_17_dialog_content = "確かに聖徒様の件は、僕たちにとって大きな気づきになったね。\n当主様たちも大きな変革の波に直面してるみたいだよ。",
  ui_story_5084_50841201_18_dialog_content = "今日決まる新しい指導者が本当にポルフィリオ様だったら、\n真理結社の将来は、もっと厳しいものになるだろうね…",
  ui_story_5084_50841201_19_dialog_content = "世界が変われば、真理もまた変わる――\nこの地に真理の祝福あれ。",
  ui_story_5084_50841201_20_dialog_content = "ビクトリア様とナビゲーターの姿がまだ見えないんだけど…\nまさか何かあったワケじゃないよね？",
  ui_story_5084_50841201_21_dialog_content = "ビクトリア様はおっしゃったことを必ずお守りになります――ただ人目をはばかり、\n信徒たちがいなくなってから、姿をお見せになるおつもりかもしれません。",
  ui_story_5084_50841201_22_dialog_content = "いや、この状況でビクトリア様が人目をはばかる必要はないと思うよ。",
  ui_story_5084_50841201_23_dialog_content = "PlayerNameも一緒だからね。人混みの中でもすぐに分かるはずだ。",
  ui_story_5084_50841201_24_dialog_content = "ファウストさんの言う通りだね！あたし、予感がするの。\n今夜あたしは真理結社の奇跡を見ることになるって！",
  ui_story_5084_50841201_25_dialog_content = "アハハ、帰ったら、お姉ちゃんに自慢しよっと。",
  ui_story_5084_50841201_26_dialog_content = "村では死徒による傷害事件が起こっているというのに、\n祭りのために多くの信徒が街に繰り出しているね。",
  ui_story_5084_50841201_27_dialog_content = "さすがは晨光歴2000年まで続いていく祭典というべきか…",
  ui_story_5084_50841201_28_dialog_content = "巡行に参加する信徒たちの安全を守るため、\n私が警戒しておきましょう。",
  ui_story_5084_50841201_29_dialog_content = "もうだいぶ経つのに…ビクトリア、まだかな…",
  ui_story_5084_50841201_30_dialog_content = "見たか？あのワラーキ家のお嬢様が儀式に参加しに来たぞ！",
  ui_story_5084_50841201_31_dialog_content = "ああ…しかも派手な服をまとって…真理結社の規則に反することだ！",
  ui_story_5084_50841201_32_dialog_content = "（…服を着替えに行ってたの？ビクトリアは…？）",
  ui_story_5084_50841201_33_dialog_content = "お嬢様はずっと叔父さんとそりが合わなかったんだ。\n結社の規則を守らなくても、特段おかしくはないだろ…",
  ui_story_5084_50841201_34_dialog_content = "ワラーキ家もついに長の地位を譲るのか…",
  ui_story_5084_50841201_35_dialog_content = "それはないだろ。ビクトリアお嬢様は真理結社を率いるために\n戻ってきたって話だからな。",
  ui_story_5084_50841201_36_dialog_content = "それ、本当の話か？だって、お嬢様は3年前の聖鳴祭で…",
  ui_story_5084_50841201_37_dialog_content = "それもどうなったか分からないさ…\n何しろ棺に入ったのは、他でもないワラーキのお嬢様だったんだからな。",
  ui_story_5084_50841201_38_dialog_content = "それに…理由はともかく、数百年もずっとそうだったんだ。\n真理結社の指導者はやっぱりワラーキ家が継いでこそ安心できる気がするな…",
  ui_story_5084_50841201_39_dialog_content = "…待たせたわね。",
  ui_story_5084_50841201_40_dialog_content = "…わぁ…儀式のために、わざわざ正装に着替えたの？",
  ui_story_5084_50841201_41_dialog_content = "それだけではないわ。この服はワラーキをまだ気に掛けてくれている人が、\n私が村にいることを知って、わざわざ送り届けてくれたものでしょうね。",
  ui_story_5084_50841201_42_dialog_content = "この仕立ては、1人2人の縫子が短時間で仕上げられるものではないわ。",
  ui_story_5084_50841201_43_dialog_content = "その人たちはこの服を通じて、今まさに勢いに乗っている当主たちに、\n自分たちの不満を表明する気なのかもしれないわね。",
  ui_story_5084_50841201_44_dialog_content = "だから、その人たちの期待に応えるためにも、\n真理結社の指導者たる力があるってことを証明するためにも…",
  ui_story_5084_50841201_45_dialog_content = "その服を着て、今日の儀式に参加するんだね？",
  ui_story_5084_50841201_46_dialog_content = "力と服との間には何の関係もないわ。\n古い服も新しい服も、どちらも私の力にふさわしい。",
  ui_story_5084_50841201_47_dialog_content = "ただ、長い歴史を持つこの村に欠けているのは、\n人々の心を奮い立たせる変化よ。",
  ui_story_5084_50841201_48_dialog_content = "教典や指輪、赤い月もすべて形式でしかない。\nそして形式とは、人々が重要だと思う瞬間を記録しているだけ。",
  ui_story_5084_50841201_49_dialog_content = "当主たちがこうした人目を引く変化を嫌うというなら、\n私がそれを見せつけてあげるわ。",
  ui_story_5084_50841201_50_dialog_content = "何しろ彼らの目には、女性のきらびやかな変身は、\n弱々しい過去との決別に映るでしょうからね。",
  ui_story_5084_50841201_51_dialog_content = "うーん…僕には、すごく似合ってるってことしか分からないな。",
  ui_story_5084_50841201_52_dialog_content = "PlayerName！PlayerName！",
  ui_story_5084_50841201_53_dialog_content = "あ、みんな！",
  ui_story_5084_50841201_54_dialog_content = "フッフ～ン！あたしったら、人混みの中で\nひときわ光り輝くビクトリア様を一目で見つけちゃった！",
  ui_story_5084_50841201_55_dialog_content = "遠くから見た時は、ビクトリア様だって信じられませんでした！",
  ui_story_5084_50841201_56_dialog_content = "今はどうかしら？",
  ui_story_5084_50841201_57_dialog_content = "ビクトリア様です！前よりもさらに美しくなったビクトリア様です！",
  ui_story_5084_50841201_58_dialog_content = "ビクトリア様、すべて順調に進んだようで何よりです。\nおめでとうございます。",
  ui_story_5084_50841201_59_dialog_content = "ネイルスにも大きな変化があったようね。",
  ui_story_5084_50841201_60_dialog_content = "ビクトリア様、お久しぶりでございます。\nこれもすべて導師の教えのおかげです…",
  ui_story_5084_50841201_61_dialog_content = "ビクトリア様に…お話ししたいことが山ほどあるのです！",
  ui_story_5084_50841201_62_dialog_content = "そうね。街でのあなたの行いを見せてもらったわ。\nまた今度話を聞かせてちょうだい。",
  ui_story_5084_50841201_63_dialog_content = "そろそろ時間ね。",
  ui_story_5084_50841201_64_dialog_content = "ですが、ビクトリア様、先程から死徒が人を傷つけています…",
  ui_story_5084_50841201_65_dialog_content = "ワラーキ村の伝説に登場する黒い騎士がいったい誰か、\n今の私には分かる…",
  ui_story_5084_50841201_66_dialog_content = "行きましょう。街の信者たちはヴィルヘルムが守ってくれるわ。",
  ui_story_5084_50841201_67_dialog_content = "今夜私は真理結社の力を皆に示さなければならない。\n一緒に教会に来なさい。",
  ui_story_5084_50841201_68_dialog_content = "はい！",
  ui_story_5084_50841201_69_dialog_content = "真理結社に永遠の真理の祝福あれ。",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>ギィ…</color>",
  ui_story_5084_50841201_71_dialog_content = "この人たちは…",
  ui_story_5084_50841201_72_dialog_content = "床に倒れてるけど…これって…",
  ui_story_5084_50841201_73_dialog_content = "…",
  ui_story_5084_50841201_74_dialog_content = "ビクトリア様、全員息がありません…",
  ui_story_5084_50841201_75_dialog_content = "…！",
  ui_story_5084_50841201_76_dialog_content = "私にやらせてください…彼らの代わりに、この私が苦痛を受けましょう。",
  ui_story_5084_50841201_77_dialog_content = "おや…ワラーキ家の当主殿と使用人どもも、\nようやくお出ましか。",
  ui_story_5084_50841201_78_dialog_content = "今日は真理結社の祭典よ。来ないはずがないでしょう？",
  ui_story_5084_50841201_79_dialog_content = "ビクトリア…私は…",
  ui_story_5084_50841201_80_dialog_content = "…",
  ui_story_5084_50841201_81_dialog_content = "クラビス様…全身に傷が…",
  ui_story_5084_50841201_82_dialog_content = "私に背いた結果だよ…",
  ui_story_5084_50841201_83_dialog_content = "私は…どうなっても構わない…だがカロンと妻だけは…",
  ui_story_5084_50841201_84_dialog_content = "真理の殿堂で人を殺めるなんて――",
  ui_story_5084_50841201_85_dialog_content = "そこを動くな、ワラーキ！！",
  ui_story_5084_50841201_86_dialog_content = "あんたねぇっ――！",
  ui_story_5084_50841201_87_dialog_content = "メイ、私の後ろへ。",
  ui_story_5084_50841201_88_dialog_content = "血の一族の戒律をすっかり忘れてしまったようだな。\nならば、クラビスに教えてもらうといい。君がいったいどの戒律を犯したのか…",
  ui_story_5084_50841201_89_dialog_content = "ビクトリア…なぜ…戻ってきた…",
  ui_story_5084_50841201_90_dialog_content = "今さら出てきたところで無駄だ。儀式はすでに終わったのだ。\n主に捧げるべき「いけにえ」もすでに捧げ終わった。",
  ui_story_5084_50841201_91_dialog_content = "今手下たちに食糧を無駄にしないよう教育しているところだ。",
  ui_story_5084_50841201_92_dialog_content = "光霊は真理の主からの贈り物よ。\nそれをあなたは食糧だと言うのかしら？",
  ui_story_5084_50841201_93_dialog_content = "ワラーキ家のお嬢様、君も毎晩のように耐えがたい空腹感に襲われ、\n真夜中になると、使用人たちに新鮮な血液を探させているのだろう？",
  ui_story_5084_50841201_94_dialog_content = "私は自分の「いけにえ」を一滴たりとも無駄にしなかったぞ。",
  ui_story_5084_50841201_95_dialog_content = "だが、クラビスは違ってな。\n食糧を無駄にしただけではなく、私をだました。ハハハ、ウハハハハッ…",
  ui_story_5084_50841201_96_dialog_content = "――！",
  ui_story_5084_50841201_97_dialog_content = "うわあああっ――！やめろ、ポルフィリオ…やめてくれ…！",
  ui_story_5084_50841201_98_dialog_content = "ヴィルヘルムはどこだ！？",
  ui_story_5084_50841201_99_dialog_content = "やめなさい、デービー・ポルフィリオ！",
  ui_story_5084_50841201_100_dialog_content = "ほう？では貴様が代わりに話すか？",
  ui_story_5084_50841201_101_dialog_content = "あれをここへ――",
  ui_story_5084_50841201_102_dialog_content = "…承知いたしました、ビクトリア様。",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>ガッチャーン</color>",
  ui_story_5084_50841201_104_dialog_content = "藤蔓人、何をしている？",
  ui_story_5084_50841201_105_dialog_content = "…私はワラーキのお嬢様の言いつけに従い、巡行の棺を…\nポルフィリオ様の前にお持ちしただけです…",
  ui_story_5084_50841201_106_dialog_content = "ワラーキの先祖の遺体ごときに、\nまさか私が恐れをなすと思っているのか？",
  ui_story_5084_50841201_107_dialog_content = "フッ…あるいはヴィルヘルム・ワラーキと同じ手で、\n逃げ果せようという魂胆か…",
  ui_story_5084_50841201_108_dialog_content = "棺の中に眠っているのは、ヴィルヘルムよ。",
  ui_story_5084_50841201_109_dialog_content = "…？",
  ui_story_5084_50841201_110_dialog_content = "ヴィルヘルムはあなたたちの手にかかって命を落とした。\nそれなのに私に尋ねるなんて滑稽ね。",
  ui_story_5084_50841201_111_dialog_content = "フッ、私の堪忍袋の緒もそう長くは持たんぞ…",
  ui_story_5084_50841201_112_dialog_content = "この血瓶の中の血を飲み干したら、\n次は貴様から養分をいただくとしよう。",
  ui_story_5084_50841201_113_dialog_content = "さあ…来い。吐け！貴様はヴィルヘルムといったい何を企んでいる？",
  ui_story_5084_50841201_114_dialog_content = "ヴィルヘルムなら死んだわ。",
  ui_story_5084_50841201_115_dialog_content = "噓をつけ！",
  ui_story_5084_50841201_116_dialog_content = "ビクトリア、あぶない！",
  ui_story_5084_50841201_117_dialog_content = "ビクトリア様に近づくな！",
  ui_story_5084_50841201_118_dialog_content = "自分の組織を作ろうとした者は君が初めてではない。\nだが、その使用人たちはずいぶんと主思いのようだね。実に結構だ。",
  ui_story_5084_50841201_119_dialog_content = "ただ、他人をバカにするのも程々にするがいい。私はこの目で見たのだ。\n君たち叔父と姪がクサリヘビとパンニングを殺めるのを。",
  ui_story_5084_50841201_120_dialog_content = "あら、怖いのかしら？クサリヘビもパンニングも、\n悪事を企む者は皆、彼の剣によって粛清されるの。",
  ui_story_5084_50841201_121_dialog_content = "どんなにさいなみ、手にかけ、地中に埋めようとも、\nヴィルヘルム・ワラーキを殺すことは永遠に不可能よ。",
  ui_story_5084_50841201_122_dialog_content = "ヴィルヘルムは…生きているのか？本当に…生きているのか？",
  ui_story_5084_50841201_123_dialog_content = "…",
  ui_story_5084_50841201_124_dialog_content = "死んでないってどういうこと…？\nワラーキは死しても、その霊魂は残るというの？",
  ui_story_5084_50841201_125_dialog_content = "この世に霊魂などあるものか！死徒たちでさえ、\nポルフィリオの血を食して、ようやくこうして動くのだ…",
  ui_story_5084_50841201_126_dialog_content = "これこそポルフィリオの持つ死徒の力…\n血の一族の歴史上でも唯一無二の力だ！",
  ui_story_5084_50841201_127_dialog_content = "死してもなお復活する力など、あるはずがない。\n冗談も程々にするがいい。",
  ui_story_5084_50841201_128_dialog_content = "あなたはワラーキの持つ力が先祖の力を継承し、\n遺物から未来の予言を得ることだけだと思っているようね？",
  ui_story_5084_50841201_129_dialog_content = "…？",
  ui_story_5084_50841201_130_dialog_content = "今さっき、私は教典と契約を結んだ。\n私はすでに真理結社の指導者と認められし者となった――",
  ui_story_5084_50841201_131_dialog_content = "ひざまずく信者の敬虔な称賛の声に包まれ、真理に帰する…",
  ui_story_5084_50841201_132_dialog_content = "こうなってみて分かったのだ。ワラーキの血統のみが選ばれるだと？\nそんなもの、権力を握っておくためにワラーキがこじつけた偽りにすぎない。",
  ui_story_5084_50841201_133_dialog_content = "我がポルフィリオ家は、もっと早くにこの栄誉を手にし、\n結社を真理の徒に戻すという責務を果たすべきだったのだ。",
  ui_story_5084_50841201_134_dialog_content = "吸血鬼は…血の主宰者であり、夜の主宰者だ。\nなぜ光に向かい生きる者どもの支配に屈しなければならんのだ！",
  ui_story_5084_50841201_135_dialog_content = "私はこの栄誉を受け入れ、先祖の定めし方法で人々を解放しなければならない――\nそれこそ教典が私に与えた啓示なのだ！",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>理性を奪う激しい戦いがさらにその激しさを増し、\n棺が倒された時、人々は目の当たりにする――</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>真新しい教典が棺から飛び出し、\nまるで運命かのようにビクトリアの足下に落ちるのを…</color>",
  ui_story_5084_50841301_3_dialog_content = "真理は救いの道を歩み続けたいようね。\nそして――その代行人は私こそふさわしい。",
  ui_story_5084_50841301_4_dialog_content = "災典、行くわよ――！",
  ui_story_5084_50841301_5_dialog_content = "…",
  ui_story_5084_50841301_6_dialog_content = "…？それは…何だ？",
  ui_story_5084_50841301_7_dialog_content = "未来を予言する教典は、あなたに未来の光景を見せた。\nでも、あなたにはそれを御する力がない――まるで歩き始めたばかりの赤子のようね。",
  ui_story_5084_50841301_8_dialog_content = "原始の河に洗われた災典はすべてを知っている…\nそして、この災典に…不可能はない。",
  ui_story_5084_50841301_9_dialog_content = "「新しい章」はすでに示された――そのページをめくるのはこの私よ！",
  ui_story_5084_50841301_10_dialog_content = "災典がどうやってあなたの生と死、そして跪き罪を悔いる姿を見せるのか、\nその目で見てみたくはない？",
  ui_story_5084_50841301_11_dialog_content = "…！",
  ui_story_5084_50841301_12_dialog_content = "ポルフィリオと取引をした者たちも、よく聞きなさい。",
  ui_story_5084_50841301_13_dialog_content = "真理結社十二大家序列三の当主、ポルフィリオは――",
  ui_story_5084_50841301_14_dialog_content = "赤い月が空にかかりし時、血に魅入られ、\n大勢の信徒を殺害してその鮮血を食らい、家宝の金のキセルで死徒を操った。",
  ui_story_5084_50841301_15_dialog_content = "真理結社の廃位となった第13代指導者と手を組み、\n邪神をワラーキ村に引き入れ、信者を虐殺――",
  ui_story_5084_50841301_16_dialog_content = "あの廃位となった子どものことか…？",
  ui_story_5084_50841301_17_dialog_content = "第13代指導者は、かつて暗面にて真理の主の降臨の地を探し求め…",
  ui_story_5084_50841301_18_dialog_content = "「邪神」を村に引き入れ、信者を殺害し、\n真理の主の降臨を迎える儀式を妨害した。",
  ui_story_5084_50841301_19_dialog_content = "デービー・ポルフィリオはその虐殺の機に乗じ、\n大量の信者の血を食した。",
  ui_story_5084_50841301_20_dialog_content = "これだけの重罪を犯した者に、真理結社の指導者になる資格が、\n当主の長になる資格があると？",
  ui_story_5084_50841301_21_dialog_content = "…",
  ui_story_5084_50841301_22_dialog_content = "すべて作り話だ！",
  ui_story_5084_50841301_23_dialog_content = "<color=#FFB400>ワラーキの指輪</color>の前で、\nあなたの<color=#FFB400>本性</color>を見せなさい！",
  ui_story_5084_50841301_24_dialog_content = "――！",
  ui_story_5084_50841301_25_dialog_content = "わ、私は…第13代長と手を結べば、聖徒の鮮血を飲み、\n力を高められると思ったのだ。",
  ui_story_5084_50841301_26_dialog_content = "他の当主たちは真理の主の祝福を受け、\n他の血でも満足できるようになった。",
  ui_story_5084_50841301_27_dialog_content = "私だけが…人の血への渇望がますます強くなり、\n今やこの宙に浮かぶ血瓶がないと生きられないまでになってしまった。",
  ui_story_5084_50841301_28_dialog_content = "第13代長はあなたと取引したなんて思っていなかったわ。\n分かっていないのね。",
  ui_story_5084_50841301_29_dialog_content = "あなたを殺すのと万物を殺すのに何の違いがあるのかしら？\n第13代長に利用されただけよ。",
  ui_story_5084_50841301_30_dialog_content = "日蝕に投じ、<color=#FFB400>ファントム</color>の1人となるような<color=#FFB400>長</color>を…\nあなたごときが推し量れるとでも？",
  ui_story_5084_50841301_31_dialog_content = "だ、黙れ――！",
  ui_story_5084_50841301_32_dialog_content = "貴様…ビクトリア・ワラーキ…！\n指輪の力で私を操ったのか！？",
  ui_story_5084_50841301_33_dialog_content = "いや、違う…ワラーキの指輪にそんな力はないはずだ。",
  ui_story_5084_50841301_34_dialog_content = "私は今この指輪を御している。\nワラーキの先祖たちと共にある。",
  ui_story_5084_50841301_35_dialog_content = "あなたが今相対しているのはワラーキ一族の力――\n我がワラーキ一族の前で罪を認めなさい！",
  ui_story_5084_50841301_36_dialog_content = "ハハッ…アハハハハハ！私が…",
  ui_story_5084_50841301_37_dialog_content = "この私がヴィルヘルムを殺したのだ！",
  ui_story_5084_50841301_38_dialog_content = "だが、それも真理結社のために障害を取り除いたにすぎない！",
  ui_story_5084_50841301_39_dialog_content = "曲がった心を持ち、他人と交わらず孤独に暮らして、兄に背いたワラーキの次男など、\nどうして真理結社の指導者になれようか！",
  ui_story_5084_50841301_40_dialog_content = "ヴィルヘルムは…誰にも背いていない…！",
  ui_story_5084_50841301_41_dialog_content = "貴様は黙っていろ――！",
  ui_story_5084_50841301_42_dialog_content = "――！",
  ui_story_5084_50841301_43_dialog_content = "教典はワラーキの聖物だ。\nそれを持つ者に力を与え、未来に対する恐怖をぬぐう。",
  ui_story_5084_50841301_44_dialog_content = "私が血を食らい、人を殺めたとしても、\n教典は私を認め、私に力を与えた。",
  ui_story_5084_50841301_45_dialog_content = "真理結社に私に逆らえる者などいない！",
  ui_story_5084_50841301_46_dialog_content = "紅血の教典よ！我にワラーキを粛清する力を与えたまえ！",
  ui_story_5084_50841301_47_dialog_content = "…",
  ui_story_5084_50841301_48_dialog_content = "紅血の教典――！",
  ui_story_5084_50841301_49_dialog_content = "あなたは今もまだワラーキ一族がなぜ真理結社の指導者たり得るのか、\n理解できていないようね。",
  ui_story_5084_50841301_50_dialog_content = "ワラーキは教典の力で人を傷つけたことは一度たりともない。",
  ui_story_5084_50841301_51_dialog_content = "反対に教典に血を捧げ、その血を吸った教典から未来の啓示を得てきたのよ。",
  ui_story_5084_50841301_52_dialog_content = "…？",
  ui_story_5084_50841301_53_dialog_content = "先祖たちも両親も、そしてヴィルヘルム・ワラーキも私も皆、\nそうしてきたの。",
  ui_story_5084_50841301_54_dialog_content = "ワラーキの聖物には歴代家長の意識が残っている…\n彼らの理性も…彼らの狂気もすべて…",
  ui_story_5084_50841301_55_dialog_content = "聖物と契約した者は強大な精神力で憑りついた意識のささやきの干渉を断つ。\nそうしてようやく真理の境地に到達し…",
  ui_story_5084_50841301_56_dialog_content = "さらなる高みから真理の主の啓示を解読するのよ！",
  ui_story_5084_50841301_57_dialog_content = "貴様…いったいどんな啓示を受けたのだ？",
  ui_story_5084_50841301_58_dialog_content = "…",
  ui_story_5084_50841301_59_dialog_content = "な、何をする…！？",
  ui_story_5084_50841301_60_dialog_content = "当主会談でのこと、忘れたのかしら？",
  ui_story_5084_50841301_61_dialog_content = "どんな啓示を受けたというのだ？",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>門派を粛清せよ。</color>",
  ui_story_5084_50841301_63_dialog_content = "貴様――！！",
  ui_story_5084_50841301_64_dialog_content = "真理の信徒たちよ、共に唱えましょう！",
  ui_story_5084_50841301_65_dialog_content = "ネイルス、この命をもって共に唱えます！",
  ui_story_5084_50841301_66_dialog_content = "メイと「ベビーちゃん」、共に唱えます！",
  ui_story_5084_50841301_67_dialog_content = "信徒ファウスト、ビクトリア様と共に唱えます！",
  ui_story_5084_50841301_68_dialog_content = "デービー、負けを認めよう…",
  ui_story_5084_50841301_69_dialog_content = "怖気づいたか？\n真理結社はポルフィリオの当主が治めるべきだ！",
  ui_story_5084_50841301_70_dialog_content = "…失礼する。",
  ui_story_5084_50841301_71_dialog_content = "誓いを忘れ、私を裏切るか！！",
  ui_story_5084_50841301_72_dialog_content = "よしてちょうだい。私たちの取り引きは赤い月が空にかかる時までだったはず。\nまったく…賭ける相手を間違えたわ。ハハハ…せいぜい鮮血をじっくり味わうのね。",
  ui_story_5084_50841301_73_dialog_content = "死徒よ――！",
  ui_story_5084_50841301_74_dialog_content = "真理結社の当主の皆さんにも、立ち合っていただくわ――",
  ui_story_5084_50841301_75_dialog_content = "…",
  ui_story_5084_50841301_76_dialog_content = "信者の血脈に流れる真理の霊魂たちよ、立ち上がれ！",
  ui_story_5084_50841301_77_dialog_content = "共に真理の声を聞きなさい！",
  ui_story_5084_50841301_78_dialog_content = "私と共に流れと波紋を成し、\n虚しき空を破って、ここに集まるのよ！",
  ui_story_5084_50841301_79_dialog_content = "私こそは真理の主の握りし呪符、聖地にて主の降臨を待つ。",
  ui_story_5084_50841301_80_dialog_content = "私は光を迎える者、闇の奏者！\n永遠の生の境地で死せし星を啓くの！",
  ui_story_5084_50841301_81_dialog_content = "聖なる真理の主よ、啓示をこのワラーキの血に流したまえ。\n私に神の国を啓く力を与えたまえ！",
  ui_story_5084_50841301_82_dialog_content = "「聖血」が固まってきた…受難者よ、告解するのです！",
  ui_story_5084_50841301_83_dialog_content = "つづら藤がよみがえったよ。真理の主よ、メイにどうかご降臨を！",
  ui_story_5084_50841301_84_dialog_content = "これこそ真の悪夢だ、僕が相手をしてやろう！\n古き力を解放する！",
  ui_story_5084_50841301_85_dialog_content = "原始の河に架かる橋、宇宙の真理を貫くナビゲーター、\nどうか私たちに力を貸してちょうだい！",
  ui_story_5084_50841301_86_dialog_content = "橋を架ける…？真理を貫く…？",
  ui_story_5084_50841301_87_dialog_content = "とにかく…力を貸すよ！",
  ui_story_5084_50841301_88_dialog_content = "主があなたの捧げた物を目にする時、契約は成される。\nあなたは私と共に神の降臨を待つのよ。",
  ui_story_5084_50841302_1_dialog_content = "同じ血の一族…汚れた種族…\n生まれながらにして呪われた種族…",
  ui_story_5084_50841302_2_dialog_content = "なぜ…同じ種族でありながら、ワラーキだけがその座に居座り続けるのだ…",
  ui_story_5084_50841302_3_dialog_content = "その問いを発した時、答えはもう目の前にあったはずよ。",
  ui_story_5084_50841302_4_dialog_content = "…ワラーキ…",
  ui_story_5084_50841302_5_dialog_content = "血を好み、寿命が長く、呪われた血の一族は、\n「力を得ると同時に代償を払わなければならない」…",
  ui_story_5084_50841302_6_dialog_content = "その考えは生まれた時からずっと私に付きまとい、\n私を作り上げてきた。",
  ui_story_5084_50841302_7_dialog_content = "けれど、ようやく真理を悟ったわ。私の経験してきたことはすべて代償ではない。\n力を得る者として受け入れた贈り物であり、導きだったのよ。",
  ui_story_5084_50841302_8_dialog_content = "真理の主は血の一族を選び、変革を導く力をお与えになった。\n時代を切り拓く機会をお与えになったのよ。",
  ui_story_5084_50841302_9_dialog_content = "暗鬼や旧文明の兵器は、確かに邪神かもしれないわね。\nそのうちのどれをとっても、光霊の存亡を揺るがすものだもの。",
  ui_story_5084_50841302_10_dialog_content = "けれど光霊の中にも、\nあなたのように主を冒とくする邪悪な者が大勢いるのよ。",
  ui_story_5084_50841302_11_dialog_content = "ワラーキ村を出れば、そこには水の流れや星の運行がある…",
  ui_story_5084_50841302_12_dialog_content = "アイオリアというこの「加護」を受ける孤独な星が\n主の目にはどう映っているのか、考えをめぐらすこともできる…",
  ui_story_5084_50841302_13_dialog_content = "でもあなたには、歴史の隙間から見れば、\n星の滅亡なんてありきたりだってことも永遠に分からないのね。",
  ui_story_5084_50841302_14_dialog_content = "光霊が再び強大な破壊の力と対峙する時、\n主に選ばれたワラーキだけがアイオリアの滅亡を止められる。",
  ui_story_5084_50841302_15_dialog_content = "未知の恐怖に立ち向かい、今をはるかに超える位格でそれを退けられるかどうかは、\n力を得るために大前提となる素質よ。",
  ui_story_5084_50841302_16_dialog_content = "デービー・ポルフィリオ、あなたは血の一族として生まれ、その栄誉を受けながら、\n真理を悟ることができなかった。ならば主から賜った力は返すべきね。",
  ui_story_5084_50841302_17_dialog_content = "悟りも真理の主の選択も関係ない…血の一族が認めるのはワラーキのみ…",
  ui_story_5084_50841302_18_dialog_content = "ポルフィリオはもともとワラーキの後裔だ…",
  ui_story_5084_50841302_19_dialog_content = "だが我が家の先人たちはワラーキから迫害を受け、その貴き名を奪われた…\n私から主に認められる機会を奪った…",
  ui_story_5084_50841302_20_dialog_content = "何百年経っても、血の一族は変わらない。\n貴様の悟りなど何の訳にも立たない…",
  ui_story_5084_50841302_21_dialog_content = "貴様が…ワラーキが…血の一族の宿命から逃れられると思ったら大間違いだ…",
  ui_story_5084_50841302_22_dialog_content = "フフッ…フフフ…アハハハハ…",
  ui_story_5084_50841302_23_dialog_content = "…",
  ui_story_5084_50841302_24_dialog_content = "ワラーキのお嬢様、いや…ビクトリア様…",
  ui_story_5084_50841302_25_dialog_content = "外の世界を遊歴なさる中で、本当に主の啓示を受けたのですか…？",
  ui_story_5084_50841302_26_dialog_content = "我が家は太古の遺物を多く有していますが――",
  ui_story_5084_50841302_27_dialog_content = "そのささやきが私を縛り付けていることを、\n自分に真理の主から力を賜る資格があるかどうかを、どう判断すればいいのですか？",
  ui_story_5084_50841302_28_dialog_content = "真理結社は血の一族の卓越した精神力を強みとしてきた。\n太古の遺物と共鳴する力は主からの賜り物よ。",
  ui_story_5084_50841302_29_dialog_content = "でも長い時が経ち、当主たちが権力争いに明け暮れ、無為に贅沢をむさぼってきたせいで、\nその血脈には異物が混ざり、遺物を通して後代に受け継がれた。",
  ui_story_5084_50841302_30_dialog_content = "私も共鳴してみて分かったわ。多くの遺物の中には、\n人に狂気と苦痛を与える叫び以外、何もないことを。",
  ui_story_5084_50841302_31_dialog_content = "光霊と器物との間に生じる縛りの本質は恐れ。",
  ui_story_5084_50841302_32_dialog_content = "ワラーキを受け継ぐ者は毎晩恐怖に襲われ、当てもなく歩き回り、\n服に隠された肉体と心は傷だらけになっていく…",
  ui_story_5084_50841302_33_dialog_content = "だから私は典籍や文書を読みあさり、\n理性と知識で私を狂わせようとする遺物の力を抑え込んでいる。",
  ui_story_5084_50841302_34_dialog_content = "そうするうちに徐々にささやきの霧が晴れ、\n真理の主の懐に至った。",
  ui_story_5084_50841302_35_dialog_content = "問いかけと探究を止めてはいけないわ。\nささやきを力で抑え、恐怖を与えて屈服させる。それこそが正しい道よ。",
  ui_story_5084_50841302_36_dialog_content = "…ビクトリア様の教えをしかと胸に刻みます。",
  ui_story_5084_50841302_37_dialog_content = "でも、これは血の一族だけの特権でないことも知っておくべきよ…",
  ui_story_5084_50841302_38_dialog_content = "外の世界を巡り歩き、私は知った。血の一族ではない光霊にも、\n特殊な器物を引き付ける神秘の力を持つ者たちがいる。",
  ui_story_5084_50841302_39_dialog_content = "あるいは車輪や眼球を…",
  ui_story_5084_50841302_40_dialog_content = "あるいは植物のつるや紙切れを…",
  ui_story_5084_50841302_41_dialog_content = "またあるいは動物や箱を…",
  ui_story_5084_50841302_42_dialog_content = "操る者によって、強大な意識の潜在力を引き出すことができる。",
  ui_story_5084_50841302_43_dialog_content = "あなたたちはまだ凝固して形を成し、\n暗鬼を倒すことのできる血液を見たことがないでしょう…",
  ui_story_5084_50841302_44_dialog_content = "…うちの門徒が街でそのような信者を見たと言っておりました。",
  ui_story_5084_50841302_45_dialog_content = "…",
  ui_story_5084_50841302_46_dialog_content = "そうした神秘の力を持つ信者は世界中に存在するわ。真理結社は光霊に歩み寄り、\n真理を広め、それらの力を結社に取り込むべきよ。",
  ui_story_5084_50841302_47_dialog_content = "啓示を受けし者はすでに現れている。ただ彼らは啓示を受けたことの意味を知らぬまま、\n世界各地の片隅で人知れず暮らしているだけ。",
  ui_story_5084_50841302_48_dialog_content = "私たち血の一族はそうした啓示を結集し、共に真理の主に声を届けなければならないの。\n主をお迎えし、光霊の未来を導いていただかなければ。",
  ui_story_5084_50841302_49_dialog_content = "そういうことであれば、私はワラーキ村を離れることに賛成です。\n光霊に歩み寄り、真理を広めます…",
  ui_story_5084_50841302_50_dialog_content = "広く信者を集め、力を結集させます…",
  ui_story_5084_50841302_51_dialog_content = "ですが、どうすれば真理の主に声を届けられるのですか？",
  ui_story_5084_50841302_52_dialog_content = "もし真理結社に、聖物とつながることで原始の河に到達し、\nさらには聖物を動かす力を持つナビゲーターがいると言ったら…",
  ui_story_5084_50841302_53_dialog_content = "あなたたちは真理結社の未来に希望を抱いてくれるかしら？",
  ui_story_5084_50841302_54_dialog_content = "ナ、ナビゲーターですか…？",
  ui_story_5084_50841302_55_dialog_content = "あ、あのぉ、僕は…真理結社に入った覚えはないんだけど…",
  ui_story_5084_50841302_56_dialog_content = "空の末裔、燭台をこっちへ。",
  ui_story_5084_50841302_57_dialog_content = "…え？でも、こんなにたくさんの人がいちゃ…",
  ui_story_5084_50841302_58_dialog_content = "渡してちょうだい。",
  ui_story_5084_50841302_59_dialog_content = "…",
  ui_story_5084_50841302_60_dialog_content = "彼は…空の末裔よ。真理結社の盟友なの。",
  ui_story_5084_50841302_61_dialog_content = "あ…ど、どうも…",
  ui_story_5084_50841302_62_dialog_content = "空の末裔ですと…？聞いたことがあります。\n巨像を操縦し、感知の力を持つという種族ですよね？",
  ui_story_5084_50841302_63_dialog_content = "空の末裔殿、先程からずっとここにいらしたのですか…？",
  ui_story_5084_50841302_64_dialog_content = "ええと、その…正確には今だけじゃなく、前から色々な時にいたんですけど、\n事情があって姿は見せなかったんです。",
  ui_story_5084_50841302_65_dialog_content = "感知の力とは…血の一族の共鳴と同じようなものでしょうか…？",
  ui_story_5084_50841302_66_dialog_content = "違うわ。",
  ui_story_5084_50841302_67_dialog_content = "血の一族の共鳴は、その血と聖物の間に生まれるもの。",
  ui_story_5084_50841302_68_dialog_content = "一方、空の末裔の感知は血の一族の上位にあるものを動かす力…\nそして、その上位の力こそ光霊の力の基礎となっているものよ…",
  ui_story_5084_50841302_69_dialog_content = "…原始の河…ですか？",
  ui_story_5084_50841302_70_dialog_content = "なんと！ビクトリア様、まさか…太古の書を手になさったのですか？",
  ui_story_5084_50841302_71_dialog_content = "いいえ。太古の書は今だ誰も手にしたことはないわ。\nどこにあるのかも分かっていない…",
  ui_story_5084_50841302_72_dialog_content = "ただ…太古の書を動かす原始の河には、行った者がいるようね。",
  ui_story_5084_50841302_73_dialog_content = "私はその場所を探しに行くわ。\nだから、あなたたちにはこれからのワラーキ村を頼みたいの。",
  ui_story_5084_50841302_74_dialog_content = "指導者の教えを守り、あなた様の伝えた真理を悟るよう努めます。",
  ui_story_5084_50841302_75_dialog_content = "…ほ、本当なのか…？原始の河に行った者がいると…？",
  ui_story_5084_50841302_76_dialog_content = "クラビス・アブラハム。あなたはあの時、\nヴィルヘルムを殺したことを話すべきかどうか迷っていたわね。",
  ui_story_5084_50841302_77_dialog_content = "…",
  ui_story_5084_50841302_78_dialog_content = "クラビス、今日は借りたい物があって来たのだ。",
  ui_story_5084_50841302_79_dialog_content = "…ファリアか？",
  ui_story_5084_50841302_80_dialog_content = "そうだ。",
  ui_story_5084_50841302_81_dialog_content = "紅血の教典を持ち出すつもりか！？",
  ui_story_5084_50841302_82_dialog_content = "紅血の教典を墓の中に入れたままにしておけば、\n遅かれ早かれ、吸血鬼の手に落ちてしまう。",
  ui_story_5084_50841302_83_dialog_content = "だが奴には…持ち出す資格はないだろう？",
  ui_story_5084_50841302_84_dialog_content = "それはワラーキ出身の歴代指導者が当主らにそう思い込ませてきたからだ。",
  ui_story_5084_50841302_85_dialog_content = "だがビクトリアはまだ、己の血脈の中にいかに重要な力が秘められているかを知らない。",
  ui_story_5084_50841302_86_dialog_content = "それに私の過去の行いがワラーキの神聖さをけがしてしまった。\n当主らはもうずいぶんと前からこの座を狙っている。",
  ui_story_5084_50841302_87_dialog_content = "私がいなくなれば、奴らはビクトリアを見逃しはしないだろう。",
  ui_story_5084_50841302_88_dialog_content = "ポルフィリオが指導者となった真理結社は必ずや世界に大きな災厄をもたらす。",
  ui_story_5084_50841302_89_dialog_content = "ヴィルヘルム、それは…",
  ui_story_5084_50841302_90_dialog_content = "ワラーキの墓所が当主らの前にその扉を開くのは、\n聖鳴祭の夜、赤い月が藤の蔓を照らす時のみだ。",
  ui_story_5084_50841302_91_dialog_content = "だがその時まで待っていては、全てが手遅れになってしまう。\n私たちは以前、万門の鍵――黒箱ファリアの可能性について、話し合ったことがあったな。",
  ui_story_5084_50841302_92_dialog_content = "兄は来るべき時が来た時、私が教典を取り出すことができるよう、\n親友たる君に預けたのだろう。",
  ui_story_5084_50841302_93_dialog_content = "…",
  ui_story_5084_50841302_94_dialog_content = "クラビス、なぜ黙っている？",
  ui_story_5084_50841302_95_dialog_content = "ヴィルヘルム、ファリアで墓を開けられるとしても…\n当主たちの立会いなしに教典を持ち出せば、契約に背くことになる。",
  ui_story_5084_50841302_96_dialog_content = "承知のうえだ。",
  ui_story_5084_50841302_97_dialog_content = "それだけではない。契約に背く決断をわざわざ私に話すとは…\nヴィルヘルム、いったい何を考えている？",
  ui_story_5084_50841302_98_dialog_content = "ビクトリアは今年いくつになる？",
  ui_story_5084_50841302_99_dialog_content = "なぜ、それを聞く？",
  ui_story_5084_50841302_100_dialog_content = "君はもう何年もビクトリアの世話をしてきた。\n野心に燃え、自分の事しか見えていなかったかつての青年も…",
  ui_story_5084_50841302_101_dialog_content = "今や他人を想い、他人のために動くようになったのだな。",
  ui_story_5084_50841302_102_dialog_content = "ふっ…ビクトリアと私が普段どう暮らしているかを見たら、\nその言葉は出てこないだろうな。",
  ui_story_5084_50841302_103_dialog_content = "私がなぜ旧市街地に移り住んだと思う？",
  ui_story_5084_50841302_104_dialog_content = "聞くまでもない、カロンのためだ。",
  ui_story_5084_50841302_105_dialog_content = "その通りだ、ヴィルヘルム。私も妻も真理結社にはもう関心がない。\nカロンを真理結社に入れるつもりも毛頭ない。",
  ui_story_5084_50841302_106_dialog_content = "怖気づいたか。",
  ui_story_5084_50841302_107_dialog_content = "いいや、それは違う。\n私はカロンのために苦難の道へと踏み出したのだ。",
  ui_story_5084_50841302_108_dialog_content = "ならば、カロンとその母の未来に影を落とさないためにも、\nファリアを私に渡すべきだと言ったらどうする？",
  ui_story_5084_50841302_109_dialog_content = "…",
  ui_story_5084_50841302_110_dialog_content = "ワラーキが教典を手にしてこそ、真理結社に活路が拓ける。\n私が受け継ぐ多くの記憶の中でも、教典を手にしたワラーキのみが変革を成し遂げた！",
  ui_story_5084_50841302_111_dialog_content = "野心に燃えるあの頃に戻ったようではないか…",
  ui_story_5084_50841302_112_dialog_content = "君をむしばもうとする狂気のささやきだけでは、\n罰は十分でなかったというのか？",
  ui_story_5084_50841302_113_dialog_content = "その通りだ、私には野心がある！だが、それがどうした！？",
  ui_story_5084_50841302_114_dialog_content = "抜きんでた才に恵まれ、強大な力を有する兄に負けた弟は、\n影に潜み、己を哀れんで過ごせと！？フン、私はそのような生き方はしない！",
  ui_story_5084_50841302_115_dialog_content = "…",
  ui_story_5084_50841302_116_dialog_content = "…すまない、クラビス。そういうことが言いたかったわけではない。",
  ui_story_5084_50841302_117_dialog_content = "ただ、今度は己のためではない、ビクトリアのためだ。",
  ui_story_5084_50841302_118_dialog_content = "だとしても、無理だ。ヴィルヘルム…",
  ui_story_5084_50841302_119_dialog_content = "いったい何を恐れている？クラビス、まさか異変が起こり始めていることに気づいていないとでも？",
  ui_story_5084_50841302_120_dialog_content = "ポルフィリオと当主たちは、ワラーキの一族から分家して以来、戒律を守らなくなった…",
  ui_story_5084_50841302_121_dialog_content = "君独りが守ったところで、何の意味がある？",
  ui_story_5084_50841302_122_dialog_content = "血の一族の戒律は檻だ！今の真理結社は、君にとっても、\n私にとっても、村の人々にとっても災いでしかないのだ！",
  ui_story_5084_50841302_123_dialog_content = "血の一族は生来そういうものだ…\n君は我々よりも運が良かったにすぎない。",
  ui_story_5084_50841302_124_dialog_content = "…君はいつから運命に屈するようになったのだ？",
  ui_story_5084_50841302_125_dialog_content = "そんな言い草はよせ、ヴィルヘルム。\n私は単に事実を否定できないだけだよ…",
  ui_story_5084_50841302_126_dialog_content = "あの鍵は、君を傷つけるだけだ。",
  ui_story_5084_50841302_127_dialog_content = "…手助けする気はないということか？",
  ui_story_5084_50841302_128_dialog_content = "…",
  ui_story_5084_50841302_129_dialog_content = "分かった、気にするな。他の方法を考えることにする。",
  ui_story_5084_50841302_130_dialog_content = "私は…ファリアをヴィルヘルムに渡さなかった…\nあの時は本当に彼を殺そうなどとは考えていなかったのだ…",
  ui_story_5084_50841302_131_dialog_content = "聖鳴祭の夜、ヴィルヘルムが他の当主たちに殺されるのをただ見ていれば…\nそれで済むと思っていた…",
  ui_story_5084_50841302_132_dialog_content = "…",
  ui_story_5084_50841302_133_dialog_content = "<size=45>ああ！！</size>",
  ui_story_5084_50841302_134_dialog_content = "フフフッ…フハハハハッ…",
  ui_story_5084_50841302_135_dialog_content = "クラビス…",
  ui_story_5084_50841302_136_dialog_content = "すまない…ヴィルヘルム…",
  ui_story_5084_50841302_137_dialog_content = "私はカロンに…汚れなき未来を残してやりたいのだ…",
  ui_story_5084_50841302_138_dialog_content = "君にもビクトリアがいる。分かってくれ…",
  ui_story_5084_50841302_139_dialog_content = "ビクトリア…",
  ui_story_5084_50841302_140_dialog_content = "ふっ…",
  ui_story_5084_50841302_141_dialog_content = "すまない…！",
  ui_story_5084_50841302_142_dialog_content = "ハハハハハ…クラビス。\n君には決心がつかないだろうと思っていたのにな。",
  ui_story_5084_50841302_143_dialog_content = "ヴィルヘルムよ、ヴィルヘルム。\nその子供だましの手品であの娘を隠せば、何か変えられると思ったか…",
  ui_story_5084_50841302_144_dialog_content = "おお、かわいそうなヴィルヘルム。\n誰にも認められず、故郷で犬死にするとはな。",
  ui_story_5084_50841302_145_dialog_content = "…",
  ui_story_5084_50841302_146_dialog_content = "フン。ワラーキの指輪など継承したところで、何の意味もない。",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>デービー・ポルフィリオは背後にあった血瓶を揺らし、\n生涯で最大の力をその指に込めた</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>ワラーキの指輪がポルフィリオの指の間で砕け散り、\n銀と赤の粉がヴィルヘルムの身体の上に降りかかる</color>",
  ui_story_5084_50841302_149_dialog_content = "何をしているのだ？\n指輪を粉々にしてしまったら、この先…",
  ui_story_5084_50841302_150_dialog_content = "我々には無用の長物だ。\n粉々にしてヴィルヘルムの副葬品にしてやろうではないか。",
  ui_story_5084_50841302_151_dialog_content = "これでもう不安におびえることもない。",
  ui_story_5084_50841302_152_dialog_content = "当主の長としてのワラーキの束縛は、\nもはや過去のもの！",
  ui_story_5084_50841302_153_dialog_content = "ハハハ…デービー、ずいぶんと豪勢な聖鳴祭の晩餐じゃないか！",
  ui_story_5084_50841302_154_dialog_content = "貴様ら…ヴィルヘルムが死んだのだぞ…！",
  ui_story_5084_50841302_155_dialog_content = "いかにも。君のおかげだ。\nさあ、ワラーキの鮮血ともなれば、味わうにも順序を守らねばな。",
  ui_story_5084_50841302_156_dialog_content = "私の後はもちろん、我が最良の友――クラビス。",
  ui_story_5084_50841302_157_dialog_content = "手下どもが満足したら、ヴィルヘルムは君にくれてやろう。",
  ui_story_5084_50841302_158_dialog_content = "親友だったことに免じて、ヴィルヘルムの埋葬を許してやる。",
  ui_story_5084_50841302_159_dialog_content = "死して棺に眠るのは、我々血の一族の伝統だからな。",
  ui_story_5084_50841302_160_dialog_content = "だが、懺悔を忘れないことだ。\n最良の友に刺され死したヴィルヘルムの耳にも聞こえるかもしれんぞ…",
  ui_story_5084_50841302_161_dialog_content = "カロンと妻は、見逃してくれるのだろうな？",
  ui_story_5084_50841302_162_dialog_content = "もちろんだ。だがクラビス、私には解せんのだが…\n手下どもの話では、引っ越すそうではないか。",
  ui_story_5084_50841302_163_dialog_content = "…",
  ui_story_5084_50841302_164_dialog_content = "それでは今後、何か頼みごとをしようにも…\n少々不便な気がするのだがな。",
  ui_story_5084_50841302_165_dialog_content = "デービー、貴様！",
  ui_story_5084_50841302_166_dialog_content = "ハハハハハ！",
  ui_story_5084_50841302_167_dialog_content = "…愚か者が。",
  ui_story_5084_50841302_168_dialog_content = "パンニング、君には人脈があったな。\nビクトリアを見つけ出し、後々の憂いを断つことを忘れないでくれたまえ。",
  ui_story_5084_50841302_169_dialog_content = "私は何てことを…何てことをしてしまったのだ…",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>クラビスはヴィルヘルムを背負い、ワラーキの墓所へとやってきた</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>しかし、墓所を守る藤蔓人はヴィルヘルムの埋葬に同意しなかった</color>",
  ui_story_5084_50841302_172_dialog_content = "万門の鍵――<color=#FFB400>黒箱ファリア</color>よ！",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>声と共に聖物が現われ、何もなかったはずの空間に裂け目ができた――\n「河の流れ」の隙間から、クラビスは墓の中へと入って行った</color>",
  ui_story_5084_50841302_174_dialog_content = "ヴィルヘルム、墓所に着いたぞ…\nここもすでに安全ではないかもしれないが…私は君の側に居られない。",
  ui_story_5084_50841302_175_dialog_content = "ここで永遠の眠りにつき、\n先祖と共に真理の主の懐に抱かれるよう願っているよ。",
  ui_story_5084_50841302_176_dialog_content = "この鍵は、持っていても災いを招くだけだ。",
  ui_story_5084_50841302_177_dialog_content = "私が持っている限り、いつかきっとポルフィリオに見つかってしまう。",
  ui_story_5084_50841302_178_dialog_content = "我らが先祖よ、すべてご覧になっていたのなら、\n孤独な余生の苦しみをもって、この私を罰してください…",
  ui_story_5084_50841302_179_dialog_content = "真理結社も…ワラーキも…私たちは努力しました。\nでも、その運命を変えることはできませんでした。",
  ui_story_5084_50841302_180_dialog_content = "ヴィルヘルムも…血の一族も…\n結局は運命に囚われたまま、生きて行くしかないのでしょうか…",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>声なき墓守が見守る中、クラビスはヴィルヘルムと共にファリアを棺の中に納めた</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>しかしこの時、この万門の鍵が「運命」という扉を開くことになろうとは誰も知る由もなかった</color>",
  ui_story_5084_50841302_183_dialog_content = "言い訳はしない…すべて自ら招いたことだ。",
  ui_story_5084_50841302_184_dialog_content = "裏切りとは…なんと罪深いことを。\nクラビスさん、あなたはすぐにでも真理の主に懺悔すべきです。",
  ui_story_5084_50841302_185_dialog_content = "主の赦しを乞う気はない…\nヴィルヘルムには…合わせる顔もない。",
  ui_story_5084_50841302_186_dialog_content = "…",
  ui_story_5084_50841302_187_dialog_content = "あの場所は、私とあなた以外に知る者はいない。\nそして、ヴィルヘルムはすでに死んでいた。",
  ui_story_5084_50841302_188_dialog_content = "あの日私がワラーキ村を離れようと決めた時、\nあなたはヴィルヘルムではなく、私を訪ねてきたのね。",
  ui_story_5084_50841302_189_dialog_content = "もし村に戻るというなら、すべてを告白するつもりだった。\nだが村を出るというなら…",
  ui_story_5084_50841302_190_dialog_content = "だから、何も言わなかった。",
  ui_story_5084_50841302_191_dialog_content = "あれからというもの、苦しみを感じない日は\n1日たりともなかった…",
  ui_story_5084_50841302_192_dialog_content = "この命はいつでも差し出そう。\nただ私にはやり残したことがあるのだ。",
  ui_story_5084_50841302_193_dialog_content = "…",
  ui_story_5084_50841302_194_dialog_content = "クラビスさん、まだ動けるのですか…",
  ui_story_5084_50841302_195_dialog_content = "カロンと妻はこの件と一切関係ない。\n2人には、汚れなき未来を残してやらねば…",
  ui_story_5084_50841302_196_dialog_content = "ハハハ…だが私のような父親では、\n生きていたところで、カロンは恨むだけだろうがな…",
  ui_story_5084_50841302_197_dialog_content = "この先、いったいどんな未来が待ち受けているのか…\nこれこそ私に対する罰だろう…",
  ui_story_5084_50841302_198_dialog_content = "カロンは確かに…お父さんとあまり仲が良くないって言ってた。",
  ui_story_5084_50841302_199_dialog_content = "…",
  ui_story_5084_50841302_200_dialog_content = "あ、ビクトリア。ロウソクが消えそうだよ…",
  ui_story_5084_50841400_1_dialog_content = "ビクトリア様…こちらを…「万門の鍵」でございます。",
  ui_story_5084_50841400_2_dialog_content = "クラビス様は当時、これをヴィルヘルム様の棺の中に納めました。\nですが今やヴィルヘルム様はどこへ行かれたか知れず、この鍵だけが見つかりました。",
  ui_story_5084_50841400_3_dialog_content = "あれ？この黒い箱って確か…",
  ui_story_5084_50841400_4_dialog_content = "PlayerName…",
  ui_story_5084_50841400_5_dialog_content = "あ、ごめん。この時代のことじゃなかったね。",
  ui_story_5084_50841400_6_dialog_content = "ここを離れられるのですね。ですからこれは――\n真理結社の指導者ビクトリア様にお渡しします。",
  ui_story_5084_50841400_7_dialog_content = "いいえ、黒箱がもたらす影響は誰にも御せはしないわ。\nこれは、置いていきましょう。",
  ui_story_5084_50841400_8_dialog_content = "ただ、誰にも使わせないように、あなたが守っていてちょうだい。\nたとえ相手が私であってもね。すべては主の意志に従うのよ。",
  ui_story_5084_50841400_9_dialog_content = "ビクトリア様、お願いでございます…\nこのように大事なものを私にあずけるなど…お考え直しくださいませんか？",
  ui_story_5084_50841400_10_dialog_content = "黒箱はもともとあなたが保管すべきものでしょう？\n父がクラビスに渡したのはきっと…運命の軌道を見たからだわ。",
  ui_story_5084_50841400_11_dialog_content = "私にこのワラーキの墓所をいつまで守り切れるか…",
  ui_story_5084_50841400_12_dialog_content = "可能ならば、私は当主の座を退き、何の憂いもない1本の蔓となって、\n一心一意に墓を守り、あなた様の再びの訪れをお待ちしたく存じます。",
  ui_story_5084_50841400_13_dialog_content = "秘法で当主たちの「視界」から墓所を消してあげるわ。\nただ…あなたの心には、堅く信じる真理があるのかしら？",
  ui_story_5084_50841400_14_dialog_content = "真理ですか…私は最初から、ただ人の世から離れて生きたかっただけです。\nこの墓所は私には最良の居場所でした。",
  ui_story_5084_50841400_15_dialog_content = "それは誰が真理結社の指導者になろうと関係のないこと――\nもちろん、ビクトリア様の意志を疑っているわけではございません。",
  ui_story_5084_50841400_16_dialog_content = "まだ墓守を続けたいなんて、あなたは自由にはなりたくないの？",
  ui_story_5084_50841400_17_dialog_content = "私にはもう家族はございません。\n世界のどこへ行こうと、孤独なことに変わりはないのです。",
  ui_story_5084_50841400_18_dialog_content = "ならば、ここで安寧を得る権利を与えましょう。",
  ui_story_5084_50841400_19_dialog_content = "あなたはワラーキ家の最も忠実な友人よ。デービー・ポルフィリオに代わって、\n私が留守にしている間、ワラーキ村を管理する資格が十分にある。",
  ui_story_5084_50841400_20_dialog_content = "わ、私が…どんでもありません！",
  ui_story_5084_50841400_21_dialog_content = "でも、ここが最良の「居場所」だというのなら、\nここで新たに家族を探し、未来をつむぐといいわ。",
  ui_story_5084_50841400_22_dialog_content = "あなたの一族は確か、姓から何もかも\n白夜城と関係ある過去はすべて捨てたんだったわね。",
  ui_story_5084_50841400_23_dialog_content = "さあ、好きな姓を選ぶといいわ。\nそれが新たな一族の出発点となるのよ。",
  ui_story_5084_50841400_24_dialog_content = "…承知いたしました、お嬢様。",
  ui_story_5084_50841400_25_dialog_content = "ならば…ダンテスと名乗ることにいたします。",
  ui_story_5084_50841400_26_dialog_content = "今日から私はグレイブ・ダンテスです。",
  ui_story_5084_50841400_27_dialog_content = "（ダンテス…！？この人は…スカーレイの先祖ってこと？）",
  ui_story_5084_50841400_28_dialog_content = "フフ。自分で選んだ運命よ。受け入れ、進み続けなさい。",
  ui_story_5084_50841400_29_dialog_content = "あなたたちの一族はワラーキの忠実な盟友だった。これからもね。\n黒箱ファリアはダンテス家の運命を輝かせることでしょう。",
  ui_story_5084_50841400_30_dialog_content = "分かりました…では、私はこれで失礼いたします。",
  ui_story_5084_50841400_31_dialog_content = "ふぅ…これで全部終わったってこと？",
  ui_story_5084_50841400_32_dialog_content = "ここの聖鳴祭が終わって、ワールプール町に戻った後は、\nもう1つの聖鳴祭が待っているよ。",
  ui_story_5084_50841400_33_dialog_content = "うーん…ってことは、聖鳴祭を3回も過ごすってことじゃん！\nなんだか急にお姉ちゃんが恋しくなってきた…",
  ui_story_5084_50841400_34_dialog_content = "あ！ロウソクが…今度こそ本当に消えそうだ。",
  ui_story_5084_50841400_35_dialog_content = "…",
  ui_story_5084_50841400_36_dialog_content = "（ビクトリアが遠くを眺めてる…ヴィルヘルムさんを待ってるのかな…）",
  ui_story_5084_50841400_37_dialog_content = "行きましょう。",
  ui_story_5084_50841400_38_dialog_content = "ビクトリア様、今2冊の教典をお持ちですが、\n2冊ともお持ち帰りになるのですか？",
  ui_story_5084_50841400_39_dialog_content = "帰りの道で、教典はあるべき所へ行くわ。\nさあ、準備はいいかしら？",
  ui_story_5084_50841400_40_dialog_content = "火が消えた…あれ？古い教典はまだあるんだね。",
  ui_story_5084_50841400_41_dialog_content = "この教典が私たちをここへ導き、新しいそれと出会わせてくれた。\nなら、今度は私が運命に返してあげる番ね。",
  ui_story_5084_50841400_42_dialog_content = "え？",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>帰途を包む暗闇の中で、時の流れにわずかな「隙間」が生じ、\nその「隙間」から河のような神秘的な流れがかすかに姿をみせた</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>ビクトリアが手を放すと、長い間彼女と共にあった教典は\nその神秘の流れの中へと落ち、そのまま流れていく</color>",
  ui_story_5084_50841400_45_dialog_content = "教典は…どこへ行ったの…？",
  ui_story_5084_50841400_46_dialog_content = "シーッ。流れをよく見るの。真理は、そこにある。",
  ui_story_5084_50841400_47_dialog_content = "私たちは皆、この流れの下に沈む一粒の砂にすぎない。\nそしていつか真理の主の懐へと帰って行くのよ。",
  ui_story_5084_50841400_48_dialog_content = "さあ、行きなさい。「あなた」がすべての運命と出会えるよう願っているわ。",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>教典は流れに従い、「未来の見知らぬ者たち」のもとから去った</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>教典は原始の河を静かに流れていく。水面が揺れ、波紋ができ、\nその下には無数の光が現れては過去と未来を映し出す</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>風もない中、教典のページはおのずと開かれ、教典の起こした乱れが\n一文字もなかった真っ白なページに文字となって浮かび上がる</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>こうして運命が刻まれて行く――</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>教典の姿が出来事の中に現れ、その存在が知られていく。\n河の流れの下にある運命に教典が関わっていく</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>「どこからともなく現れた教典を拾いあげたヴィルヘルムは啓示の存在を感じ、\n深い眠りに就いたビクトリアに渡すことを決めた。」</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>「若きビクトリアは何も記されていない教典のページをめくると、\n初めて真理の予言を耳にした。」</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>教典は流れに従い、さらに先へと漂っていく。河を流れる時間に始まりも終わりもなく、\nただ永遠に止まることのない輪となって流れてゆく</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>「ビクトリアが手を放すと、長い間彼女と共にあった教典は\nその神秘の流れの中へと落ち、そのまま流れていく。」</color>",
  ui_story_5084_50841400_58_dialog_content = "…旅人も皆、元の時へと戻っていった。\n私も己のやるべきことを終わらせるとしよう。",
  ui_story_5084_50841400_59_dialog_content = "1918年のビクトリアよ。お前はまだ真理を探す途中にある。\n何も知らず、何も分からず、全てが靄に包まれて見えるだろう…",
  ui_story_5084_50841400_60_dialog_content = "だが、心配するな。時の流れをただ静かに待っていればいい。",
  ui_story_5084_50841400_61_dialog_content = "君も私と同様、長い旅路の末に啓示を受けるだろう。",
  ui_story_5084_50841400_62_dialog_content = "その時、君は彼らを連れて、この時に戻ってくる。\n私たちは、また会える。",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>ヴィルヘルムは深い眠りに就いたビクトリアをワールプール町から墓所に送り、\n古い教典をその手に持たせた</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>そして来たりし時に眠っていた棺に横たわり、過去へと思いをはせた</color>",
  ui_story_5084_50841400_65_dialog_content = "私たちが初めて会ったのは、死期を悟った兄が幼い君を私に託した時だった。",
  ui_story_5084_50841400_66_dialog_content = "私に指導者になれと？",
  ui_story_5084_50841400_67_dialog_content = "そうだ。指導者となり、ビクトリアを守ってほしい。",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>ビクトリアは両親の傍らに立ち、これから死にゆく者が、\nなぜ満足げな表情を浮かんでいるか解せずにいた</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>一方、ありとあらゆる屈辱を受け尽くしたヴィルヘルム・ワラーキには、\nすでに心を深く痛めているビクトリアを血の一族の宿命に引き込むことはどうしてもできなかった</color>",
  ui_story_5084_50841400_70_dialog_content = "それ以上何を言っても無駄です。承知できません。",
  ui_story_5084_50841400_71_dialog_content = "…",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>しかし葬儀の当日、ヴィルヘルムは信者の服をまとい、\n兄夫婦の棺がワラーキ村を離れるのを見送っていた</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>そしてワラーキの墓所の入り口で、当主らがビクトリアに「挨拶」するのを聞いた</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>暴雨、雷…ヴィルヘルムは自分の心の奥底から、\n世界を切り裂き、粉々にせんとする力が湧き出るかのように感じた</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>そして墓所の中心へと走っていった。ただ当主たちの前で、\n己を呑み込んでしまうであろうワラーキの指輪をはめるためだけに…</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>己と共に永遠の真理の道を歩んでいくことになる少女を守るためだけに</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>2人で過ごす日々は決して楽なものではなかった。だがヴィルヘルムは何としても、\nこの時真理結社を拒絶していたビクトリアを強大な存在に育てなけばならなかった</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>自身も各地を回り、自分とビクトリアの2人を守る方法を探し続けた</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>そして、自分が死んだ時のことを想った…</color>",
  ui_story_5084_50841400_80_dialog_content = "クラビス…",
  ui_story_5084_50841400_81_dialog_content = "君にもビクトリアがいる。分かってくれ…",
  ui_story_5084_50841400_82_dialog_content = "ビクトリア…",
  ui_story_5084_50841400_83_dialog_content = "ふっ…",
  ui_story_5084_50841400_84_dialog_content = "（血の一族にとって、死は一種の祝福かもしれない）",
  ui_story_5084_50841400_85_dialog_content = "（今の私はもう、誰かの裏切りに心を痛めることもない…）",
  ui_story_5084_50841400_86_dialog_content = "（クラビス、分かっている…だが、これからビクトリアはどうする？）",
  ui_story_5084_50841400_87_dialog_content = "（私は本当に知り得た真理を全て伝えてやれるだろうか）",
  ui_story_5084_50841400_88_dialog_content = "（ビクトリアは村を離れたあの日、真理を探究する道を歩むと、\nその決心を私に伝えようとしていたのだろうか？）",
  ui_story_5084_50841400_89_dialog_content = "（…）",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>ヴィルヘルムの真理に対する問いかけは止むことなく、\nその思考は透き通った河の流れに溶け込んでいった</color>",
  ui_story_5084_50841400_91_dialog_content = "…どういうことだ？私は確か教会で…\nもう死んでいるはずだが…",
  ui_story_5084_50841400_92_dialog_content = "ここは…",
  ui_story_5084_50841400_93_dialog_content = "死後の国か…？それとも真理の主の殿堂だろうか？",
  ui_story_5084_50841400_94_dialog_content = "この河はいったい…？",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>止まることのない河の流れ――ヴィルヘルムは身動き一つせず、流れに身を任せていた。\nその頭の中には世界のありとあらゆる情報が流れ込んでくる</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>10年、100年…いったいどれだけの年月が流れたのだろうか…</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>アイオリアは闇に包まれたかと思うと、また明るさを取り戻し、\n光霊と暗鬼の争いは止むことなく続いていく</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>ただ1人ヴィルヘルムだけが、河の流れに漂っていた</color>",
  ui_story_5084_50841400_99_dialog_content = "おや…あれは私か？",
  ui_story_5084_50841400_100_dialog_content = "望む望まずに関わらず、これが運命だ。私の代わりにこの真新しい教典を\n棺の中に納めておいてくれ。いつか必ずあの子の役に立つ。",
  ui_story_5084_50841400_101_dialog_content = "はい、ヴィルヘルム様。",
  ui_story_5084_50841400_102_dialog_content = "あれは、あの時の…",
  ui_story_5084_50841400_103_dialog_content = "そう気を落とすことはない。\n君も家庭を持てばいいだけのことだ。",
  ui_story_5084_50841400_104_dialog_content = "家庭、子ども？興味はないよ。",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>幾人ものヴィルヘルムが幾つもの時空に現れ、また互いに重なり合っていく。\n錯綜と混乱が続き、ようやく自分以外の存在が現れた</color>",
  ui_story_5084_50841400_106_dialog_content = "私ではなく、真理の主の加護のおかげよ。",
  ui_story_5084_50841400_107_dialog_content = "ここはどこですか?",
  ui_story_5084_50841400_108_dialog_content = "<color=#FFB400>原始の河</color>は時間に左右されず、空間の縛りを受けないの。\n外の世界との唯一の違いは流動すること。",
  ui_story_5084_50841400_109_dialog_content = "このままでは、私たちの命も自身で掌握できなくなるのではないのか？\nなぜ、ここへ連れて来た？",
  ui_story_5084_50841400_110_dialog_content = "ビクトリアか！？",
  ui_story_5084_50841400_111_dialog_content = "ハハハ…アハハハハハ！!",
  ui_story_5084_50841400_112_dialog_content = "さすがだ、ビクトリア・ワラーキ！やり遂げたか！ハハハハハ…",
  ui_story_5084_50841400_113_dialog_content = "カロンも…",
  ui_story_5084_50841400_114_dialog_content = "…クラビス、私たちはやり遂げたのだな…",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>回想を終えたヴィルヘルムが身体を起こした時、そこはもう棺の中ではなかった。\n目の前の原始の河を眺めながら、ヴィルヘルムはその止まることのない流れに足を踏み入れた</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>彼自身によってかき乱された因果がその身体にまとわりつき――\nヴィルヘルムを「真理の確定点」へと誘っていく</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>すると――</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>ビクトリアの投げ入れた教典は「障害物」――\n河に横たわる「死者」に行く手を阻まれ、漂うことを止めた</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>裏切られ、死を遂げたヴィルヘルムという名の、運命の扉に引き入れられた者は…\n神秘の流れの中で目を覚ました</color>",
  ui_story_5084_50841400_120_dialog_content = "…！？",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>その時、自分の足にせき止められている紅血の教典が\n困惑するヴィルヘルムの目に留まった</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>声なき召喚を受けたかのように、\n何も書かれていない教典のページをめくると、そこに文字が浮かび上がる――</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>「河に流されてきた教典が死したヴィルヘルムの足に当たり、\n血の一族の若者は砕かれた指輪の破片に封じ込められた一滴の血によって再び目を覚ました。」</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>「…その時、自分の足にせき止められている紅血の教典が\n困惑するヴィルヘルムの目に留まった。」</color>",
  ui_story_5084_50841400_125_dialog_content = "あ！！",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>「驚いたヴィルヘルムは背後の河へ倒れ込み、乱され、しぶきを上げた河の水は\nその身体を濡らすとともに、あらゆる因果が彼を染め上げた。」</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>「河の中に座り込むヴィルヘルムは、いつの間にやら自分の手にもたらされた物に気づく。\n震えながら、それを見てみると――」</color>",
  ui_story_5084_50841400_128_dialog_content = "指輪…我がワラーキ家に代々伝わる指輪だ…",
  ui_story_5084_50841400_129_dialog_content = "いったい、どういうことだ…",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>「召喚を受けたヴィルヘルムは漂流の旅に出なければならない。真理を導く者として――」</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>「機が熟した時、ワラーキの墓所はおのずとビクトリアに扉を開く。\n真理の下僕ヴィルヘルムは必ずやビクトリアを導くだろう。」</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>「…そしてヴィルヘルムは来たりし時に眠っていた棺に横たわり、過去へと思いをはせた。」</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>「…己の使命が果たされた時、ビクトリアの翼は豊かに育ち、彼自身は安息を得られるのだろうか？」</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>「ヴィルヘルムが指輪に触れると、そこに封じ込められていた一滴の血が身体へと戻り、\n全身を巡った…懐かしい感覚がよみがえり、彼は深い眠りに就いた。」</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>「再び目を覚ました時、ヴィルヘルムは運命の交わる場所へと導かれていくだろう。」</color>",
  ui_story_5084_50841400_136_dialog_content = "ここは…",
  ui_story_5084_50841400_137_dialog_content = "ビクトリア様は敬虔が導いてくれるとおっしゃいましたが…",
  ui_story_5084_50841400_138_dialog_content = "私はこうしていけにえに…",
  ui_story_5084_50841400_139_dialog_content = "私はこのまま…",
  ui_story_5084_50841400_140_dialog_content = "…",
  ui_story_5084_50841400_141_dialog_content = "…真理の主？",
  ui_story_5084_50841400_142_dialog_content = "偉大なる真理の主！",
  ui_story_5084_50841400_143_dialog_content = "今…「ビクトリア様」と言ったか？",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>「河を流れる時間に始まりも終わりもなく、\nただ永遠に止まることのない輪となって流れてゆく。」</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>「ビクトリアが手を放すと、長い間彼女と共にあった教典は\nその神秘の流れの中へと落ち、そのまま流れていった…」</color>",
  ui_story_5084_50841400_146_dialog_content = "おかえりなさい。",
  ui_story_5084_50841400_147_dialog_content = "あれ？ロウソクがない！？",
  ui_story_5084_50841400_148_dialog_content = "ロウソクも「ファリア」の力の一部なの。",
  ui_story_5084_50841400_149_dialog_content = "ファリア、閉門！",
  ui_story_5084_50841400_150_dialog_content = "（そうか…星空の墓所って、あの時のワラーキの墓所だったんだ）",
  ui_story_5084_50841400_151_dialog_content = "「万門の鍵」、また会ったわね。",
  ui_story_5084_50841400_152_dialog_content = "ビクトリア様？",
  ui_story_5084_50841400_153_dialog_content = "フフ、ただの独り言よ。気にしないでちょうだい。",
  ui_story_5084_50841400_154_dialog_content = "…はい。",
  ui_story_5084_50841400_155_dialog_content = "メイ？",
  ui_story_5084_50841400_156_dialog_content = "お姉ちゃん？なんでいるの？",
  ui_story_5084_50841400_157_dialog_content = "パンが焼き上がった後、メイがいないことに気づきました。スカーレイさんの所だとは思いましたが、\nビクトリア様も皆もいるとは思いませんでした。",
  ui_story_5084_50841400_158_dialog_content = "あ、今パンって言ったような…？",
  ui_story_5084_50841400_159_dialog_content = "おいしいパンと芳醇なワイン…\n聖鳴祭のお料理はお姉ちゃんが準備したんだ！",
  ui_story_5084_50841400_160_dialog_content = "なんだか急にお腹が減ってきた…",
  ui_story_5084_50841400_161_dialog_content = "スカーレイ、あなたも祝典に参加するわね？",
  ui_story_5084_50841400_162_dialog_content = "はい。ビクトリア様のお招きとあらば、そういたしましょう。",
  ui_story_5084_50841400_163_dialog_content = "そろそろお時間です、ビクトリア様。\n他の者たちも村に集まっている頃です。",
  ui_story_5084_50841400_164_dialog_content = "真理結社の人は全員来るの？",
  ui_story_5084_50841400_165_dialog_content = "この間誘った時は、乗り気じゃなかったようだけど、\n今はなんだか嬉しそうだね？",
  ui_story_5084_50841400_166_dialog_content = "真理結社の皆とは、しょっちゅう会えるわけじゃないし、\nよく知った友だちに囲まれて過ごす時間は楽しいから。",
  ui_story_5084_50841400_167_dialog_content = "3年に1度の真理結社の祭典にようこそ。",
  ui_story_5084_50841400_168_dialog_content = "3年の時を経て、私たちはまたアイオリアの探索に一歩近づいた。\nそれは真理の主に近づいたことでもある。",
  ui_story_5084_50841400_169_dialog_content = "私たちは等しく真理の主を崇め、成員の出身の尊卑を問わず、\n永久に変わらぬ戒律も認めない。",
  ui_story_5084_50841400_170_dialog_content = "持って生まれたものを守り続ける者も、\n過去の縛りから抜け出そうとする者も、使命を果たすことに努める者も…",
  ui_story_5084_50841400_171_dialog_content = "絶えず成長し、悟りを積み重なるからこそ、\n真理に近づく途上で輝きを放つことができる。",
  ui_story_5084_50841400_172_dialog_content = "今の真理結社は、着実に真理の祝福を受けた道を歩んでいる。",
  ui_story_5084_50841400_173_dialog_content = "真理結社と深いつながりをもつ血の一族は、\nアストラ大陸の外ですでに準備を整えている。",
  ui_story_5084_50841400_174_dialog_content = "この私が――皆を真理の主が降臨するその時へと導きましょう。",
  ui_story_5084_50841400_175_dialog_content = "暗潮の危機が訪れた時、教典は大きな変革が到来すると啓示した。",
  ui_story_5084_50841400_176_dialog_content = "その時私が見定めた変革者は、今も成長を続けている。",
  ui_story_5084_50841400_177_dialog_content = "錠は暗面に現れる。その鍵は私が彼の地へと携えていきましょう。\n真理の主と共に神の国を再建するのよ。",
  ui_story_5084_50841400_178_dialog_content = "その旅は暗面を横断し、昼夜を逆転させるものとなる。\n真理結社は盟友として、光霊が危機を脱するのを再び導くでしょう。",
  ui_story_5084_50841400_179_dialog_content = "この後は、祝典を存分に楽しんで。",
  ui_story_5084_50841400_180_dialog_content = "私は主から、皆に真理のあふれた食事とお酒を授ける栄誉を賜った。",
  ui_story_5084_50841400_181_dialog_content = "互いの悟りを思う存分語り合ってちょうだい。",
  ui_story_5084_50841400_182_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50841400_183_dialog_content = "真理の祝福あれ。",
  ui_story_5084_50841400_184_dialog_content = "パソロ、どうしてファウストを見てるの？\nファウストに何かついてる？",
  ui_story_5084_50841400_185_dialog_content = "あのぉ…フ、ファウストさん…死んだ父さんと母さんの「霊魂」について、\nファウストさんなら新しい答えを知ってるかもしれないって、スカーレイさんが…",
  ui_story_5084_50841400_186_dialog_content = "「新しい答え」なら、ネイルスに聞くといいよ。\nここ最近で収穫が最も大きかったのは彼だからね。",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>ゴロゴロゴロ――</color>",
  ui_story_5084_50841400_188_dialog_content = "PlayerName、止めて！",
  ui_story_5084_50841400_189_dialog_content = "うわ！早すぎるよ…ネイルスの方に転がって行っちゃった！",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5084_50841400_191_dialog_content = "ネイルス、悪かったわね！ケガはない？",
  ui_story_5084_50841400_192_dialog_content = "大丈夫です、セファーさん。もし私を痛めつけたいのなら、\nそのイバラで力いっぱい殴ってください。",
  ui_story_5084_50841400_193_dialog_content = "あんたねえ、今夜は絶対に自分を傷つけないって、さっき言ってなかった？\nそれって…服を新しくしたから！？",
  ui_story_5084_50841400_194_dialog_content = "ファウストさんが…ネイルスさんなら「霊魂」について、\n新しい悟りを教えてくれると言ってたんですが…",
  ui_story_5084_50841400_195_dialog_content = "悟り、ですか…確かに私は導師から多くの教えを賜りました…",
  ui_story_5084_50841400_196_dialog_content = "「霊魂」とは精神が凝固したものだと、私は思います。\n精神さえ存在していれば、人は永遠に消えないのではないでしょうか。",
  ui_story_5084_50841400_197_dialog_content = "そうなんですか…だったら、亡くなった人にも会えますか？",
  ui_story_5084_50841400_198_dialog_content = "それについては…ビクトリア様なら、ご存知かもしれません。",
  ui_story_5084_50841400_199_dialog_content = "おや、久しぶりだな。神聖な気配を漂わせているではないか…",
  ui_story_5084_50841400_200_dialog_content = "お久しぶりです、トラモンさん。",
  ui_story_5084_50841400_201_dialog_content = "お前…ビクトリア様と共に何か経験したのか？",
  ui_story_5084_50841400_202_dialog_content = "光栄なことに、ご一緒させていただきました。今回の旅で、私は大切な師と出会い、\nその方のおかげで真理の主による聖化を得ることができました…",
  ui_story_5084_50841400_203_dialog_content = "まさか苦行者にも悟りを啓く日が訪れるとはな。\nで、その導師とやらも来ているのか？",
  ui_story_5084_50841400_204_dialog_content = "導師は…恥ずかしながら、存じ上げません…",
  ui_story_5084_50841400_205_dialog_content = "ビクトリア様、ネイルスさんが言ってたんです。\n「精神さえ存在していれば、人は永遠に消えない」と…",
  ui_story_5084_50841400_206_dialog_content = "亡くなった両親はずっと私の側にいてくれてる…\nそうなんですよね？",
  ui_story_5084_50841400_207_dialog_content = "光霊は信仰の光が集まって誕生した種族よ。\n光霊の精神の力は、それより高位にある河の流れを源とするの。",
  ui_story_5084_50841400_208_dialog_content = "ご両親が亡くなった後、その精神の一部が河の流れに帰ったのならば、\nあなたは2人を祝福してあげなくてはいけないわ。",
  ui_story_5084_50841400_209_dialog_content = "両親を祝福する…",
  ui_story_5084_50841400_210_dialog_content = "ビクトリア様、ありがとうございます。\nもう少し自分で考えてみます…",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>日増しに大きくなっていく真理結社を見ながら、\nビクトリアは深い感慨に浸っていた</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>結社の今があるのは、あの時のヴィルヘルムと今の自分が共に\n過去の自分の行く手にあった障害物を取り除いたからだ</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>そして2人が運命として受けた導きは過去の、もしくは未来の誰かが、\n時空の流れにもまれながら、全力で伝えた真心だったのかもしれない</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>ビクトリアは運命の流れの中で、共に歩む無数の人々の姿を見た。\nその存在は少しずつ真理を探究し続ける彼女の勇気になっていった</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>そのすべてを、時の河の流れに漂うあの人も見守ってくれていることだろう</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>河の流れが変わり、教典に物語が刻まれる。\nだがこの瞬間、ビクトリアにはどうしても、すぐにページをめくる気にはなれなかった</color>",
  ui_story_5084_50841400_217_dialog_content = "ふむ…俺と同じで独り静かに修行することを好むか。",
  ui_story_5084_50841400_218_dialog_content = "ならば、真理結社の祭典に顔を出さんのも理解できるな。\n隠者とはそういうものだ。",
  ui_story_5084_50841400_219_dialog_content = "隠者にも組織があるの？",
  ui_story_5084_50841400_220_dialog_content = "組織というほどではないが…独りで静かに修行することを好む一派は\n1915年のワラーキ村で生まれ、謎の男の信者が確立したと言われている。",
  ui_story_5084_50841400_221_dialog_content = "ビクトリア様に教えていただかなかったのか？",
  ui_story_5084_50841400_222_dialog_content = "光霊の集まる村に出入りするお前たちと違って、\n隠者を名乗る者には、私も野や山で時どきお目にかかるくらいだがな。",
  ui_story_5084_50841400_223_dialog_content = "隠者の方々は…普段、何をされているのですか？",
  ui_story_5084_50841400_224_dialog_content = "広々とした何もない場所か、人目につかない場所を探し…",
  ui_story_5084_50841400_225_dialog_content = "それから？",
  ui_story_5084_50841400_226_dialog_content = "そこで、頭の中を空にするのだ。",
  ui_story_5084_50841400_227_dialog_content = "それって、ただ読書や勉強したくないだけじゃ…",
  ui_story_5084_50841400_228_dialog_content = "いや、これは隠者修行の大家と呼ばれる方のやり方だ。\nその方には読んだことのない本などないらしい。",
  ui_story_5084_50841400_229_dialog_content = "何もない所にいるから、その人はきっと読みたくても本がないんじゃないかな？\nでも君たちは、本があるのに、ただ読んでないだけに思えるけど…",
  ui_story_5084_50841400_230_dialog_content = "その方はきっと大そう立派な方なのでしょうね！\nお名前は何とおっしゃるのですか？",
  ui_story_5084_50841400_231_dialog_content = "彼の名を知る者はいない。ただ俺は会ったことがあるぞ。",
  ui_story_5084_50841400_232_dialog_content = "スラっと背が高く、古の貴族のような雰囲気のある方だ…",
  ui_story_5084_50841400_233_dialog_content = "いつも黒い帽子をかぶり、赤みがかった黒いマントを羽織って、\n黒い馬を引いているのでな。",
  ui_story_5084_50841400_234_dialog_content = "…？",
  ui_story_5084_50841400_235_dialog_content = "その方は行先や居場所を他人に知らせず、各地を旅して歩いている。\n古い知人に会える時を待っているのだという者もいる。",
  ui_story_5084_50841400_236_dialog_content = "まさか…導師！？",
  ui_story_5084_50841400_237_dialog_content = "ん？誰だって？",
  ui_story_5084_50841400_238_dialog_content = "その人が待ってる人って…",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>「すべてにケリがついたら、またここで会おう。」\nあの時、彼はそう言った</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>ビクトリアは窓辺に立ったまま、時の流れの向こう側にいる、\n真理を追い求める人々の姿を見つめていた</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>彼らはまるで夜空に浮かぶ星々のように、光り輝くものもいれば、今はひと休みしているものもいる。\nだが、すべての星が自らのやり方で真理の意味を読み解こうとしている。</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>真理とは、あのはるか遠くに光る星を追うように、心の目をもってこそ\n見えるものであることをビクトリアは知っていた。</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>彼はその途上に現れたにすぎない。\n後に続く者をさらに先へと導いていくために。</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>窓の外で彼は軽くため息をついた。今の真理結社の者たちは皆、\n彼にとって子どもも同然の存在だ。</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>彼らの行く道にどんな困難が待ち受けていようとも、暗闇が行く手を阻もうとしたその時、\nビクトリアは必ず明かりを点してくれるだろう。</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>だが、窓辺にたたずむビクトリアもまた、\n孤独な探究者にすぎないことを彼だけは知っていた。</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>ビクトリアは目を閉じて、心の声を夜空に響かせた。</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>独り静かに行う修行も、結社の喧騒の中に身を置くことも、\n同じく真理に通ずる道なのだと。</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>「真理とは、あくなき探究なのだ」――彼がつぶやく</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>「その探究の旅路で、私は君たちを見守り、導いていこう。」</color>"
}
return config
